) as (
values
  (47, 'ancient-agora-athens', 'Αρχαία Αγορά της Αθήνας', ARRAY['Αγορά', 'Δημόσιος χώρος', 'Ιερό', 'Διοικητικό κέντρο']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Οργανώθηκε ως βασικός δημόσιος χώρος από τα μέσα του 6ου αιώνα π.Χ.', '6ος αιώνας π.Χ. - Ρωμαϊκή περίοδος', 'Δεν καταστράφηκε σε μία μόνο φάση· η χρήση της μεταβλήθηκε σταδιακά στους μεταγενέστερους χρόνους.', 'Δεν χτίστηκε από ένα μόνο πρόσωπο· αναπτύχθηκε σταδιακά από την αθηναϊκή πόλη-κράτος.', 'Πολιτικό, διοικητικό, εμπορικό, κοινωνικό, θρησκευτικό και πολιτιστικό κέντρο της αρχαίας Αθήνας.', 'Η Αρχαία Αγορά ήταν η καρδιά της αρχαίας Αθήνας. Εκεί συγκεντρώνονταν οι πολίτες, λειτουργούσαν δημόσια κτήρια, ιερά, στοές, καταστήματα και χώροι διοίκησης. Βρισκόταν βορειοδυτικά της Ακρόπολης, ανάμεσα στον Άρειο Πάγο και τον Αγοραίο Κολωνό.', 'Από βασικό κέντρο της κλασικής πόλης συνέχισε να χρησιμοποιείται και να μεταβάλλεται στους ελληνιστικούς και ρωμαϊκούς χρόνους.', 'easy', 'Εύκολη πρόσβαση, καθώς βρίσκεται στο κέντρο της Αθήνας, κοντά σε σταθμούς μετρό και σε άλλους αρχαιολογικούς χώρους.', 'Αθήνα / Αθηναϊκή πόλη-κράτος', ARRAY['Ακρόπολη', 'Άρειος Πάγος', 'Κεραμεικός', 'Στοά Αττάλου', 'Ναός Ηφαίστου']::text[], 'Γενική άποψη της Αρχαίας Αγοράς με τον Ναό του Ηφαίστου ή τη Στοά του Αττάλου.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_ancient_agora_athens']::text[], 'https://upload.wikimedia.org/wikipedia/commons/b/b8/Agora_-_Ath%C3%A8nes_%28GRA1%29_-_2022-03-26_-_97.jpg'),
  (63, 'temple-of-poseidon-sounion', 'Ναός Ποσειδώνα στο Σούνιο', ARRAY['Ναός', 'Ιερό', 'Οχυρωμένη θέση']::text[], ARRAY['Κλασική']::text[], '5ος αιώνας π.Χ.', 'Κλασική περίοδος - Ρωμαϊκή περίοδος', 'Ο χώρος έπαψε σταδιακά να λειτουργεί ως αρχαίο ιερό μετά την αρχαιότητα.', 'Δεν είναι γνωστός συγκεκριμένος αρχιτέκτονας· το ιερό συνδέεται με την αθηναϊκή πόλη-κράτος.', 'Λατρεία του Ποσειδώνα και έλεγχος ενός στρατηγικού θαλάσσιου σημείου της Αττικής.', 'Ο Ναός του Ποσειδώνα βρίσκεται στο ακρωτήριο Σούνιο, στο νοτιότερο άκρο της Αττικής. Το ιερό τέμενος καταλαμβάνει το υψηλότερο σημείο του οχυρωμένου ακρωτηρίου και είχε μεγάλη σημασία για τους Αθηναίους, επειδή βρισκόταν σε θέση που έλεγχε τους θαλάσσιους δρόμους του Αιγαίου.', 'Από λατρευτικό και στρατηγικό σημείο της αρχαίας Αθήνας μετατράπηκε σε αρχαιολογικό χώρο και τοπόσημο της Αττικής.', 'easy', 'Εύκολη πρόσβαση με αυτοκίνητο ή λεωφορείο, αλλά βρίσκεται αρκετά μακριά από το κέντρο της Αθήνας.', 'Αθήνα / Αττική', ARRAY['Φρούριο Σουνίου', 'Ιερό Αθηνάς Σουνιάδας', 'Αρχαίο λιμάνι Σουνίου']::text[], 'Ο ναός του Ποσειδώνα με φόντο τη θάλασσα ή το ηλιοβασίλεμα.', 'high', true, 'Manual-review import: mapped cleaned monument "Ναός Ποσειδώνα στο Σούνιο" to catalog_id 63 "Ναός Ποσειδώνα". Alternatives: 23: Ναός Απόλλωνος στην Αρχαία Κόρινθο (0.156); 31: Ναός Επικουρίου Απόλλωνος (0.156); 65: Ναός Απόλλωνα, Δίδυμα (0.156).', ARRAY['odysseus_sounion_poseidon']::text[], 'https://upload.wikimedia.org/wikipedia/commons/4/45/Greece_Cape_Sounion_BW_2017-10-09_10-12-43.jpg'),
  (16, 'eleusis-archaeological-site', 'Αρχαιολογικός χώρος Ελευσίνας', ARRAY['Ιερό', 'Λατρευτικό κέντρο', 'Μυστήρια']::text[], ARRAY['Μυκηναϊκή', 'Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Ο χώρος χρησιμοποιείται λατρευτικά ήδη από τη Μυκηναϊκή Εποχή.', 'Μυκηναϊκή Εποχή - τέλος 4ου αιώνα μ.Χ.', 'Η αρχαία λατρεία σταμάτησε σταδιακά προς το τέλος της αρχαιότητας.', 'Αναπτύχθηκε σε πολλές φάσεις από τους Ελευσίνιους και αργότερα από την αθηναϊκή πόλη.', 'Λατρεία της Δήμητρας και της Περσεφόνης και τέλεση των Ελευσίνιων Μυστηρίων.', 'Η Ελευσίνα ήταν ένα από τα σημαντικότερα λατρευτικά κέντρα του αρχαίου κόσμου. Εκεί τελούνταν τα Ελευσίνια Μυστήρια, μυστικές θρησκευτικές τελετές αφιερωμένες στη Δήμητρα και την Περσεφόνη. Ο χώρος απέκτησε πανελλήνια σημασία και συνδέθηκε άμεσα με την Ιερά Οδό που ένωνε την Αθήνα με την Ελευσίνα.', 'Από τοπικό ιερό εξελίχθηκε σε πανελλήνιο λατρευτικό κέντρο και σήμερα λειτουργεί ως αρχαιολογικός χώρος.', 'easy', 'Εύκολη πρόσβαση, καθώς βρίσκεται μέσα στη σύγχρονη Ελευσίνα.', 'Ελευσίνα / Αττική, αργότερα στενά συνδεδεμένη με την Αθήνα', ARRAY['Τελεστήριο', 'Μεγάλα Προπύλαια', 'Ιερά Οδός', 'Αρχαιολογικό Μουσείο Ελευσίνας']::text[], 'Άποψη του αρχαιολογικού χώρου με τα Προπύλαια ή το Τελεστήριο.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_eleusis']::text[], 'https://upload.wikimedia.org/wikipedia/commons/8/83/General_view_of_sanctuary_of_Demeter_and_Kore_and_the_Telesterion_%28Initiation_Hall%29%2C_center_for_the_Eleusinian_Mysteries%2C_Eleusis_%288191841684%29.jpg'),
  (198, 'temple-of-aphaia-aegina', 'Ναός Αφαίας Αίγινας', ARRAY['Ναός', 'Ιερό']::text[], ARRAY['Αρχαϊκή', 'Κλασική']::text[], 'Περίπου 500-490 π.Χ.', 'Αρχαϊκή - Κλασική περίοδος', 'Ο ναός υπέστη φθορές στους μεταγενέστερους χρόνους, αλλά η θέση του παρέμεινε γνωστή.', 'Δεν γνωρίζουμε συγκεκριμένο αρχιτέκτονα· συνδέεται με την κοινότητα της αρχαίας Αίγινας.', 'Λατρεία της θεότητας Αφαίας.', 'Ο Ναός της Αφαίας δεσπόζει σε πευκόφυτο λόφο στο βορειοανατολικό τμήμα της Αίγινας. Είναι το σημαντικότερο μνημείο του ιερού της Αφαίας και από τους πιο καλοδιατηρημένους αρχαίους ναούς στον ελλαδικό χώρο. Η λατρευτική δραστηριότητα στην περιοχή φαίνεται ότι υπήρχε ήδη από τη μυκηναϊκή εποχή.', 'Η βασική χρήση του ήταν λατρευτική· σήμερα λειτουργεί ως αρχαιολογικός χώρος.', 'easy', 'Εύκολη πρόσβαση με όχημα από την πόλη της Αίγινας.', 'Αρχαία Αίγινα', ARRAY['Κολώνα Αίγινας', 'Αρχαία πόλη Αίγινας']::text[], 'Ο ναός της Αφαίας πάνω στον λόφο με φόντο το φυσικό τοπίο.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_aphaia_aegina']::text[], 'https://upload.wikimedia.org/wikipedia/commons/9/90/Aegina_-_Temple_of_Aphaia_03.jpg'),
  (23, 'ancient-corinth-temple-of-apollo', 'Αρχαία Κόρινθος / Ναός Απόλλωνα', ARRAY['Πόλη', 'Ναός', 'Αγορά']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Ο Ναός του Απόλλωνα χρονολογείται περίπου στο 560 π.Χ.', 'Αρχαϊκή περίοδος - Ρωμαϊκή περίοδος', 'Η πόλη άλλαξε μορφή ιδιαίτερα μετά τη ρωμαϊκή αναδιοργάνωση.', 'Ο Ναός του Απόλλωνα ήταν έργο της κορινθιακής πόλης-κράτους.', 'Λατρεία του Απόλλωνα και ανάδειξη της ισχύος της αρχαίας Κορίνθου.', 'Η Αρχαία Κόρινθος ήταν μία από τις ισχυρότερες πόλεις-κράτη της αρχαίας Ελλάδας. Η θέση της, κοντά στον Ισθμό, της έδινε μεγάλο εμπορικό και στρατηγικό πλεονέκτημα. Ο Ναός του Απόλλωνα είναι από τα πιο χαρακτηριστικά και αναγνωρίσιμα μνημεία της πόλης.', 'Η περιοχή από ελληνική πόλη-κράτος μετατράπηκε αργότερα σε σημαντική ρωμαϊκή πόλη.', 'easy', 'Εύκολη πρόσβαση με όχημα, κοντά στον σύγχρονο οικισμό της Αρχαίας Κορίνθου.', 'Κόρινθος / Κορινθιακή πόλη-κράτος', ARRAY['Ακροκόρινθος', 'Αγορά Αρχαίας Κορίνθου', 'Κεγχρεές', 'Ισθμός']::text[], 'Οι κίονες του Ναού του Απόλλωνα με φόντο τον Ακροκόρινθο.', 'high', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['odysseus_ancient_corinth', 'odysseus_apollo_corinth']::text[], 'https://upload.wikimedia.org/wikipedia/commons/4/41/Ravel_1008.2.jpg'),
  (138, 'ancient-nemea', 'Αρχαία Νεμέα', ARRAY['Ιερό', 'Στάδιο', 'Πανελλήνιοι αγώνες']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική']::text[], 'Ο χώρος αναπτύχθηκε σταδιακά ως ιερό του Δία και κέντρο των Νέμεων Αγώνων.', 'Αρχαϊκή - Ελληνιστική περίοδος', 'Η λατρευτική και αγωνιστική χρήση σταμάτησε σταδιακά στους μεταγενέστερους χρόνους.', 'Δεν συνδέεται με έναν μόνο κτήτορα· οργανώθηκε ως πανελλήνιο ιερό.', 'Λατρεία του Δία και τέλεση των Νέμεων Αγώνων.', 'Η Αρχαία Νεμέα ήταν γνωστή για το ιερό του Δία και τους Νέμεους Αγώνες, έναν από τους μεγάλους πανελλήνιους αγώνες της αρχαιότητας. Ο χώρος περιλαμβάνει τον ναό του Δία, στάδιο και βοηθητικά κτήρια για τη λατρεία και τη φιλοξενία των αγώνων.', 'Από ενεργό ιερό και αγωνιστικό κέντρο μετατράπηκε σε αρχαιολογικό χώρο.', 'easy', 'Εύκολη πρόσβαση με όχημα, κοντά στη σύγχρονη Νεμέα.', 'Νεμέα / Περιοχή Αργολίδας και Κορινθίας', ARRAY['Ναός Δία', 'Στάδιο Νεμέας', 'Αρχαιολογικό Μουσείο Νεμέας', 'Κλεωνές']::text[], 'Ο Ναός του Δία ή η είσοδος του αρχαίου σταδίου.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_nemea']::text[], 'https://upload.wikimedia.org/wikipedia/commons/0/09/Nemea_Stadion_2008-09-12.jpg'),
  (31, 'temple-of-epicurius-apollo-bassae', 'Ναός Επικούριου Απόλλωνα στις Βάσσες', ARRAY['Ναός', 'Ιερό', 'UNESCO']::text[], ARRAY['Κλασική']::text[], 'Περίπου 420-400 π.Χ.', 'Κλασική περίοδος', 'Δεν καταστράφηκε πλήρως· σήμερα προστατεύεται ως μνημείο παγκόσμιας κληρονομιάς.', 'Αποδίδεται στον Ικτίνο.', 'Αφιέρωμα στον Απόλλωνα Επικούριο, δηλαδή στον Απόλλωνα ως βοηθό ή σωτήρα.', 'Ο Ναός του Επικούριου Απόλλωνα στις Βάσσες είναι από τα καλύτερα σωζόμενα μνημεία της κλασικής αρχιτεκτονικής. Ξεχωρίζει επειδή συνδυάζει δωρικά, ιωνικά και κορινθιακά στοιχεία και ήταν το πρώτο ελληνικό μνημείο που εντάχθηκε στον κατάλογο της UNESCO.', 'Από λατρευτικός ναός μετατράπηκε σε προστατευόμενο αρχαιολογικό μνημείο.', 'medium', 'Η πρόσβαση είναι μέτρια, επειδή βρίσκεται σε ορεινή τοποθεσία και απαιτεί διαδρομή με όχημα.', 'Φιγαλεία / Αρκαδία', ARRAY['Αρχαία Φιγαλεία', 'Λύκαιο Όρος', 'Ορεινή Αρκαδία']::text[], 'Ο ναός μέσα στο προστατευτικό στέγαστρο ή πανοραμική άποψη του μνημείου στο ορεινό τοπίο.', 'high', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['greek_unesco_epicurius_apollo', 'ephorate_epicurius_apollo']::text[], 'https://upload.wikimedia.org/wikipedia/commons/6/65/Temple_of_Apollo_Bassae_1982.jpg'),
  (57, 'ancient-messene', 'Αρχαία Μεσσήνη', ARRAY['Πόλη', 'Οχύρωση', 'Θέατρο', 'Στάδιο', 'Ιερό']::text[], ARRAY['Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Ιδρύθηκε το 369 π.Χ.', '4ος αιώνας π.Χ. - Ρωμαϊκή περίοδος', 'Η πόλη εγκαταλείφθηκε σταδιακά στους μεταγενέστερους χρόνους.', 'Ιδρύθηκε με πρωτοβουλία του Θηβαίου στρατηγού Επαμεινώνδα και των συμμάχων του.', 'Ίδρυση νέας πρωτεύουσας των ελεύθερων Μεσσηνίων μετά την απελευθέρωσή τους από τη σπαρτιατική κυριαρχία.', 'Η Αρχαία Μεσσήνη είναι μία από τις καλύτερα σωζόμενες αρχαίες πόλεις στην Ελλάδα. Χτίστηκε στους πρόποδες της Ιθώμης και περιλάμβανε ισχυρά τείχη, αγορά, θέατρο, Ασκληπιείο, στάδιο και γυμνάσιο. Ο χώρος δείχνει πολύ καθαρά πώς ήταν οργανωμένη μια ελληνιστική πόλη.', 'Από ζωντανή πόλη και πολιτικό κέντρο μετατράπηκε σταδιακά σε ερειπωμένο αρχαιολογικό χώρο.', 'easy', 'Εύκολη πρόσβαση με όχημα, αλλά ο χώρος είναι μεγάλος και χρειάζεται αρκετό περπάτημα.', 'Μεσσηνία / Μεσσηνιακή πόλη', ARRAY['Ιθώμη', 'Ασκληπιείο', 'Στάδιο', 'Γυμνάσιο', 'Οχυρώσεις Μεσσήνης']::text[], 'Το στάδιο ή πανοραμική άποψη της Αρχαίας Μεσσήνης με την Ιθώμη.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_messene_fortifications', 'efa_messene_guide']::text[], 'https://upload.wikimedia.org/wikipedia/commons/1/1d/Messeneasklepeion.jpg'),
  (215, 'palace-of-nestor', 'Ανάκτορο του Νέστορα', ARRAY['Ανάκτορο', 'Μυκηναϊκό κέντρο']::text[], ARRAY['Μυκηναϊκή']::text[], 'Η ακμή του ανακτόρου τοποθετείται περίπου στο 1300-1200 π.Χ.', '13ος αιώνας π.Χ.', 'Καταστράφηκε από μεγάλη πυρκαγιά στα τέλη του 13ου ή στις αρχές του 12ου αιώνα π.Χ.', 'Δεν γνωρίζουμε τον πραγματικό κτήτορα· συνδέεται με το μυκηναϊκό βασίλειο της Πύλου και παραδοσιακά με τον ομηρικό Νέστορα.', 'Διοικητικό, οικονομικό και πολιτικό κέντρο του μυκηναϊκού βασιλείου της Πύλου.', 'Το Ανάκτορο του Νέστορα στον Άνω Εγκλιανό είναι το καλύτερα σωζόμενο μυκηναϊκό ανακτορικό συγκρότημα της ηπειρωτικής Ελλάδας. Περιλάμβανε επίσημα διαμερίσματα, αποθήκες, εργαστήρια, αυλές, λουτρά και αρχεία με πινακίδες Γραμμικής Β΄.', 'Μετά την καταστροφή του δεν ξαναχτίστηκε ως ανάκτορο, γεγονός που βοήθησε στη διατήρηση των καταλοίπων.', 'easy', 'Εύκολη πρόσβαση με όχημα· ο χώρος προστατεύεται σήμερα με στέγαστρο.', 'Μυκηναϊκή Πύλος / Μεσσηνία', ARRAY['Θολωτοί τάφοι Πύλου', 'Τάφος Γρύπα-Πολεμιστή', 'Μυκηναϊκό νεκροταφείο', 'Αρχαιολογικό Μουσείο Χώρας', 'Θολωτός τάφος Πύλου A', 'Θολωτός τάφος Πύλου B', 'Θολωτός τάφος Πύλου Γ']::text[], 'Εσωτερική άποψη του στεγασμένου ανακτόρου ή η αίθουσα του θρόνου.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['efa_nestor_palace', 'odysseus_nestor_palace']::text[], 'https://upload.wikimedia.org/wikipedia/commons/b/bf/Ancient_Bath_in_Pylos.jpg'),
  (110, 'phaistos', 'Φαιστός', ARRAY['Ανάκτορο', 'Μινωικό κέντρο']::text[], ARRAY['Μινωική', 'Ιστορικοί χρόνοι']::text[], 'Το μινωικό ανάκτορο αναπτύχθηκε κυρίως στη 2η χιλιετία π.Χ.', 'Μινωική περίοδος', 'Η ανακτορική χρήση διακόπηκε μετά τις καταστροφές της μινωικής περιόδου, αλλά η περιοχή συνέχισε να έχει ιστορική σημασία.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· συνδέεται με τη μινωική ανακτορική εξουσία.', 'Διοικητικό, οικονομικό και θρησκευτικό κέντρο της νότιας Κρήτης.', 'Η Φαιστός ήταν ένα από τα σημαντικότερα μινωικά κέντρα της Κρήτης. Είναι χτισμένη σε χαμηλό λόφο στην πεδιάδα της Μεσαράς, σε θέση με στρατηγικό έλεγχο της περιοχής. Το ανάκτορο συνδέεται με διοίκηση, αποθήκευση, τελετουργίες και οικονομική οργάνωση.', 'Από μινωικό ανακτορικό κέντρο η περιοχή συνέχισε να χρησιμοποιείται σε μεταγενέστερες ιστορικές φάσεις.', 'easy', 'Εύκολη πρόσβαση με όχημα από τη Μεσαρά και το Ηράκλειο.', 'Μινωική Κρήτη / Περιοχή Μεσαράς', ARRAY['Αγία Τριάδα', 'Κομμός', 'Γόρτυνα']::text[], 'Η μεγάλη αυλή και τα επίπεδα του ανακτόρου με φόντο την πεδιάδα της Μεσαράς.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_phaistos']::text[], ''),
  (112, 'gortyna', 'Γόρτυνα', ARRAY['Πόλη', 'Νομικό μνημείο', 'Ρωμαϊκό κέντρο', 'Παλαιοχριστιανικό κέντρο']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή', 'Παλαιοχριστιανική']::text[], 'Η πόλη αναπτύχθηκε σταδιακά από τους αρχαίους χρόνους.', 'Αρχαϊκή περίοδος - Παλαιοχριστιανικοί χρόνοι', 'Η σημασία της μειώθηκε σταδιακά μετά την ύστερη αρχαιότητα.', 'Δεν χτίστηκε από ένα μόνο πρόσωπο· αναπτύχθηκε ως αρχαία κρητική πόλη.', 'Αστικό, διοικητικό, νομικό και θρησκευτικό κέντρο της Κρήτης.', 'Η Γόρτυνα ήταν μία από τις σημαντικότερες πόλεις της Κρήτης. Τα ερείπιά της απλώνονται σε μεγάλη έκταση και περιλαμβάνουν δημόσια κτήρια, ιερά, νεκροπόλεις και μνημεία διαφορετικών περιόδων. Είναι ιδιαίτερα γνωστή για τον περίφημο Κώδικα της Γόρτυνας, ένα από τα σημαντικότερα νομικά κείμενα της αρχαιότητας.', 'Από αρχαία κρητική πόλη εξελίχθηκε σε σημαντικό ρωμαϊκό και παλαιοχριστιανικό κέντρο.', 'easy', 'Εύκολη πρόσβαση με όχημα στην περιοχή της Μεσαράς.', 'Γόρτυνα / Κρήτη', ARRAY['Κώδικας Γόρτυνας', 'Ωδείο', 'Ναός Αγίου Τίτου', 'Ακρόπολη Γόρτυνας', 'Φαιστός']::text[], 'Ο χώρος με τον Κώδικα της Γόρτυνας ή ο ναός του Αγίου Τίτου.', 'high', true, 'Manual-review import: mapped cleaned monument "Γόρτυνα" to catalog_id 112 "Γόρτυνα / Γόρτυς". Alternatives: 122: Μινωικός χώρος Τυλίσου (0.055); 126: Κομμός / Μινωικό λιμάνι Κομμού (0.055); 212: Μινωικό νεκροταφείο και οικισμός Κούμασα (0.055).', ARRAY['odysseus_gortyna']::text[], 'https://upload.wikimedia.org/wikipedia/commons/a/a1/Gortys_R02.jpg'),
  (55, 'malia-palace', 'Ανάκτορο Μαλίων', ARRAY['Ανάκτορο', 'Μινωικό κέντρο']::text[], ARRAY['Μινωική']::text[], 'Το ανάκτορο αναπτύχθηκε στη μινωική περίοδο.', 'Μινωική περίοδος', 'Η χρήση του μεταβλήθηκε μετά τις καταστροφές και την παρακμή του μινωικού ανακτορικού συστήματος.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· συνδέεται με τη μινωική ανακτορική οργάνωση.', 'Διοικητικό, οικονομικό και θρησκευτικό κέντρο.', 'Το Ανάκτορο των Μαλίων ήταν ένα από τα μεγάλα μινωικά ανακτορικά κέντρα της Κρήτης. Ο χώρος περιλαμβάνει αυλές, αποθήκες, τελετουργικούς χώρους και δρόμους πομπών, στοιχεία που δείχνουν οργανωμένη διοίκηση και λατρευτική δραστηριότητα.', 'Από μινωικό ανακτορικό κέντρο μετατράπηκε σε αρχαιολογικό χώρο.', 'easy', 'Εύκολη πρόσβαση, κοντά στον σύγχρονο οικισμό των Μαλίων.', 'Μινωική Κρήτη / Ανατολική Κρήτη', ARRAY['Μινωική πόλη Μαλίων', 'Κεντρική αυλή', 'Πομπικοί δρόμοι', 'Λασίθι']::text[], 'Η κεντρική αυλή ή οι πομπικοί δρόμοι του ανακτόρου.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_malia_palace']::text[], 'https://upload.wikimedia.org/wikipedia/commons/2/26/Kreta_-_Malia.jpg'),
  (113, 'zakros-palace', 'Ανάκτορο Ζάκρου', ARRAY['Ανάκτορο', 'Μινωικό κέντρο', 'Λιμάνι']::text[], ARRAY['Μινωική']::text[], 'Το ανάκτορο ανήκει στη μινωική ανακτορική περίοδο.', 'Μινωική περίοδος', 'Μετά την καταστροφή του δεν ακολούθησε έντονη νέα οικοδόμηση στον ίδιο χώρο.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· συνδέεται με τη μινωική ανακτορική εξουσία.', 'Κέντρο διοίκησης, θρησκείας και εμπορίου στην ανατολική Κρήτη.', 'Το Ανάκτορο της Ζάκρου ήταν σημαντικό μινωικό κέντρο στην ανατολική Κρήτη. Το ανάκτορο περιστοιχιζόταν από πόλη και συνδεόταν με θαλάσσιες εμπορικές επαφές. Η θέση του κοντά στη θάλασσα δείχνει τη σημασία του ως ανακτορικό και εμπορικό κέντρο.', 'Η περιοχή δεν ξαναχτίστηκε έντονα μετά την καταστροφή, γεγονός που βοήθησε στη διατήρηση των μινωικών καταλοίπων.', 'medium', 'Η πρόσβαση είναι μέτρια, επειδή βρίσκεται πιο απομονωμένα στην ανατολική Κρήτη.', 'Μινωική Κρήτη / Ανατολική Κρήτη', ARRAY['Κάτω Ζάκρος', 'Φαράγγι των Νεκρών', 'Αρχαιολογικό Μουσείο Σητείας']::text[], 'Πανοραμική άποψη του ανακτόρου με το φυσικό τοπίο της Κάτω Ζάκρου.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_zakros']::text[], ''),
  (4, 'delphi', 'Αρχαιολογικός χώρος Δελφών', ARRAY['Ιερό', 'Μαντείο', 'Πανελλήνιο κέντρο', 'UNESCO']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Ο χώρος αναπτύχθηκε σταδιακά ως μεγάλο ιερό του Απόλλωνα.', 'Αρχαϊκή περίοδος - Ρωμαϊκή περίοδος', 'Η μαντική και λατρευτική λειτουργία σταμάτησε σταδιακά στην ύστερη αρχαιότητα.', 'Δεν χτίστηκε από ένα μόνο πρόσωπο· αναπτύχθηκε από την τοπική κοινότητα, την Αμφικτυονία και αφιερώματα ελληνικών πόλεων.', 'Λατρεία του Απόλλωνα και λειτουργία του μαντείου των Δελφών.', 'Οι Δελφοί ήταν ένα από τα σημαντικότερα ιερά του αρχαίου ελληνικού κόσμου. Θεωρούνταν ο ομφαλός της γης και ήταν γνωστοί κυρίως για το μαντείο του Απόλλωνα, όπου η Πυθία έδινε χρησμούς σε πόλεις, βασιλιάδες και ιδιώτες.', 'Από ενεργό πανελλήνιο ιερό μετατράπηκε σε αρχαιολογικό χώρο παγκόσμιας σημασίας.', 'medium', 'Η πρόσβαση στην περιοχή είναι εύκολη με όχημα, αλλά ο αρχαιολογικός χώρος έχει ανηφορικά σημεία.', 'Φωκίδα / Πανελλήνιο ιερό', ARRAY['Ναός Απόλλωνα', 'Θέατρο Δελφών', 'Στάδιο Δελφών', 'Θόλος Αθηνάς Προναίας', 'Αρχαιολογικό Μουσείο Δελφών']::text[], 'Ο Ναός του Απόλλωνα με φόντο το δελφικό τοπίο.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_delphi']::text[], 'https://upload.wikimedia.org/wikipedia/commons/d/d5/Delphi%2C_Greece_-_panoramio.jpg'),
  (38, 'ancient-thebes-kadmeia', 'Αρχαία Θήβα / Καδμεία', ARRAY['Πόλη', 'Ακρόπολη', 'Μυκηναϊκό ανάκτορο']::text[], ARRAY['Μυκηναϊκή', 'Αρχαϊκή', 'Κλασική', 'Ελληνιστική']::text[], 'Το μυκηναϊκό ανάκτορο της Καδμείας χρονολογείται κυρίως στον 13ο αιώνα π.Χ.', 'Μυκηναϊκή περίοδος και ιστορικοί χρόνοι', 'Το μυκηναϊκό ανάκτορο καταστράφηκε περίπου γύρω στο 1200 π.Χ.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· ήταν κέντρο μυκηναϊκής ανακτορικής εξουσίας.', 'Διοικητικό και πολιτικό κέντρο της μυκηναϊκής Θήβας και αργότερα κέντρο της βοιωτικής πόλης.', 'Η αρχαία Θήβα ήταν μία από τις σημαντικότερες πόλεις της Βοιωτίας. Η Καδμεία, η ακρόπολη της πόλης, είχε ιδιαίτερη σημασία ήδη από τη Μυκηναϊκή Εποχή. Τα ευρήματα, όπως οι πινακίδες Γραμμικής Β΄, δείχνουν οργανωμένη διοίκηση και ισχυρή ανακτορική παρουσία.', 'Η περιοχή από μυκηναϊκό ανακτορικό κέντρο συνέχισε να αποτελεί πυρήνα της ιστορικής Θήβας.', 'easy', 'Εύκολη πρόσβαση, καθώς τα σημεία βρίσκονται μέσα στη σύγχρονη Θήβα.', 'Θήβα / Βοιωτία', ARRAY['Αρχαιολογικό Μουσείο Θηβών', 'Καδμεία', 'Μυκηναϊκά νεκροταφεία', 'Ισμήνιο Απόλλωνα']::text[], 'Άποψη από την Καδμεία ή το Αρχαιολογικό Μουσείο Θηβών με σχετικό μυκηναϊκό υλικό.', 'high', true, 'Manual-review import: mapped cleaned monument "Αρχαία Θήβα / Καδμεία" to catalog_id 38 "Αρχαία Θήβα/ Αρχαίο νεκροταφείο/τύμβος". Alternatives: 69: Αρχαιολογικό Μουσείο Θηβών (0.147); 77: Ιερό Καβείρων / θέατρο Καβείριων μυστηρίων (0.110); 14: Ιερό Αρτέμιδος Αυλιδείας (0.055).', ARRAY['museum_thebes_kadmeion']::text[], ''),
  (202, 'ancient-eretria', 'Αρχαία Ερέτρια', ARRAY['Πόλη', 'Θέατρο', 'Ιερά', 'Τείχη']::text[], ARRAY['Γεωμετρική', 'Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η πόλη άρχισε να αποκτά αστικό χαρακτήρα από τον 8ο αιώνα π.Χ.', '8ος αιώνας π.Χ. - Ρωμαϊκή περίοδος', 'Η πόλη γνώρισε πολλές ιστορικές φάσεις και μεταβολές.', 'Αναπτύχθηκε από την πόλη-κράτος των Ερετριέων.', 'Αστικό, εμπορικό, ναυτικό και θρησκευτικό κέντρο της Εύβοιας.', 'Η Ερέτρια ήταν μία από τις σημαντικότερες πόλεις της αρχαίας Εύβοιας. Από τον 8ο αιώνα π.Χ. απέκτησε αστικό χαρακτήρα και εξελίχθηκε σε ισχυρή πόλη με ναυτική και εμπορική παρουσία. Ο αρχαιολογικός χώρος περιλαμβάνει θέατρο, ιερά, οικίες, τείχη και δημόσια κτήρια.', 'Η περιοχή διατηρεί κατάλοιπα από διαφορετικές φάσεις της αρχαίας πόλης.', 'easy', 'Εύκολη πρόσβαση, κοντά στη σύγχρονη πόλη της Ερέτριας.', 'Ερέτρια / Εύβοια', ARRAY['Αρχαίο Θέατρο Ερέτριας', 'Ναός Δαφνηφόρου Απόλλωνα', 'Αρχαιολογικό Μουσείο Ερέτριας']::text[], 'Το αρχαίο θέατρο ή γενική άποψη του αρχαιολογικού χώρου.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_eretria']::text[], 'https://upload.wikimedia.org/wikipedia/commons/d/dc/%CE%95%CF%81%CE%AD%CF%84%CF%81%CE%B9%CE%B1%2C_Eretria.jpg'),
  (185, 'aigai-vergina', 'Αιγές / Βεργίνα', ARRAY['Πόλη', 'Ανάκτορο', 'Βασιλική νεκρόπολη', 'UNESCO']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική']::text[], 'Η περιοχή αναπτύχθηκε ως βασιλικό κέντρο των Μακεδόνων, με ιδιαίτερη ακμή στην κλασική περίοδο.', 'Αρχαϊκή - Ελληνιστική περίοδος', 'Η πολιτική σημασία της μειώθηκε όταν το κέντρο του μακεδονικού βασιλείου μετατοπίστηκε στην Πέλλα.', 'Συνδέεται με τη μακεδονική βασιλική δυναστεία.', 'Πρώτη πρωτεύουσα και βασιλικό κέντρο του μακεδονικού βασιλείου.', 'Οι Αιγές, κοντά στη σημερινή Βεργίνα, ήταν η πρώτη πρωτεύουσα του βασιλείου των Μακεδόνων. Ο χώρος περιλαμβάνει ανάκτορο, ιερά, θέατρο και βασιλική νεκρόπολη με μακεδονικούς τάφους. Είναι από τους σημαντικότερους αρχαιολογικούς χώρους της Μακεδονίας.', 'Από βασιλικό και πολιτικό κέντρο μετατράπηκε σε χώρο ταφικής μνήμης και σήμερα σε αρχαιολογικό χώρο παγκόσμιας σημασίας.', 'easy', 'Εύκολη πρόσβαση με όχημα από Βέροια και Θεσσαλονίκη.', 'Μακεδονικό βασίλειο', ARRAY['Ανάκτορο Αιγών', 'Βασιλικοί τάφοι', 'Θέατρο Αιγών', 'Μουσείο Βασιλικών Τάφων']::text[], 'Το ανάκτορο των Αιγών ή η είσοδος του Μουσείου Βασιλικών Τάφων.', 'high', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['unesco_aigai']::text[], ''),
  (18, 'pella', 'Αρχαιολογικός χώρος Πέλλας', ARRAY['Πόλη', 'Πρωτεύουσα', 'Αγορά', 'Οικίες', 'Ψηφιδωτά']::text[], ARRAY['Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η μεγάλη ακμή της Πέλλας ξεκινά στο δεύτερο μισό του 4ου αιώνα π.Χ.', '4ος αιώνας π.Χ. - Ελληνιστική περίοδος', 'Η σημασία της μειώθηκε μετά τις ιστορικές αλλαγές και τη ρωμαϊκή κυριαρχία.', 'Αναπτύχθηκε ως βασιλική πρωτεύουσα του μακεδονικού κράτους.', 'Διοικητικό, πολιτικό και οικονομικό κέντρο του μακεδονικού βασιλείου.', 'Η Πέλλα ήταν η μεγάλη πρωτεύουσα του μακεδονικού βασιλείου. Ήταν οργανωμένη με οικοδομικά τετράγωνα, μεγάλες οικίες, δημόσιους χώρους και εντυπωσιακά ψηφιδωτά. Συνδέεται άμεσα με την εποχή της ακμής της Μακεδονίας και με τον κόσμο του Φιλίππου Β΄ και του Μεγάλου Αλεξάνδρου.', 'Από πρωτεύουσα του μακεδονικού βασιλείου μετατράπηκε σταδιακά σε αρχαιολογικό χώρο.', 'easy', 'Εύκολη πρόσβαση με όχημα, κοντά στον σύγχρονο οικισμό και στο Αρχαιολογικό Μουσείο Πέλλας.', 'Μακεδονικό βασίλειο', ARRAY['Αγορά Πέλλας', 'Οικίες με ψηφιδωτά', 'Αρχαιολογικό Μουσείο Πέλλας', 'Ανάκτορο Πέλλας']::text[], 'Τα ψηφιδωτά της Πέλλας ή γενική άποψη του αρχαιολογικού χώρου.', 'high', true, 'Manual-review import: mapped cleaned monument "Αρχαιολογικός χώρος Πέλλας" to catalog_id 18 "Αρχαιολογικός χώρος Πέλλας". Alternatives: 54: Αρχαιολογικός χώρος Πέλλας (1.000); 1: Κορυφη Αυγο Παγγαιο (0.000); 2: Οκτάγωνο του Ανακτορικού Συγκροτήματος Γαλερίου (0.000).', ARRAY['odysseus_pella']::text[], 'https://upload.wikimedia.org/wikipedia/commons/e/e7/The_main_courtyard_of_the_House_of_Dionysos%2C_built_in_325-300_BC%2C_Ancient_Pella_%286914026352%29.jpg'),
  (67, 'dion', 'Δίον', ARRAY['Πόλη', 'Ιερό', 'Αρχαιολογικό πάρκο']::text[], ARRAY['Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Ο χώρος αναπτύχθηκε σταδιακά ως ιερό και πόλη των Μακεδόνων.', 'Κλασική - Ρωμαϊκή περίοδος', 'Η χρήση του χώρου μεταβλήθηκε σταδιακά στους μεταγενέστερους χρόνους.', 'Αναπτύχθηκε από τους Μακεδόνες και την τοπική κοινότητα.', 'Θρησκευτικό και πολιτικό κέντρο των Μακεδόνων, συνδεδεμένο με τη λατρεία του Δία και των Ολύμπιων θεών.', 'Το Δίον βρίσκεται στους βόρειους πρόποδες του Ολύμπου και είχε ιδιαίτερη σημασία για τους Μακεδόνες. Ο χώρος περιλαμβάνει ιερά, θέατρα, λουτρά, δρόμους και τμήματα της αρχαίας πόλης. Η σύνδεσή του με τον Όλυμπο το κάνει ένα από τα πιο χαρακτηριστικά αρχαιολογικά τοπία της Μακεδονίας.', 'Από ιερό και πόλη των Μακεδόνων μετατράπηκε σε οργανωμένο αρχαιολογικό πάρκο.', 'easy', 'Εύκολη πρόσβαση με όχημα, αλλά ο χώρος είναι μεγάλος και χρειάζεται περπάτημα.', 'Μακεδονικό βασίλειο / Πιερία', ARRAY['Όλυμπος', 'Ιερά Δίου', 'Αρχαία θέατρα', 'Αρχαιολογικό Μουσείο Δίου']::text[], 'Αρχαία ερείπια του Δίου με φόντο τον Όλυμπο.', 'high', true, 'Manual-review import: mapped cleaned monument "Δίον" to catalog_id 67 "Αρχαιολογικο Πάρκο Δίον". Alternatives: 184: Αρχαία Λείβηθρα (0.055); 186: Αρχαία Πύδνα (0.055); 1: Κορυφη Αυγο Παγγαιο (0.000).', ARRAY['odysseus_dion']::text[], 'https://upload.wikimedia.org/wikipedia/commons/4/49/Dion_archaeological_site_102.jpg'),
  (27, 'amphipolis', 'Αμφίπολη', ARRAY['Πόλη', 'Οχύρωση', 'Ταφικά μνημεία']::text[], ARRAY['Κλασική', 'Ελληνιστική', 'Ρωμαϊκή', 'Παλαιοχριστιανική']::text[], 'Η πόλη ιδρύθηκε το 438/7 π.Χ.', 'Κλασική περίοδος - Παλαιοχριστιανικοί χρόνοι', 'Η χρήση και μορφή της περιοχής άλλαξαν στους ρωμαϊκούς και παλαιοχριστιανικούς χρόνους.', 'Ιδρύθηκε ως αθηναϊκή αποικία.', 'Στρατηγικό, εμπορικό και πολιτικό κέντρο κοντά στον ποταμό Στρυμόνα.', 'Η Αμφίπολη ήταν μία από τις σημαντικότερες πόλεις της αρχαίας Μακεδονίας. Ιδρύθηκε σε στρατηγική θέση κοντά στον Στρυμόνα, σε περιοχή με μεγάλη σημασία για δρόμους, εμπόριο και πλουτοπαραγωγικές πηγές. Αργότερα εντάχθηκε στη μακεδονική σφαίρα επιρροής.', 'Από κλασική πόλη και αθηναϊκή αποικία εξελίχθηκε σε μακεδονικό, ρωμαϊκό και παλαιοχριστιανικό κέντρο.', 'easy', 'Εύκολη πρόσβαση με όχημα από την ευρύτερη περιοχή Σερρών και Καβάλας.', 'Αθηναϊκή αποικία, αργότερα Μακεδονία', ARRAY['Τείχη Αμφίπολης', 'Τάφος Βρασίδα', 'Αρχαιολογικό Μουσείο Αμφίπολης', 'Στρυμόνας', 'Τύμβος Καστά']::text[], 'Ο Λέων της Αμφίπολης ή άποψη των τειχών/περιοχής του Στρυμόνα.', 'high', true, 'Manual-review import: mapped cleaned monument "Αμφίπολη" to catalog_id 27 "[χωρίς όνομα]". Alternatives: 28: [χωρίς όνομα] (0.147); 34: Τάφος Βρασίδα (0.147); 20: Αρχαία Άργιλος (0.110).', ARRAY['odysseus_amphipolis']::text[], ''),
  (9, 'theatre-of-dionysus-athens', 'Θέατρο Διονύσου Ελευθερέως', ARRAY['Θέατρο', 'Ιερό', 'Λατρευτικός χώρος']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η πρώτη διαμόρφωση του θεατρικού χώρου συνδέεται με τον 6ο αιώνα π.Χ., ενώ η μνημειακή μορφή του ολοκληρώθηκε κυρίως τον 4ο αιώνα π.Χ.', '6ος αιώνας π.Χ. - Ρωμαϊκή περίοδος', 'Η χρήση του θεάτρου μειώθηκε σταδιακά μετά την αρχαιότητα και το μνημείο ερειπώθηκε.', 'Δεν αποδίδεται σε ένα μόνο πρόσωπο· η πλήρης διαμόρφωση του χώρου συνδέεται με δημόσια έργα της Αθήνας, ιδιαίτερα την εποχή του Λυκούργου.', 'Λατρεία του Διονύσου και τέλεση θεατρικών αγώνων στο πλαίσιο των διονυσιακών εορτών.', 'Το Θέατρο του Διονύσου βρίσκεται στη Νότια Κλιτύ της Ακρόπολης και θεωρείται ο σημαντικότερος θεατρικός χώρος της αρχαίας Αθήνας. Εκεί παρουσιάστηκαν τραγωδίες και κωμωδίες που συνδέονται με τη γέννηση του αρχαίου ελληνικού θεάτρου. Ο χώρος συνδυάζει λατρεία, δημόσια ζωή και πολιτισμό.', 'Από λατρευτικό και θεατρικό κέντρο της πόλης μετατράπηκε σταδιακά σε αρχαιολογικό μνημείο.', 'easy', 'Εύκολη πρόσβαση μέσα από τον αρχαιολογικό χώρο της Ακρόπολης και των Κλιτύων.', 'Αθήνα / Αθηναϊκή πόλη-κράτος', ARRAY['Ιερό Διονύσου', 'Στοά Ευμένους', 'Ασκληπιείο Νότιας Κλιτύος', 'Ακρόπολη']::text[], 'Γενική άποψη του θεάτρου με φόντο την Ακρόπολη ή τα καθίσματα της κερκίδας.', 'high', true, 'Manual-review import: mapped cleaned monument "Θέατρο Διονύσου Ελευθερέως" to catalog_id 9 "Θέατρο Διονύσου, Νότια Κλιτύς Ακρόπολης". Alternatives: 10: Στοά Ευμένους (0.220); 13: Ιερό/Ασκληπιείο κάτω από την Ακρόπολη (0.220); 191: Θέατρο Θορικού (0.195).', ARRAY['odysseus_south_slope_acropolis']::text[], 'https://upload.wikimedia.org/wikipedia/commons/e/ee/Athen_Akropolis_%2818512008726%29.jpg'),
  (74, 'sanctuary-of-artemis-brauron', 'Ιερό Αρτέμιδος Βραυρώνας', ARRAY['Ιερό', 'Λατρευτικό κέντρο']::text[], ARRAY['Αρχαϊκή', 'Κλασική']::text[], 'Το ιερό αναπτύχθηκε κυρίως στους αρχαϊκούς και κλασικούς χρόνους, πάνω σε περιοχή με παλαιότερη κατοίκηση.', 'Αρχαϊκή - Κλασική περίοδος', 'Η λατρευτική χρήση σταμάτησε σταδιακά στους μεταγενέστερους χρόνους.', 'Δεν είναι γνωστός συγκεκριμένος κτήτορας· το ιερό συνδέεται με την αθηναϊκή Αττική και τον αρχαίο δήμο των Φιλαϊδών.', 'Λατρεία της Αρτέμιδος Βραυρωνίας και τελετουργίες που σχετίζονταν κυρίως με γυναίκες και κορίτσια.', 'Το Ιερό της Αρτέμιδος στη Βραυρώνα ήταν ένα από τα σημαντικότερα ιερά της Αττικής. Βρισκόταν κοντά σε υγροτοπική περιοχή και περιλάμβανε ναό, στοά και άλλα λατρευτικά κτίσματα. Η λατρεία της Βραυρωνίας Αρτέμιδος είχε ιδιαίτερη σχέση με τη μετάβαση των κοριτσιών στην ενήλικη ζωή.', 'Από ενεργό αρχαίο ιερό μετατράπηκε σε αρχαιολογικό χώρο και μουσείο της περιοχής.', 'easy', 'Εύκολη πρόσβαση με αυτοκίνητο· το μουσείο βρίσκεται πολύ κοντά στον αρχαιολογικό χώρο.', 'Βραυρώνα / Αττική', ARRAY['Αρχαιολογικό Μουσείο Βραυρώνας', 'Στοά Βραυρώνας', 'Ναός Αρτέμιδος']::text[], 'Η στοά του ιερού ή γενική άποψη του χώρου με το φυσικό τοπίο της Βραυρώνας.', 'high', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['odysseus_brauron_museum']::text[], 'https://upload.wikimedia.org/wikipedia/commons/4/4a/Brauron-2.jpg'),
  (100, 'aigosthena-fortress', 'Αρχαίο Φρούριο Αιγοσθένων', ARRAY['Φρούριο', 'Οχύρωση', 'Πόλη']::text[], ARRAY['Κλασική', 'Ελληνιστική', 'Ρωμαϊκή', 'Βυζαντινή']::text[], 'Β΄ μισό του 4ου αιώνα π.Χ.', '4ος αιώνας π.Χ. - Μεταβυζαντινοί χρόνοι', 'Το φρούριο υπέστη σημαντικές φθορές και καταρρεύσεις, μεταξύ άλλων από τον σεισμό του 1981, αλλά τμήματά του έχουν αναστηλωθεί.', 'Συνδέεται με τα αρχαία Αιγόσθενα, κώμη των Μεγάρων στην κλασική περίοδο.', 'Οχύρωση στρατηγικής παράκτιας θέσης στον Κορινθιακό κόλπο.', 'Το Φρούριο των Αιγοσθένων δεσπόζει στον ανατολικό όρμο του Κορινθιακού κόλπου, στο σημερινό Πόρτο Γερμενό. Είναι ένα από τα καλύτερα διατηρημένα αρχαία φρούρια στον ελλαδικό χώρο και σώζει εντυπωσιακούς πύργους και τμήματα τειχών.', 'Η θέση χρησιμοποιήθηκε από τους αρχαίους έως και τους βυζαντινούς και μεταβυζαντινούς χρόνους.', 'easy', 'Εύκολη οδική πρόσβαση μέχρι την περιοχή· απαιτείται περπάτημα μέσα στον αρχαιολογικό χώρο.', 'Αιγόσθενα / Μέγαρα, αργότερα Κοινό Βοιωτών', ARRAY['Ακρόπολη Αιγοσθένων', 'Νοτιοανατολικός πύργος', 'Παλαιοχριστιανική βασιλική']::text[], 'Ο αναστηλωμένος πύργος ή πανοραμική άποψη του φρουρίου με τον Κορινθιακό κόλπο.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_aigosthena']::text[], 'https://upload.wikimedia.org/wikipedia/commons/1/16/Aigosthena_fortifications.jpg'),
  (188, 'poseidon-sanctuary-kalaureia', 'Ιερό Ποσειδώνα Καλαυρείας', ARRAY['Ιερό', 'Αρχαία πόλη', 'Λατρευτικό κέντρο']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική']::text[], 'Το ιερό αναπτύχθηκε στους αρχαϊκούς και κλασικούς χρόνους.', 'Αρχαϊκή - Ελληνιστική περίοδος', 'Η λατρευτική χρήση εγκαταλείφθηκε σταδιακά μετά την αρχαιότητα.', 'Δεν συνδέεται με έναν γνωστό κτήτορα· ανήκε στην αρχαία Καλαυρεία του Πόρου.', 'Λατρεία του Ποσειδώνα και λειτουργία σημαντικού ιερού στον Σαρωνικό.', 'Το Ιερό του Ποσειδώνα βρίσκεται σε υψόμετρο περίπου 190 μέτρων στην Καλαυρεία του Πόρου. Ο χώρος περιλάμβανε τον ναό του Ποσειδώνα, στοές, αγορά και άλλα κτήρια. Η θέση του το κάνει σημαντικό σημείο για την αρχαία ιστορία του Σαρωνικού.', 'Από λατρευτικό κέντρο έγινε αρχαιολογικός χώρος.', 'medium', 'Προσβάσιμο με όχημα και μικρή διαδρομή στο νησί του Πόρου.', 'Καλαυρεία / Πόρος', ARRAY['Αρχαία πόλη Καλαυρείας', 'Στοές', 'Βουλευτήριο', 'Ασκληπιείο ή Ηρώο']::text[], 'Γενική άποψη του ιερού με το φυσικό τοπίο του Πόρου.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_kalaureia_poseidon']::text[], ''),
  (192, 'franchthi-cave', 'Σπήλαιο Φράγχθι', ARRAY['Σπήλαιο', 'Προϊστορικός χώρος', 'Οικιστική θέση']::text[], ARRAY['Παλαιολιθική', 'Μεσολιθική', 'Νεολιθική']::text[], 'Δεν είναι κτίσμα· η χρήση του ξεκινά στην Ανώτερη Παλαιολιθική.', 'Περίπου 40.000 π.Χ. - Νεολιθική περίοδος', 'Η κατοίκηση εγκαταλείφθηκε σταδιακά στους προϊστορικούς χρόνους.', 'Δεν χτίστηκε από κάποιον· είναι φυσικό σπήλαιο που χρησιμοποιήθηκε από προϊστορικές κοινότητες.', 'Κατοίκηση, καταφύγιο, δραστηριότητες καθημερινής ζωής και ταφικές πρακτικές σε προϊστορικές περιόδους.', 'Το Σπήλαιο Φράγχθι στη νοτιοδυτική Αργολίδα είναι ένας από τους σημαντικότερους προϊστορικούς χώρους της Ελλάδας. Η μεγάλη διάρκεια χρήσης του το κάνει πολύτιμο για την κατανόηση της μετάβασης από κυνηγετικές-τροφοσυλλεκτικές κοινωνίες στη νεολιθική ζωή.', 'Από προϊστορικός χώρος κατοίκησης έγινε αρχαιολογικός χώρος με ερευνητική και εκπαιδευτική σημασία.', 'medium', 'Η πρόσβαση στην είσοδο είναι δυνατή, αλλά η είσοδος στο σπήλαιο μπορεί να είναι περιορισμένη· χρειάζεται έλεγχος πριν την επίσκεψη.', 'Προϊστορική Αργολίδα', ARRAY['Κοιλάδα Αργολίδας', 'Προϊστορικά ευρήματα Ερμιονίδας']::text[], 'Η είσοδος του σπηλαίου με θέα στον κόλπο της Κοιλάδας.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_franchthi_cave']::text[], 'https://upload.wikimedia.org/wikipedia/commons/5/57/Franchthi_Cave_from_Koilada_Argolidas.jpg'),
  (107, 'lerna-house-of-tiles', 'Λέρνα / Οικία των Κεράμων', ARRAY['Προϊστορικός οικισμός', 'Μνημειακό κτήριο']::text[], ARRAY['Πρωτοελλαδική', 'Εποχή Χαλκού']::text[], 'Η Οικία των Κεράμων χρονολογείται στην Πρωτοελλαδική ΙΙ περίοδο, περίπου στην 3η χιλιετία π.Χ.', 'Πρωτοελλαδική περίοδος', 'Το κτήριο καταστράφηκε από πυρκαγιά.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· συνδέεται με την οργανωμένη προϊστορική κοινότητα της Λέρνας.', 'Πιθανό διοικητικό ή κεντρικό κτήριο του οικισμού.', 'Η Λέρνα είναι σημαντικός προϊστορικός οικισμός της Αργολίδας. Το πιο γνωστό της μνημείο είναι η Οικία των Κεράμων, ένα μεγάλο ορθογώνιο κτήριο που πήρε το όνομά του από τα πολλά κεραμίδια της στέγης που βρέθηκαν στην ανασκαφή.', 'Μετά την καταστροφή του κτηρίου η περιοχή συνέχισε να έχει προϊστορικές φάσεις κατοίκησης.', 'easy', 'Σχετικά εύκολη πρόσβαση με όχημα στην περιοχή της Λέρνας.', 'Προϊστορική Αργολίδα', ARRAY['Οικία των Κεράμων', 'Προϊστορικός οικισμός Λέρνας']::text[], 'Τα κατάλοιπα της Οικίας των Κεράμων ή γενική άποψη του προϊστορικού χώρου.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_lerna']::text[], 'https://upload.wikimedia.org/wikipedia/commons/c/c4/Lerna1.JPG'),
  (32, 'mount-lykaion-sanctuary-zeus', 'Λύκαιο Όρος / Ιερό Δία', ARRAY['Ιερό', 'Βωμός', 'Αθλητικός χώρος']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική']::text[], 'Το ιερό αναπτύχθηκε σε μακρά διάρκεια, με κύρια χρήση στους ιστορικούς χρόνους.', 'Αρχαϊκή - Ελληνιστική περίοδος', 'Η λατρεία εγκαταλείφθηκε σταδιακά μετά την αρχαιότητα.', 'Δεν συνδέεται με έναν κτήτορα· ήταν ιερό των Αρκάδων αφιερωμένο στον Δία.', 'Λατρεία του Δία Λυκαίου και τέλεση τελετουργιών και αγώνων.', 'Το Λύκαιο Όρος ήταν ένα από τα σημαντικότερα ιερά της Αρκαδίας. Οι Αρκάδες το αποκαλούσαν και Όλυμπο ή Ιερά Κορυφή. Ο χώρος περιλάμβανε ιερό του Δία, βωμό και εγκαταστάσεις που συνδέονται με τη λατρεία και τους αγώνες.', 'Από ορεινό λατρευτικό κέντρο έγινε αρχαιολογικός και ερευνητικός χώρος.', 'hard', 'Η πρόσβαση είναι πιο δύσκολη λόγω ορεινής θέσης και απαιτεί κατάλληλη διαδρομή.', 'Αρκαδία / Αρκάδες', ARRAY['Βωμός Δία', 'Στάδιο ή ιππόδρομος', 'Ιερό Δέσποινας στη Λυκόσουρα']::text[], 'Πανοραμική άποψη του ορεινού ιερού ή του βωμού στην κορυφή.', 'high', false, 'Imported from cleaned 217 dataset. Match method: fuzzy (0.740).', ARRAY['odysseus_mount_lykaion']::text[], 'https://upload.wikimedia.org/wikipedia/commons/d/d9/Lykaion_looking_East.jpg'),
  (92, 'pavlopetri', 'Παυλοπέτρι', ARRAY['Βυθισμένη πόλη', 'Προϊστορικός οικισμός']::text[], ARRAY['Προϊστορική', 'Εποχή Χαλκού']::text[], 'Η πόλη ανήκει σε προϊστορικές φάσεις της Εποχής του Χαλκού.', 'Εποχή του Χαλκού', 'Ο οικισμός βυθίστηκε και σήμερα τα κατάλοιπα βρίσκονται κάτω από τη θάλασσα.', 'Δεν είναι γνωστοί οι κτήτορες· πρόκειται για προϊστορική παράκτια κοινότητα.', 'Παράκτια εγκατάσταση με οικιστική και πιθανώς εμπορική/ναυτική σημασία.', 'Το Παυλοπέτρι είναι ένας από τους πιο γνωστούς βυθισμένους προϊστορικούς οικισμούς της Ελλάδας. Βρίσκεται κοντά στην Ελαφόνησο και είναι σημαντικό γιατί σώζει πολεοδομικά κατάλοιπα κάτω από τη θάλασσα, δίνοντας εικόνα μιας αρχαίας παράκτιας εγκατάστασης.', 'Από κατοικημένος παράκτιος οικισμός μετατράπηκε σε ενάλιο αρχαιολογικό χώρο.', 'medium', 'Η περιοχή είναι προσβάσιμη από ξηρά, αλλά τα κατάλοιπα είναι υποθαλάσσια και η επίσκεψη απαιτεί προσοχή και σεβασμό στον ενάλιο χώρο.', 'Προϊστορική Λακωνία', ARRAY['Ελαφόνησος', 'Νότια Λακωνία', 'Βυθισμένοι οικισμοί Νότιας Πελοποννήσου']::text[], 'Αεροφωτογραφία της ακτής ή υποβρύχια απεικόνιση των καταλοίπων.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_underwater_peloponnese']::text[], ''),
  (194, 'diros-alepotrypa-cave', 'Σπήλαιο Διρού / Αλεπότρυπα', ARRAY['Σπήλαιο', 'Προϊστορικός χώρος', 'Ταφικός χώρος']::text[], ARRAY['Νεολιθική']::text[], 'Δεν είναι κτίσμα· πρόκειται για φυσικό σπήλαιο που χρησιμοποιήθηκε στη Νεολιθική περίοδο.', 'Περίπου 6000-3200 π.Χ.', 'Η χρήση του σπηλαίου σταμάτησε στην προϊστορία, πιθανότατα μετά από φυσικά γεγονότα και αλλαγές στις συνθήκες κατοίκησης.', 'Δεν χτίστηκε από κάποιον· χρησιμοποιήθηκε από νεολιθικές κοινότητες της Μάνης.', 'Κατοίκηση, τελετουργίες και ταφική χρήση.', 'Τα Σπήλαια Διρού στη Μάνη περιλαμβάνουν την Αλεπότρυπα, τη Βλυχάδα/Γλυφάδα και το Καταφύγγι. Η Αλεπότρυπα είναι ιδιαίτερα σημαντική αρχαιολογικά, καθώς η έρευνα έδειξε μακρά χρήση της από την αρχαιότερη έως την τελική Νεολιθική περίοδο ως οικιστικού και ταφικού χώρου.', 'Από προϊστορικός χώρος κατοίκησης και ταφών μετατράπηκε σε προστατευόμενο σπήλαιο και αρχαιολογικό μνημείο.', 'medium', 'Η πρόσβαση στην περιοχή των Σπηλαίων Διρού είναι εύκολη με όχημα, αλλά η πρόσβαση στην Αλεπότρυπα μπορεί να είναι περιορισμένη και θέλει έλεγχο πριν την επίσκεψη.', 'Προϊστορική Λακωνία / Μάνη', ARRAY['Σπήλαιο Βλυχάδα ή Γλυφάδα', 'Σπήλαιο Καταφύγγι', 'Μάνη']::text[], 'Η είσοδος ή εσωτερική άποψη των σπηλαίων Διρού.', 'high', false, 'Imported from cleaned 217 dataset. Match method: fuzzy (0.740).', ARRAY['culture_diros_caves', 'odysseus_alepotrypa']::text[], 'https://upload.wikimedia.org/wikipedia/commons/1/1c/Diros-cave-greece_16269357444_o.jpg'),
  (88, 'ancient-eleutherna', 'Αρχαία Ελεύθερνα', ARRAY['Πόλη', 'Νεκρόπολη', 'Αρχαιολογικός χώρος']::text[], ARRAY['Γεωμετρική', 'Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή', 'Παλαιοχριστιανική']::text[], 'Η πόλη αναπτύχθηκε σταδιακά από τους πρώιμους ιστορικούς χρόνους.', 'Γεωμετρική περίοδος - Παλαιοχριστιανικοί χρόνοι', 'Η σημασία της μειώθηκε σταδιακά στους μεταγενέστερους χρόνους.', 'Δεν χτίστηκε από ένα μόνο πρόσωπο· αναπτύχθηκε ως αρχαία κρητική πόλη.', 'Αστικό, θρησκευτικό και ταφικό κέντρο της κεντρικής Κρήτης.', 'Η Αρχαία Ελεύθερνα είναι ένας από τους σημαντικότερους αρχαιολογικούς χώρους του Ρεθύμνου. Η πόλη έχει μεγάλη διάρκεια ζωής και είναι γνωστή για τα ευρήματα της νεκρόπολης και για τη συνέχεια της κατοίκησης από τους πρώιμους ιστορικούς έως τους μεταγενέστερους χρόνους.', 'Από αρχαία πόλη μετατράπηκε σε μεγάλο αρχαιολογικό χώρο και μουσειακό προορισμό.', 'easy', 'Εύκολη πρόσβαση με όχημα από το Ρέθυμνο και τα γύρω χωριά.', 'Ελεύθερνα / Κρήτη', ARRAY['Νεκρόπολη Ορθής Πέτρας', 'Μουσείο Αρχαίας Ελεύθερνας', 'Ιδαίο Άντρο']::text[], 'Άποψη του αρχαιολογικού χώρου ή του μουσείου με το κρητικό τοπίο.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_eleutherna']::text[], 'https://upload.wikimedia.org/wikipedia/commons/8/84/Eleutherna_Bridge%2C_Crete%2C_Greece._Pic_02.jpg'),
  (49, 'idaean-cave', 'Ιδαίο Άντρο', ARRAY['Σπήλαιο', 'Ιερό', 'Μυθολογικός χώρος']::text[], ARRAY['Μινωική', 'Γεωμετρική', 'Αρχαϊκή', 'Κλασική', 'Ρωμαϊκή']::text[], 'Δεν είναι κτίσμα· φυσικό σπήλαιο με λατρευτική χρήση σε πολλές περιόδους.', 'Μινωική περίοδος - Ρωμαϊκή περίοδος', 'Η λατρευτική χρήση σταμάτησε σταδιακά μετά την αρχαιότητα.', 'Δεν χτίστηκε από κάποιον· χρησιμοποιήθηκε ως ιερός φυσικός χώρος.', 'Λατρευτικό σπήλαιο, συνδεδεμένο με τη μυθολογία του Δία.', 'Το Ιδαίο Άντρο βρίσκεται στις ανατολικές παρειές του όρους Ίδη, στο οροπέδιο της Νίδας. Στην αρχαιότητα ήταν σημαντικό ιερό σπήλαιο και συνδέθηκε με τον μύθο της ανατροφής του Δία στην Κρήτη.', 'Από ιερό σπήλαιο έγινε προστατευόμενος αρχαιολογικός και φυσικός χώρος.', 'hard', 'Η πρόσβαση είναι δύσκολη/ορεινή και εξαρτάται από τις καιρικές συνθήκες και τη διαδρομή προς το οροπέδιο της Νίδας.', 'Κρήτη / Ίδη', ARRAY['Ψηλορείτης', 'Οροπέδιο Νίδας', 'Αρχαία Ελεύθερνα']::text[], 'Η είσοδος του σπηλαίου και το ορεινό τοπίο του Ψηλορείτη.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_idaean_cave']::text[], ''),
  (101, 'ancient-aptera', 'Αρχαία Άπτερα', ARRAY['Πόλη', 'Οχύρωση', 'Θέατρο', 'Δεξαμενές']::text[], ARRAY['Γεωμετρική', 'Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η πόλη αναπτύχθηκε σε πολλές φάσεις από τους ιστορικούς χρόνους.', 'Αρχαϊκή - Ρωμαϊκή περίοδος', 'Η αρχαία πόλη εγκαταλείφθηκε σταδιακά στους μεταγενέστερους χρόνους.', 'Δεν συνδέεται με έναν κτήτορα· αναπτύχθηκε ως σημαντική πόλη της δυτικής Κρήτης.', 'Αστικό, στρατηγικό και εμπορικό κέντρο με έλεγχο της περιοχής του κόλπου της Σούδας.', 'Η Αρχαία Άπτερα βρίσκεται σε στρατηγικό ύψωμα κοντά στα Χανιά, με θέα προς τον κόλπο της Σούδας. Ο χώρος σώζει τείχη, θέατρο, δεξαμενές και κατάλοιπα πολλών περιόδων, κάνοντάς τον έναν από τους πιο σημαντικούς αρχαιολογικούς χώρους της δυτικής Κρήτης.', 'Από αρχαία πόλη μετατράπηκε σε αρχαιολογικό χώρο με μεταγενέστερες χρήσεις στην ευρύτερη περιοχή.', 'easy', 'Εύκολη πρόσβαση με όχημα από τα Χανιά.', 'Άπτερα / Δυτική Κρήτη', ARRAY['Αρχαίο θέατρο Άπτερας', 'Ρωμαϊκές δεξαμενές', 'Οχυρώσεις Άπτερας', 'Κόλπος Σούδας']::text[], 'Το αρχαίο θέατρο ή οι δεξαμενές με θέα στον κόλπο της Σούδας.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_aptera']::text[], ''),
  (121, 'ancient-falasarna', 'Αρχαία Φαλάσαρνα', ARRAY['Πόλη', 'Λιμάνι', 'Οχύρωση']::text[], ARRAY['Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η πόλη αναπτύχθηκε κυρίως στους κλασικούς και ελληνιστικούς χρόνους.', 'Κλασική - Ελληνιστική περίοδος', 'Η λειτουργία του λιμανιού και της πόλης σταμάτησε σταδιακά μετά τις αλλαγές της αρχαιότητας και τις γεωλογικές μεταβολές της περιοχής.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· αναπτύχθηκε ως ναυτική πόλη της δυτικής Κρήτης.', 'Ναυτικό, εμπορικό και στρατηγικό κέντρο στη δυτική ακτή της Κρήτης.', 'Η Αρχαία Φαλάσαρνα βρίσκεται στο δυτικό άκρο του ακρωτηρίου της Γραμβούσας. Ήταν σημαντική ναυτική πόλη με οχυρώσεις και λιμενικές εγκαταστάσεις. Η θέση της την έκανε κομβικό σημείο για θαλάσσιες επαφές στη δυτική Κρήτη.', 'Από αρχαίο λιμάνι και πόλη μετατράπηκε σε αρχαιολογικό χώρο κοντά στη σημερινή παραλία.', 'easy', 'Εύκολη πρόσβαση με όχημα στην περιοχή της Φαλάσαρνας.', 'Φαλάσαρνα / Δυτική Κρήτη', ARRAY['Αρχαίο λιμάνι Φαλάσαρνας', 'Οχυρώσεις', 'Νεκροταφεία', 'Κίσσαμος']::text[], 'Τα ερείπια με φόντο τη θάλασσα της Φαλάσαρνας.', 'high', true, 'Manual-review import: mapped cleaned monument "Αρχαία Φαλάσαρνα" to catalog_id 121 "Αρχαία Φαλάσαρνας". Alternatives: 116: Αρχαία Κίσσαμος (0.055); 1: Κορυφη Αυγο Παγγαιο (0.000); 2: Οκτάγωνο του Ανακτορικού Συγκροτήματος Γαλερίου (0.000).', ARRAY['odysseus_falasarna']::text[], ''),
  (82, 'gla-citadel', 'Μυκηναϊκή Ακρόπολη Γλα', ARRAY['Ακρόπολη', 'Οχύρωση', 'Μυκηναϊκό κέντρο']::text[], ARRAY['Μυκηναϊκή']::text[], 'Ύστερη Εποχή του Χαλκού, κυρίως 13ος αιώνας π.Χ.', 'Μυκηναϊκή περίοδος', 'Η χρήση του χώρου σταμάτησε με την κατάρρευση των μυκηναϊκών κέντρων.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· συνδέεται με τη μυκηναϊκή οργάνωση της Κωπαΐδας.', 'Έλεγχος και διοίκηση της περιοχής της Κωπαΐδας και πιθανή σύνδεση με μεγάλα υδραυλικά/αγροτικά έργα.', 'Η Ακρόπολη του Γλα είναι μία από τις μεγαλύτερες οχυρωμένες μυκηναϊκές ακροπόλεις του ελλαδικού χώρου. Βρίσκεται στην περιοχή της Κωπαΐδας και διακρίνεται για την τεράστια οχύρωσή της και το κεντρικό κτηριακό συγκρότημα στο εσωτερικό της.', 'Δεν φαίνεται να συνέχισε ως μεγάλη πόλη μετά τη μυκηναϊκή φάση· σήμερα είναι αρχαιολογικός χώρος.', 'medium', 'Προσβάσιμο με όχημα από την περιοχή της Κωπαΐδας, αλλά χρειάζεται περπάτημα και προσοχή στον χώρο.', 'Μυκηναϊκή Βοιωτία / Κωπαΐδα', ARRAY['Κωπαΐδα', 'Ορχομενός', 'Μυκηναϊκά υδραυλικά έργα']::text[], 'Τα κυκλώπεια τείχη ή πανοραμική άποψη της ακρόπολης μέσα στην Κωπαΐδα.', 'high', false, 'Imported from cleaned 217 dataset. Match method: fuzzy (0.740).', ARRAY['odysseus_gla', 'museum_thebes_gla']::text[], 'https://upload.wikimedia.org/wikipedia/commons/9/9b/%CE%93%CE%BB%CE%B1%2C_Gla.jpg'),
  (203, 'sanctuary-amarysia-artemis', 'Ιερό Αμαρυσίας Αρτέμιδος', ARRAY['Ιερό', 'Ναός', 'Λατρευτικό κέντρο']::text[], ARRAY['Γεωμετρική', 'Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Το ιερό έχει μακρά χρήση, με σημαντικές αρχαϊκές και μεταγενέστερες φάσεις.', 'Αρχαϊκή - Ρωμαϊκή περίοδος', 'Η αρχαία λατρεία σταμάτησε σταδιακά μετά την αρχαιότητα.', 'Δεν είναι γνωστός ένας κτήτορας· το ιερό συνδέεται με την αρχαία Ερέτρια και τη λατρεία της Αρτέμιδος Αμαρυσίας.', 'Λατρεία της Αρτέμιδος Αμαρυσίας, σημαντικής θεότητας για την Ερέτρια και την Εύβοια.', 'Το Ιερό της Αμαρυσίας Αρτέμιδος στην Αμάρυνθο είναι από τα πιο σημαντικά ιερά της Εύβοιας. Οι νεότερες ανασκαφές επιβεβαίωσαν την ταύτιση του χώρου και έφεραν στο φως σημαντικά αρχιτεκτονικά και επιγραφικά ευρήματα.', 'Από αρχαίο ιερό μετατράπηκε σε ενεργό ανασκαφικό και αρχαιολογικό χώρο.', 'medium', 'Η πρόσβαση στην περιοχή είναι εύκολη, αλλά ο χώρος μπορεί να έχει περιορισμούς λόγω ανασκαφών.', 'Ερέτρια / Εύβοια', ARRAY['Αρχαία Ερέτρια', 'Ναοί Αμαρυσίας Αρτέμιδος', 'Αμάρυνθος']::text[], 'Ανασκαφική άποψη του ιερού ή φωτογραφία των αρχιτεκτονικών καταλοίπων.', 'high', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['culture_amarysia_artemis', 'esag_amarysia_artemis']::text[], ''),
  (61, 'thermopylae', 'Θερμοπύλες / Μνημείο Λεωνίδα', ARRAY['Ιστορικός τόπος', 'Μνημείο', 'Πεδίο μάχης']::text[], ARRAY['Κλασική', 'Νεότερη μνημειακή φάση']::text[], 'Η μάχη έγινε το 480 π.Χ.· το σύγχρονο μνημείο Λεωνίδα στήθηκε στη δεκαετία του 1950.', 'Κλασική περίοδος ως ιστορικό πεδίο, σύγχρονη περίοδος ως μνημειακός τόπος.', 'Δεν πρόκειται για κτήριο της αρχαιότητας αλλά για ιστορικό πεδίο μάχης με μεταγενέστερα μνημεία.', 'Το σύγχρονο μνημείο ανεγέρθηκε με δαπάνες ομογενών, προς τιμήν του Λεωνίδα και των πολεμιστών των Θερμοπυλών.', 'Μνήμη της μάχης των Θερμοπυλών και της αντίστασης των Σπαρτιατών και των συμμάχων τους στους Πέρσες.', 'Οι Θερμοπύλες είναι ένας από τους πιο γνωστούς ιστορικούς τόπους της αρχαίας Ελλάδας, συνδεδεμένος με τη μάχη του 480 π.Χ. Το σύγχρονο μνημείο του Λεωνίδα βρίσκεται απέναντι από τον ιστορικό λόφο του Κολωνού, όπου τοποθετείται η τελική φάση της μάχης.', 'Από πεδίο μάχης της αρχαιότητας έγινε τόπος μνήμης και ιστορικής επίσκεψης.', 'easy', 'Πολύ εύκολη πρόσβαση με όχημα, δίπλα στον σύγχρονο οδικό άξονα.', 'Φθιώτιδα / Στρατηγικό πέρασμα της Κεντρικής Ελλάδας', ARRAY['Λόφος Κολωνού', 'Μνημείο Θεσπιέων', 'Ιστορικό Κέντρο Θερμοπυλών']::text[], 'Ο ανδριάντας του Λεωνίδα με φόντο το τοπίο των Θερμοπυλών.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_thermopylae']::text[], 'https://upload.wikimedia.org/wikipedia/commons/e/e1/Thermopylae_ancient_coastline_large.jpg'),
  (50, 'nymphaion-mieza-school-aristotle', 'Νυμφαίο Μίεζας / Σχολή Αριστοτέλη', ARRAY['Ιερό', 'Εκπαιδευτικός χώρος', 'Φυσικό τοπίο']::text[], ARRAY['Κλασική', 'Ελληνιστική']::text[], 'Η σύνδεση με τη διδασκαλία του Αριστοτέλη τοποθετείται στον 4ο αιώνα π.Χ.', '4ος αιώνας π.Χ. και μεταγενέστερες φάσεις', 'Η αρχαία χρήση του χώρου εγκαταλείφθηκε σταδιακά.', 'Δεν είναι κλασικό κτήριο ενός κτήτορα· πρόκειται για φυσικό και διαμορφωμένο χώρο στην περιοχή της αρχαίας Μίεζας.', 'Λατρευτικός και εκπαιδευτικός χώρος, παραδοσιακά συνδεδεμένος με τη διδασκαλία του Αριστοτέλη στον Αλέξανδρο και τους συνομηλίκους του.', 'Το Νυμφαίο της Μίεζας, γνωστό και ως Σχολή του Αριστοτέλη, βρίσκεται σε καταπράσινη θέση κοντά στη Νάουσα. Ο χώρος ταυτίστηκε από την έρευνα με το περιβάλλον όπου, σύμφωνα με την παράδοση, ο Αριστοτέλης δίδαξε τον νεαρό Αλέξανδρο.', 'Από ιερό/φυσικό χώρο της αρχαιότητας μετατράπηκε σε επισκέψιμο αρχαιολογικό και ιστορικό τοπίο.', 'easy', 'Εύκολη πρόσβαση με όχημα από τη Νάουσα.', 'Μίεζα / Μακεδονικό βασίλειο', ARRAY['Αρχαιολογικός χώρος Μίεζας', 'Μακεδονικοί τάφοι', 'Νάουσα', 'Αιγές']::text[], 'Οι βραχώδεις σχηματισμοί και το φυσικό τοπίο της Σχολής του Αριστοτέλη.', 'high', true, 'Manual-review import: mapped cleaned monument "Νυμφαίο Μίεζας / Σχολή Αριστοτέλη" to catalog_id 50 "Νυμφαίο Μίεζας". Alternatives: 36: Μακεδονικός Τάφος των Ανθεμίων (0.220); 1: Κορυφη Αυγο Παγγαιο (0.000); 2: Οκτάγωνο του Ανακτορικού Συγκροτήματος Γαλερίου (0.000).', ARRAY['odysseus_nymphaion_mieza']::text[], ''),
  (172, 'ancient-olynthus', 'Αρχαία Όλυνθος', ARRAY['Πόλη', 'Οικίες', 'Ιπποδάμειο σχέδιο']::text[], ARRAY['Νεολιθική', 'Αρχαϊκή', 'Κλασική']::text[], 'Η κλασική πόλη οργανώθηκε κυρίως στον 5ο-4ο αιώνα π.Χ.', 'Κλασική περίοδος', 'Καταστράφηκε το 348 π.Χ. από τον Φίλιππο Β΄.', 'Αναπτύχθηκε από την πόλη των Ολυνθίων και αποτέλεσε σημαντικό κέντρο της Χαλκιδικής.', 'Αστικό και πολιτικό κέντρο με οργανωμένη πολεοδομία.', 'Η Αρχαία Όλυνθος είναι από τους σημαντικότερους χώρους για την κατανόηση της καθημερινής ζωής και της πολεοδομίας μιας κλασικής ελληνικής πόλης. Ήταν χτισμένη πάνω σε διπλό λόφο και είναι γνωστή για τις οικίες με ψηφιδωτά και το οργανωμένο σχέδιο των δρόμων.', 'Μετά την καταστροφή της δεν ξαναέγινε μεγάλο αστικό κέντρο, διατηρώντας καθαρή την εικόνα της κλασικής πόλης.', 'easy', 'Προσβάσιμη με αυτοκίνητο από Θεσσαλονίκη και Χαλκιδική.', 'Όλυνθος / Χαλκιδική', ARRAY['Οικίες Ολύνθου', 'Ψηφιδωτά', 'Χαλκιδική Συμμαχία']::text[], 'Τα θεμέλια των οικιών και οι δρόμοι της αρχαίας πόλης από ψηλά.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_olynthus']::text[], 'https://upload.wikimedia.org/wikipedia/commons/a/af/Bouleuterion_in_Olynthos_2.jpg'),
  (180, 'ancient-stagira', 'Αρχαία Στάγειρα', ARRAY['Πόλη', 'Οχύρωση', 'Γενέτειρα Αριστοτέλη']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική']::text[], 'Η πόλη ιδρύθηκε στην αρχαϊκή περίοδο από αποίκους της Άνδρου.', 'Αρχαϊκή - Ελληνιστική περίοδος', 'Η πόλη γνώρισε καταστροφές και μεταβολές στους κλασικούς χρόνους, αλλά η θέση συνέχισε να είναι γνωστή.', 'Άποικοι από την Άνδρο, σύμφωνα με την αρχαία παράδοση.', 'Παράκτια πόλη της Χαλκιδικής με στρατηγική και εμπορική σημασία.', 'Τα Αρχαία Στάγειρα βρίσκονται κοντά στη σημερινή Ολυμπιάδα Χαλκιδικής και είναι γνωστά κυρίως ως η γενέτειρα του Αριστοτέλη. Ο χώρος περιλαμβάνει οχυρώσεις, κατοικίες και δημόσια κτήρια σε παράκτια θέση με έντονο φυσικό τοπίο.', 'Από αρχαία πόλη μετατράπηκε σε αρχαιολογικό χώρο και τόπο μνήμης λόγω της σχέσης με τον Αριστοτέλη.', 'medium', 'Προσβάσιμη με όχημα έως την περιοχή της Ολυμπιάδας και στη συνέχεια με περπάτημα στον χώρο.', 'Στάγειρα / Χαλκιδική', ARRAY['Ολυμπιάδα', 'Οχύρωση Σταγείρων', 'Χαλκιδική']::text[], 'Τα ερείπια των Σταγείρων με φόντο τη θάλασσα.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_stagira']::text[], ''),
  (2, 'galerian-complex-thessaloniki', 'Γαλεριανό Συγκρότημα Θεσσαλονίκης / Οκτάγωνο', ARRAY['Ανάκτορο', 'Ρωμαϊκό συγκρότημα', 'Μνημειακή αρχιτεκτονική']::text[], ARRAY['Ρωμαϊκή', 'Παλαιοχριστιανική']::text[], 'Τέλη 3ου - αρχές 4ου αιώνα μ.Χ.', 'Ρωμαϊκή - Παλαιοχριστιανική περίοδος', 'Η χρήση του συγκροτήματος άλλαξε στους παλαιοχριστιανικούς και βυζαντινούς χρόνους.', 'Συνδέεται με τον αυτοκράτορα Γαλέριο.', 'Ανακτορικό και διοικητικό συγκρότημα της ύστερης ρωμαϊκής Θεσσαλονίκης.', 'Το Γαλεριανό Συγκρότημα βρίσκεται στο κέντρο της Θεσσαλονίκης και αποτελεί ένα από τα σημαντικότερα ρωμαϊκά μνημειακά σύνολα της πόλης. Περιλάμβανε ανάκτορο, περιστύλιο, αίθουσες, το Οκτάγωνο και συνδεόταν με τη Ροτόντα και την Αψίδα του Γαλερίου.', 'Από ρωμαϊκό ανακτορικό συγκρότημα ενσωματώθηκε στη μεταγενέστερη ζωή της πόλης και σήμερα είναι αστικός αρχαιολογικός χώρος.', 'easy', 'Πολύ εύκολη πρόσβαση, μέσα στο κέντρο της Θεσσαλονίκης.', 'Ρωμαϊκή Θεσσαλονίκη', ARRAY['Οκτάγωνο', 'Ροτόντα', 'Αψίδα Γαλερίου', 'Πλατεία Ναυαρίνου']::text[], 'Το Οκτάγωνο ή γενική άποψη του ανακτορικού συγκροτήματος στην πλατεία Ναυαρίνου.', 'high', true, 'Manual-review import: mapped cleaned monument "Γαλεριανό Συγκρότημα Θεσσαλονίκης / Οκτάγωνο" to catalog_id 2 "Οκτάγωνο του Ανακτορικού Συγκροτήματος Γαλερίου". Alternatives: 70: Κρύπτη Αγίου Δημητρίου (0.220); 71: Μακεδονικός Τάφος Λαγκαδά (0.073); 1: Κορυφη Αυγο Παγγαιο (0.000).', ARRAY['odysseus_galerian_complex']::text[], ''),
  (186, 'ancient-pydna', 'Αρχαία Πύδνα', ARRAY['Πόλη', 'Οχύρωση', 'Ιστορικός τόπος']::text[], ARRAY['Κλασική', 'Ελληνιστική', 'Ρωμαϊκή', 'Παλαιοχριστιανική']::text[], 'Η πόλη αναπτύχθηκε σταδιακά στους ιστορικούς χρόνους.', 'Κλασική - Ρωμαϊκή περίοδος', 'Η πόλη πέρασε από πολλές μεταβολές και συνδέεται με σημαντικές ιστορικές συγκρούσεις.', 'Δεν συνδέεται με έναν κτήτορα· αναπτύχθηκε ως μακεδονική πόλη της Πιερίας.', 'Παράκτια πόλη με στρατηγική και πολιτική σημασία στη Μακεδονία.', 'Η Αρχαία Πύδνα βρισκόταν στην περιοχή του σημερινού Μακρυγιάλου και ήταν σημαντική μακεδονική πόλη. Η θέση της κοντά στη θάλασσα την έκανε στρατηγική, ενώ η περιοχή είναι γνωστή και από τη μάχη της Πύδνας που σημάδεψε το τέλος της μακεδονικής ανεξαρτησίας.', 'Από μακεδονική πόλη πέρασε σε ρωμαϊκές και παλαιοχριστιανικές φάσεις χρήσης στην ευρύτερη περιοχή.', 'medium', 'Προσβάσιμη στην περιοχή Μακρυγιάλου, αλλά η επισκεψιμότητα μπορεί να χρειάζεται συνεννόηση.', 'Μακεδονικό βασίλειο / Πιερία', ARRAY['Μακρύγιαλος', 'Λουλουδιές Κίτρους', 'Πιερία']::text[], 'Άποψη του αρχαιολογικού χώρου ή της παράκτιας θέσης της Πύδνας.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_pydna']::text[], 'https://upload.wikimedia.org/wikipedia/commons/3/3e/Archaea_pydna_ancient.jpg'),
  (19, 'ancient-europos', 'Αρχαία Ευρωπός', ARRAY['Πόλη', 'Νεκρόπολη', 'Αρχαιολογικός χώρος']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ρωμαϊκή', 'Παλαιοχριστιανική']::text[], 'Η περιοχή έχει ευρήματα από προϊστορικούς χρόνους και σημαντική ανάπτυξη στους ιστορικούς χρόνους.', 'Αρχαϊκή - Παλαιοχριστιανική περίοδος', 'Η μορφή της πόλης και του οικισμού άλλαξε σταδιακά στους μεταγενέστερους χρόνους.', 'Δεν είναι γνωστός ένας κτήτορας· η πόλη αναπτύχθηκε στην περιοχή της μακεδονικής Βοττιαίας.', 'Αστικό και οικονομικό κέντρο της περιοχής, με σημαντική αρχαιολογική συνέχεια.', 'Η Αρχαία Ευρωπός είναι ένας από τους σημαντικότερους αρχαιολογικούς χώρους του Κιλκίς. Είναι γνωστή και ως πατρίδα του Σέλευκου Α΄ Νικάτορα, ιδρυτή της δυναστείας των Σελευκιδών. Στην περιοχή βρέθηκε και ο περίφημος Κούρος της Ευρωπού.', 'Από αρχαία πόλη και νεκρόπολη μετατράπηκε σε προστατευόμενο αρχαιολογικό χώρο.', 'easy', 'Προσβάσιμη οδικώς στην περιοχή του Ευρωπού Κιλκίς.', 'Μακεδονική Βοττιαία / Ευρωπός', ARRAY['Αρχαιολογικό Μουσείο Κιλκίς', 'Κούρος Ευρωπού', 'Νεκρόπολη Ευρωπού']::text[], 'Γενική άποψη του αρχαιολογικού χώρου ή φωτογραφία του Κούρου Ευρωπού από το μουσείο.', 'high', true, 'Manual-review import: mapped cleaned monument "Αρχαία Ευρωπός" to catalog_id 19 "Αρχαίος Ευρωπός". Alternatives: 1: Κορυφη Αυγο Παγγαιο (0.000); 3: Ηραίο Περαχώρας (0.000); 5: Πιθανή θέση της Ποικίλης Στοάς (0.000).', ARRAY['odysseus_ancient_europos', 'culture_europos_upgrade']::text[], ''),
  (22, 'heraion-olympia', 'Ηραίο Ολυμπίας', ARRAY['Ναός', 'Ιερό', 'Ολυμπία']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Ο ναός χρονολογείται κυρίως γύρω στο 600 π.Χ.', 'Αρχαϊκή - Ρωμαϊκή περίοδος', 'Ο ναός ερειπώθηκε μετά την παύση της αρχαίας λατρείας.', 'Δεν είναι γνωστός συγκεκριμένος αρχιτέκτονας· συνδέεται με την ανάπτυξη του ιερού της Ολυμπίας.', 'Λατρεία της Ήρας μέσα στο ιερό της Ολυμπίας.', 'Το Ηραίο είναι ένας από τους αρχαιότερους μνημειακούς ναούς της Ολυμπίας. Βρισκόταν μέσα στην Άλτη, το ιερό άλσος, και συνδεόταν με τη λατρεία της Ήρας. Είναι από τα πιο χαρακτηριστικά μνημεία του ολυμπιακού ιερού.', 'Από λατρευτικός ναός έγινε αρχαιολογικό μνημείο μέσα στον χώρο της Ολυμπίας.', 'easy', 'Εύκολη πρόσβαση μέσα από τον οργανωμένο αρχαιολογικό χώρο της Ολυμπίας.', 'Ολυμπία / Ηλεία', ARRAY['Ιερό Ολυμπίας', 'Ναός Δία', 'Στάδιο Ολυμπίας', 'Βωμός Ήρας']::text[], 'Οι κίονες και τα κατάλοιπα του Ηραίου μέσα στον χώρο της Ολυμπίας.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_heraion_olympia']::text[], ''),
  (189, 'ancient-aigeira-theatre', 'Αρχαία Αιγείρα / Αρχαίο Θέατρο', ARRAY['Πόλη', 'Θέατρο', 'Αρχαιολογικός χώρος']::text[], ARRAY['Ελληνιστική', 'Ρωμαϊκή']::text[], 'Το αρχαίο θέατρο χρονολογείται στο α΄ μισό του 3ου αιώνα π.Χ., περίπου 280-250 π.Χ.', 'Ελληνιστική - Ρωμαϊκή περίοδος', 'Η αρχαία πόλη εγκαταλείφθηκε σταδιακά στους μεταγενέστερους χρόνους.', 'Συνδέεται με την αρχαία πόλη της Αιγείρας και την ανάπτυξη της Αχαϊκής Συμπολιτείας.', 'Θεατρικές, πολιτικές και δημόσιες συγκεντρώσεις της αρχαίας πόλης.', 'Η Αρχαία Αιγείρα ήταν σημαντική πόλη της Αχαΐας. Το αρχαίο θέατρό της, χτισμένο σε θέση με θέα προς τον Κορινθιακό, είναι το πιο γνωστό μνημείο του χώρου και συνδέεται με την ακμή της πόλης στην ελληνιστική περίοδο.', 'Από δημόσιος χώρος της αρχαίας πόλης έγινε αρχαιολογικός χώρος.', 'medium', 'Προσβάσιμη με όχημα στην περιοχή της Αιγείρας· ο χώρος μπορεί να απαιτεί συνεννόηση/έλεγχο επισκεψιμότητας.', 'Αιγείρα / Αχαΐα', ARRAY['Θέατρο Αιγείρας', 'Λόφος Παλαιοκάστρου', 'Αχαϊκή Συμπολιτεία']::text[], 'Το αρχαίο θέατρο με θέα προς τον Κορινθιακό κόλπο.', 'high', true, 'Manual-review import: mapped cleaned monument "Αρχαία Αιγείρα / Αρχαίο Θέατρο" to catalog_id 189 "Αρχαία Αιγείρα". Alternatives: 17: Αρχαίο θέατρο Δελφών (0.390); 146: Αρχαίο Θέρμο (0.195); 191: Θέατρο Θορικού (0.195).', ARRAY['odysseus_aigeira_theatre']::text[], ''),
  (109, 'oiniades-ship-sheds', 'Οινιάδες / Αρχαία Νεώρια', ARRAY['Πόλη', 'Λιμάνι', 'Νεώρια', 'Θέατρο']::text[], ARRAY['Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Τα μνημεία του χώρου αναπτύχθηκαν κυρίως στους κλασικούς και ελληνιστικούς χρόνους.', 'Κλασική - Ελληνιστική περίοδος', 'Η πόλη έχασε σταδιακά τη σημασία της στους μεταγενέστερους χρόνους.', 'Αναπτύχθηκε ως πόλη των Οινιαδών στην περιοχή της Παραχελωίτιδας.', 'Έλεγχος των εκβολών του Αχελώου και της εισόδου του Πατραϊκού κόλπου, με ναυτική και στρατηγική σημασία.', 'Οι Οινιάδες ήταν σημαντική αρχαία πόλη της Αιτωλοακαρνανίας, γνωστή για τα εντυπωσιακά νεώρια και το θέατρό της. Η θέση της κοντά στον Αχελώο και τον Πατραϊκό κόλπο την έκανε ιδιαίτερα σημαντική για τη ναυσιπλοΐα και την άμυνα.', 'Από ζωντανή πόλη και λιμενικό κέντρο μετατράπηκε σε αρχαιολογικό χώρο.', 'medium', 'Προσβάσιμη με όχημα, αλλά ο χώρος είναι εκτεταμένος και χρειάζεται περπάτημα.', 'Οινιάδες / Αιτωλοακαρνανία', ARRAY['Αρχαία νεώρια', 'Θέατρο Οινιαδών', 'Αχελώος', 'Πλευρώνα']::text[], 'Τα αρχαία νεώρια ή το θέατρο των Οινιαδών.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_oiniades']::text[], 'https://upload.wikimedia.org/wikipedia/commons/d/d3/%CE%9F%CE%B9%CE%BD%CE%B9%CE%AC%CE%B4%CE%B5%CF%82_2.jpg'),
  (108, 'new-pleuron', 'Νέα Πλευρώνα', ARRAY['Πόλη', 'Οχύρωση', 'Θέατρο']::text[], ARRAY['Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η Νέα Πλευρώνα χτίστηκε κυρίως μετά την καταστροφή της παλαιότερης Πλευρώνας, στον 3ο αιώνα π.Χ.', 'Ελληνιστική - Ρωμαϊκή περίοδος', 'Η πόλη εγκαταλείφθηκε σταδιακά στους μεταγενέστερους χρόνους.', 'Αναπτύχθηκε από τους Αιτωλούς ως μία από τις σημαντικές πόλεις της Δυτικής Αιτωλίας.', 'Οχυρωμένη πόλη με στρατηγικό έλεγχο της περιοχής του Μεσολογγίου και της αιτωλικής ενδοχώρας.', 'Η Νέα Πλευρώνα είναι μία από τις μεγαλύτερες αρχαίες πόλεις της Δυτικής Αιτωλίας. Ξεχωρίζει για τα εντυπωσιακά τείχη της, που σώζονται σε μεγάλο μήκος, καθώς και για το θέατρο και τα κατάλοιπα του πολεοδομικού της ιστού.', 'Από οχυρωμένη ελληνιστική πόλη μετατράπηκε σε αρχαιολογικό χώρο.', 'medium', 'Προσβάσιμη με όχημα, αλλά ο χώρος είναι μεγάλος και απαιτεί περπάτημα.', 'Αιτωλία / Αιτωλικό Κοινό', ARRAY['Τείχη Πλευρώνας', 'Θέατρο Πλευρώνας', 'Οινιάδες', 'Μεσολόγγι']::text[], 'Τα τείχη της Νέας Πλευρώνας με θέα προς τη λιμνοθάλασσα.', 'high', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['odysseus_new_pleuron']::text[], ''),
  (97, 'dodona', 'Δωδώνη', ARRAY['Ιερό', 'Μαντείο', 'Θέατρο']::text[], ARRAY['Γεωμετρική', 'Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Το ιερό αναπτύχθηκε σταδιακά, με αρχαιότατη λατρευτική παράδοση.', 'Γεωμετρική - Ρωμαϊκή περίοδος', 'Η μαντική και λατρευτική χρήση σταμάτησε σταδιακά μετά την αρχαιότητα.', 'Δεν χτίστηκε από έναν κτήτορα· αναπτύχθηκε ως ιερό του Δία και της Διώνης στην Ήπειρο.', 'Λατρεία του Δία και λειτουργία μαντείου, ενός από τα αρχαιότερα του ελληνικού κόσμου.', 'Η Δωδώνη ήταν διάσημη για το μαντείο της, που σύμφωνα με την παράδοση ήταν από τα αρχαιότερα στην ελληνική επικράτεια. Ο χώρος περιλαμβάνει το ιερό, το μεγάλο αρχαίο θέατρο και κτήρια που συνδέονται με τη θρησκευτική και πολιτική ζωή της Ηπείρου.', 'Από πανάρχαιο ιερό και μαντείο μετατράπηκε σε μεγάλο αρχαιολογικό χώρο.', 'easy', 'Εύκολη πρόσβαση με όχημα από τα Ιωάννινα.', 'Ήπειρος / Μολοσσοί', ARRAY['Αρχαίο Θέατρο Δωδώνης', 'Ιερή Οικία', 'Ναός Διώνης', 'Ναός Θέμιδος']::text[], 'Το αρχαίο θέατρο της Δωδώνης με το ηπειρώτικο τοπίο.', 'high', true, 'Manual-review import: mapped cleaned monument "Δωδώνη" to catalog_id 97 "Μαντείο της Δωδώνης". Alternatives: 1: Κορυφη Αυγο Παγγαιο (0.000); 3: Ηραίο Περαχώρας (0.000); 5: Πιθανή θέση της Ποικίλης Στοάς (0.000).', ARRAY['odysseus_dodona']::text[], 'https://upload.wikimedia.org/wikipedia/commons/c/cf/Dodona-Greece-April-2008-107.JPG'),
  (58, 'ancient-nikopolis', 'Αρχαία Νικόπολη', ARRAY['Πόλη', 'Ρωμαϊκό κέντρο', 'Θέατρο', 'Ωδείο', 'Οχύρωση']::text[], ARRAY['Ρωμαϊκή', 'Παλαιοχριστιανική', 'Βυζαντινή']::text[], 'Ιδρύθηκε μετά τη ναυμαχία του Ακτίου, το 31 π.Χ.', 'Ρωμαϊκή - Παλαιοχριστιανική περίοδος', 'Η πόλη συνέχισε να υπάρχει σε μεταγενέστερες φάσεις αλλά η ακμή της μειώθηκε σταδιακά.', 'Ιδρύθηκε από τον Οκταβιανό Αύγουστο.', 'Μνημειακή πόλη-σύμβολο της νίκης του Οκταβιανού στη ναυμαχία του Ακτίου.', 'Η Νικόπολη της Ηπείρου ιδρύθηκε από τον Οκταβιανό Αύγουστο μετά τη νίκη του στο Άκτιο. Η ίδια η ονομασία της σημαίνει πόλη της νίκης. Ο αρχαιολογικός χώρος περιλαμβάνει τείχη, θέατρο, ωδείο, ρωμαϊκά και παλαιοχριστιανικά μνημεία.', 'Από ρωμαϊκή πόλη-σύμβολο έγινε παλαιοχριστιανικό και βυζαντινό κέντρο, και σήμερα αρχαιολογικός χώρος.', 'easy', 'Εύκολη πρόσβαση με όχημα από την Πρέβεζα.', 'Ρωμαϊκή Ήπειρος', ARRAY['Ρωμαϊκό Ωδείο', 'Θέατρο Νικόπολης', 'Τείχη', 'Αρχαιολογικό Μουσείο Νικόπολης', 'Άκτιο']::text[], 'Το ρωμαϊκό ωδείο ή πανοραμική άποψη των τειχών της Νικόπολης.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_nikopolis']::text[], 'https://upload.wikimedia.org/wikipedia/commons/1/1f/Nicopolis_nymphaeum.jpg'),
  (94, 'nekromanteion-acheron', 'Νεκρομαντείο Αχέροντα', ARRAY['Ιερό', 'Μαντείο', 'Μυθολογικός χώρος']::text[], ARRAY['Κλασική', 'Ελληνιστική']::text[], 'Η οργάνωση του σωζόμενου χώρου συνδέεται κυρίως με τους ελληνιστικούς χρόνους.', 'Κλασική - Ελληνιστική περίοδος', 'Η χρήση του χώρου ως μαντείου σταμάτησε μετά την αρχαιότητα.', 'Δεν είναι γνωστός συγκεκριμένος κτήτορας· συνδέεται με τη λατρεία των νεκρών και την περιοχή του Αχέροντα.', 'Επικοινωνία με τους νεκρούς και λατρεία που συνδέεται με τον Κάτω Κόσμο.', 'Το Νεκρομαντείο του Αχέροντα στον Μεσοπόταμο συνδέεται με την αρχαία αντίληψη για τον Κάτω Κόσμο. Η παλαιότερη αναφορά στο νεκρομαντείο του Αχέροντα γίνεται στην Οδύσσεια, όταν ο Οδυσσέας καθοδηγείται να συμβουλευτεί τις ψυχές των νεκρών.', 'Από μαντικό και λατρευτικό κέντρο μετατράπηκε σε αρχαιολογικό χώρο με έντονη μυθολογική ταυτότητα.', 'easy', 'Εύκολη πρόσβαση με όχημα στον Μεσοπόταμο.', 'Αχέροντας / Θεσπρωτία-Ήπειρος', ARRAY['Ποταμός Αχέροντας', 'Εφύρα', 'Πανδοσία', 'Ελέα']::text[], 'Ο κεντρικός υπόγειος χώρος ή άποψη του μνημείου με το τοπίο του Αχέροντα.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_nekromanteion']::text[], ''),
  (95, 'gitana', 'Αρχαία Γίτανα', ARRAY['Πόλη', 'Οχύρωση', 'Θέατρο']::text[], ARRAY['Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η πόλη αναπτύχθηκε στους ελληνιστικούς χρόνους.', 'Ελληνιστική περίοδος', 'Η πόλη εγκαταλείφθηκε σταδιακά μετά τις ιστορικές μεταβολές της περιοχής.', 'Συνδέεται με τους Θεσπρωτούς και το Κοινό των Θεσπρωτών.', 'Πρωτεύουσα και πολιτικό κέντρο της αρχαίας Θεσπρωτίας.', 'Τα Γίτανα ήταν δεύτερη, κατά χρονολογική σειρά, πρωτεύουσα της αρχαίας Θεσπρωτίας και έδρα του Κοινού των Θεσπρωτών. Ο χώρος σώζει οχυρώσεις, θέατρο και κατάλοιπα οργανωμένου οικισμού κοντά στον ποταμό Καλαμά.', 'Από πρωτεύουσα των Θεσπρωτών μετατράπηκε σε αρχαιολογικό χώρο.', 'medium', 'Δυνατή πρόσβαση οχημάτων έως την είσοδο μέσω ασφαλτοστρωμένου δρόμου, αλλά ο χώρος απαιτεί περπάτημα.', 'Θεσπρωτία / Κοινό Θεσπρωτών', ARRAY['Θέατρο Γιτάνων', 'Οχυρώσεις', 'Ποταμός Καλαμάς', 'Ελέα']::text[], 'Το θέατρο ή τα τείχη των Γιτάνων με το τοπίο της Θεσπρωτίας.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_gitana']::text[], ''),
  (174, 'philippi', 'Φίλιπποι', ARRAY['Πόλη', 'Θέατρο', 'UNESCO', 'Ρωμαϊκό και παλαιοχριστιανικό κέντρο']::text[], ARRAY['Κλασική', 'Ελληνιστική', 'Ρωμαϊκή', 'Παλαιοχριστιανική', 'Βυζαντινή']::text[], 'Οι πρώτοι οικιστές ήταν Θάσιοι που ίδρυσαν τις Κρηνίδες γύρω στο 360 π.Χ.; η πόλη μετονομάστηκε και αναπτύχθηκε από τον Φίλιππο Β΄.', '4ος αιώνας π.Χ. - Βυζαντινή περίοδος', 'Η πόλη επιβίωσε στους βυζαντινούς χρόνους και παρήκμασε σταδιακά μετά τις μεταγενέστερες ιστορικές αλλαγές.', 'Αρχικά Θάσιοι άποικοι· αργότερα ενισχύθηκε και μετονομάστηκε από τον Φίλιππο Β΄ της Μακεδονίας.', 'Στρατηγικό, οικονομικό και αργότερα ρωμαϊκό/χριστιανικό κέντρο στην ανατολική Μακεδονία.', 'Οι Φίλιπποι είναι ένας από τους σημαντικότερους αρχαιολογικούς χώρους της βόρειας Ελλάδας. Η πόλη ξεκίνησε ως αποικία των Θασίων με το όνομα Κρηνίδες και αναπτύχθηκε ιδιαίτερα όταν ο Φίλιππος Β΄ την ενίσχυσε και της έδωσε το όνομά του. Σώζονται θέατρο, αγορά, βασιλικές και ρωμαϊκά μνημεία.', 'Από μακεδονική πόλη εξελίχθηκε σε ρωμαϊκό και παλαιοχριστιανικό κέντρο.', 'easy', 'Εύκολη πρόσβαση με όχημα, κοντά στις Κρηνίδες, περίπου 15 χλμ. από την Καβάλα.', 'Μακεδονία / Φίλιπποι', ARRAY['Θέατρο Φιλίππων', 'Ρωμαϊκή αγορά', 'Παλαιοχριστιανικές βασιλικές', 'Κρηνίδες']::text[], 'Το αρχαίο θέατρο ή γενική άποψη του αρχαιολογικού χώρου των Φιλίππων.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_philippi']::text[], 'https://upload.wikimedia.org/wikipedia/commons/5/5c/Philippi_city_center.jpg'),
  (164, 'sanctuary-great-gods-samothrace', 'Ιερό Μεγάλων Θεών Σαμοθράκης', ARRAY['Ιερό', 'Μυστήρια', 'Πανελλήνιο κέντρο']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Το ιερό αναπτύχθηκε σταδιακά από τους αρχαϊκούς χρόνους, με μεγάλη ακμή στην ελληνιστική περίοδο.', 'Αρχαϊκή - Ρωμαϊκή περίοδος', 'Η μυστηριακή λατρεία σταμάτησε σταδιακά μετά την αρχαιότητα.', 'Δεν χτίστηκε από έναν κτήτορα· διαμορφώθηκε με αφιερώματα και κτήρια πολλών περιόδων.', 'Μυστηριακή λατρεία των Μεγάλων Θεών, με τελετές μύησης που θεωρούνταν ότι πρόσφεραν προστασία.', 'Το Ιερό των Μεγάλων Θεών στη Σαμοθράκη ήταν διάσημο σε όλο τον αρχαίο κόσμο για τη μυστηριακή του λατρεία. Εκεί βρέθηκε και το περίφημο άγαλμα της Νίκης της Σαμοθράκης. Ο χώρος περιλαμβάνει σημαντικά ελληνιστικά και ρωμαϊκά κτήρια.', 'Από ενεργό μυστηριακό ιερό έγινε αρχαιολογικός χώρος διεθνούς σημασίας.', 'medium', 'Προσβάσιμο αφού φτάσεις στη Σαμοθράκη· ο χώρος βρίσκεται κοντά στην Παλαιόπολη.', 'Σαμοθράκη / Βόρειο Αιγαίο-Θράκη', ARRAY['Νίκη της Σαμοθράκης', 'Θόλος Αρσινόης', 'Αρχαιολογικό Μουσείο Σαμοθράκης']::text[], 'Άποψη του ιερού με το φυσικό τοπίο της Σαμοθράκης ή η Θόλος Αρσινόης.', 'high', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['odysseus_samothrace_great_gods']::text[], ''),
  (173, 'ancient-abdera', 'Αρχαία Άβδηρα', ARRAY['Πόλη', 'Λιμάνι', 'Οχύρωση']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η πόλη αναπτύχθηκε από την αρχαϊκή περίοδο.', 'Αρχαϊκή - Ρωμαϊκή περίοδος', 'Η πόλη άλλαξε μορφή και σημασία στους μεταγενέστερους χρόνους.', 'Συνδέεται με ελληνική αποικιακή εγκατάσταση στα παράλια της Θράκης.', 'Παράκτια πόλη με εμπορική και στρατηγική σημασία, χάρη στα φυσικά λιμάνια της.', 'Τα Άβδηρα ήταν μία από τις σημαντικότερες αρχαίες πόλεις του βορείου Αιγαίου. Βρίσκονταν σε προνομιακή θέση στα παράλια της Θράκης, με δύο φυσικά λιμάνια. Η πόλη είναι επίσης γνωστή ως πατρίδα σημαντικών προσωπικοτήτων, όπως ο Δημόκριτος.', 'Από αρχαία πόλη και λιμενικό κέντρο έγινε αρχαιολογικός χώρος και μουσειακό σύνολο.', 'easy', 'Προσβάσιμα οδικώς από την Ξάνθη και τον σύγχρονο οικισμό των Αβδήρων.', 'Άβδηρα / Θράκη', ARRAY['Αρχαιολογικό Μουσείο Αβδήρων', 'Πολύστυλο', 'Τείχη Αβδήρων']::text[], 'Τα τείχη ή γενική άποψη του αρχαιολογικού χώρου κοντά στη θάλασσα.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_abdera']::text[], 'https://upload.wikimedia.org/wikipedia/commons/5/53/Abdera.JPG'),
  (195, 'ancient-zone-mesimvria', 'Μεσημβρία-Ζώνη / Αρχαία Ζώνη', ARRAY['Πόλη', 'Ιερό', 'Παράκτιος αρχαιολογικός χώρος']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η αρχαία πόλη αναπτύχθηκε στους αρχαϊκούς και κλασικούς χρόνους.', 'Αρχαϊκή - Ρωμαϊκή περίοδος', 'Η πόλη εγκαταλείφθηκε σταδιακά στους μεταγενέστερους χρόνους.', 'Συνδέεται με την περαία της Σαμοθράκης και τις ελληνικές εγκαταστάσεις της θρακικής ακτής.', 'Παράκτια πόλη με εμπορική και στρατηγική σημασία στο βόρειο Αιγαίο.', 'Η Μεσημβρία-Ζώνη, γνωστή και ως Αρχαία Ζώνη, βρίσκεται δυτικά της Αλεξανδρούπολης. Ο χώρος διατηρεί κατάλοιπα πόλης, οχυρώσεων και σημαντικών δημόσιων κτηρίων, με ιδιαίτερη σημασία τον ναό του Απόλλωνα.', 'Από παράκτια αρχαία πόλη μετατράπηκε σε οργανωμένο αρχαιολογικό χώρο.', 'easy', 'Εύκολη πρόσβαση από την Εγνατία και την περιοχή της Μάκρης.', 'Θρακική ακτή / Περαία Σαμοθράκης', ARRAY['Ναός Απόλλωνα', 'Οχυρώσεις', 'Αλεξανδρούπολη', 'Σαμοθράκη']::text[], 'Τα ερείπια της πόλης με φόντο τη θάλασσα του Θρακικού πελάγους.', 'high', false, 'Imported from cleaned 217 dataset. Match method: fuzzy (0.945).', ARRAY['odysseus_ancient_zone', 'odysseus_apollo_zone']::text[], ''),
  (98, 'sesklo', 'Σέσκλο', ARRAY['Προϊστορικός οικισμός', 'Νεολιθικός οικισμός']::text[], ARRAY['Νεολιθική', 'Εποχή Χαλκού']::text[], 'Η κατοίκηση ξεκινά από την αρχή της Νεολιθικής Εποχής, στην 7η χιλιετία π.Χ.', '7η - 5η χιλιετία π.Χ., με μεταγενέστερες φάσεις μέχρι τη Μέση Εποχή του Χαλκού', 'Ο οικισμός γνώρισε φάσεις εγκατάλειψης και επανακατοίκησης.', 'Δεν υπάρχει γνωστός κτήτορας· πρόκειται για προϊστορική κοινότητα της Θεσσαλίας.', 'Οικισμός μόνιμης εγκατάστασης νεολιθικών κοινοτήτων.', 'Το Σέσκλο είναι ένας από τους σημαντικότερους νεολιθικούς οικισμούς της Ελλάδας. Βρίσκεται στον λόφο Καστράκι κοντά στο σημερινό χωριό Σέσκλο και έχει μεγάλη σημασία για τη μελέτη της νεολιθικής κατοίκησης, της αρχιτεκτονικής και της κεραμικής.', 'Από προϊστορικός οικισμός μετατράπηκε σε αρχαιολογικό χώρο.', 'easy', 'Εύκολη πρόσβαση με όχημα από τον Βόλο και τη Μαγνησία.', 'Προϊστορική Θεσσαλία / Μαγνησία', ARRAY['Διμήνι', 'Αρχαιολογικό Μουσείο Βόλου', 'Νεολιθική Θεσσαλία']::text[], 'Τα ερείπια του οικισμού στον λόφο Καστράκι.', 'high', true, 'Manual-review import: mapped cleaned monument "Σέσκλο" to catalog_id 98 "Αρχαίος Οίκισμος Σέσκλο". Alternatives: 99: Μυκηναϊκός χώρος Διμήνι (0.055); 132: Παλαιά / Κλασική Άλος (0.044); 133: Νέα / Ελληνιστική Άλος (0.044).', ARRAY['odysseus_sesklo']::text[], ''),
  (99, 'dimini', 'Διμήνι', ARRAY['Προϊστορικός οικισμός', 'Νεολιθικός οικισμός', 'Μυκηναϊκός χώρος']::text[], ARRAY['Νεολιθική', 'Μυκηναϊκή']::text[], 'Ο νεολιθικός οικισμός αναπτύχθηκε στη Νεολιθική περίοδο, ενώ στην περιοχή υπάρχουν και μυκηναϊκά κατάλοιπα.', 'Νεολιθική περίοδος και Ύστερη Εποχή του Χαλκού', 'Η χρήση του χώρου μεταβλήθηκε ανάμεσα στις προϊστορικές φάσεις.', 'Δεν υπάρχει γνωστός κτήτορας· συνδέεται με προϊστορικές κοινότητες της Μαγνησίας.', 'Οργανωμένος οικισμός και αργότερα μυκηναϊκό κέντρο της περιοχής.', 'Το Διμήνι είναι ένας μεγάλος και καλά οργανωμένος προϊστορικός οικισμός κοντά στον Βόλο. Ο νεολιθικός οικισμός βρίσκεται πάνω σε χαμηλό λόφο και είναι γνωστός για τους ομόκεντρους περιβόλους του. Η περιοχή έχει επίσης μυκηναϊκά κατάλοιπα.', 'Από νεολιθικός οικισμός συνέχισε να έχει σημασία και σε μεταγενέστερες προϊστορικές φάσεις.', 'easy', 'Εύκολη πρόσβαση με όχημα από τον Βόλο.', 'Προϊστορική Θεσσαλία / Μαγνησία', ARRAY['Σέσκλο', 'Θολωτός τάφος Λαμιόσπιτο', 'Αρχαιολογικό Μουσείο Βόλου']::text[], 'Οι ομόκεντροι περίβολοι του νεολιθικού οικισμού.', 'high', true, 'Manual-review import: mapped cleaned monument "Διμήνι" to catalog_id 99 "Μυκηναϊκός χώρος Διμήνι". Alternatives: 132: Παλαιά / Κλασική Άλος (0.044); 133: Νέα / Ελληνιστική Άλος (0.044); 1: Κορυφη Αυγο Παγγαιο (0.000).', ARRAY['odysseus_dimini']::text[], 'https://upload.wikimedia.org/wikipedia/commons/0/03/Dimini_DSC_2062a.jpg'),
  (193, 'theopetra-cave', 'Σπήλαιο Θεόπετρας', ARRAY['Σπήλαιο', 'Προϊστορικός χώρος']::text[], ARRAY['Παλαιολιθική', 'Μεσολιθική', 'Νεολιθική']::text[], 'Δεν είναι κτίσμα· φυσικό σπήλαιο με πολύ μακρά προϊστορική χρήση.', 'Παλαιολιθική - Νεολιθική περίοδος', 'Η προϊστορική χρήση εγκαταλείφθηκε σταδιακά, ενώ σήμερα ο χώρος προστατεύεται.', 'Δεν χτίστηκε από κάποιον· χρησιμοποιήθηκε από προϊστορικές κοινότητες.', 'Κατοίκηση, καταφύγιο και δραστηριότητες προϊστορικών ομάδων.', 'Το Σπήλαιο Θεόπετρας ανοίγεται στη βορειοανατολική πλευρά ασβεστολιθικού εξάρματος στην περιοχή των Τρικάλων. Είναι από τους σημαντικότερους προϊστορικούς χώρους της Θεσσαλίας, με μεγάλη χρονική διάρκεια κατοίκησης και πλούσια αρχαιολογικά δεδομένα.', 'Από προϊστορικός χώρος κατοίκησης μετατράπηκε σε αρχαιολογικό χώρο και κέντρο τεκμηρίωσης.', 'medium', 'Η πρόσβαση στην περιοχή είναι εύκολη, αλλά η επισκεψιμότητα του σπηλαίου χρειάζεται έλεγχο πριν την επίσκεψη.', 'Προϊστορική Θεσσαλία / Τρίκαλα', ARRAY['Κέντρο Τεκμηρίωσης Θεόπετρας', 'Μετέωρα', 'Προϊστορική Θεσσαλία']::text[], 'Η είσοδος του σπηλαίου στον ασβεστολιθικό βράχο.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_theopetra_cave']::text[], 'https://upload.wikimedia.org/wikipedia/commons/5/52/%CE%A3%CF%80%CE%AE%CE%BB%CE%B1%CE%B9%CE%BF_%CE%98%CE%B5%CF%8C%CF%80%CE%B5%CF%84%CF%81%CE%B1%CF%82.jpg'),
  (56, 'eupalinos-tunnel', 'Ευπαλίνειο Όρυγμα', ARRAY['Υδραγωγείο', 'Σήραγγα', 'Μηχανικό έργο', 'UNESCO']::text[], ARRAY['Αρχαϊκή']::text[], '6ος αιώνας π.Χ.', 'Αρχαϊκή περίοδος και μεταγενέστερη χρήση ως υδραγωγείο', 'Έπαψε να χρησιμοποιείται ως υδραγωγείο στους μεταγενέστερους χρόνους.', 'Αποδίδεται στον μηχανικό Ευπαλίνο από τα Μέγαρα, την εποχή του τυράννου Πολυκράτη.', 'Υδροδότηση της αρχαίας πόλης της Σάμου μέσω σήραγγας μέσα στο βουνό.', 'Το Ευπαλίνειο Όρυγμα είναι ένα από τα σημαντικότερα τεχνικά έργα της αρχαιότητας. Πρόκειται για σήραγγα μήκους περίπου 1.036 μέτρων, σχεδιασμένη για την υδροδότηση της αρχαίας Σάμου. Η σημασία του βρίσκεται και στην ακρίβεια της διάνοιξής του από δύο αντίθετες κατευθύνσεις.', 'Από λειτουργικό υδραγωγείο μετατράπηκε σε επισκέψιμο μνημείο μηχανικής.', 'medium', 'Προσβάσιμο με οργανωμένες διαδρομές, αλλά το εσωτερικό έχει στενά σημεία και χρειάζεται προσοχή.', 'Αρχαία Σάμος / Πυθαγόρειο', ARRAY['Πυθαγόρειο Σάμου', 'Ηραίο Σάμου', 'Αρχαία πόλη Σάμου']::text[], 'Το εσωτερικό της σήραγγας ή η είσοδος του ορύγματος.', 'high', false, 'Imported from cleaned 217 dataset. Match method: fuzzy (0.740).', ARRAY['odysseus_eupalinos_tunnel']::text[], 'https://upload.wikimedia.org/wikipedia/commons/0/0a/Eupalinian_aqueduct.JPG'),
  (84, 'poliochni', 'Πολιόχνη Λήμνου', ARRAY['Προϊστορικός οικισμός', 'Πρωτοαστικό κέντρο']::text[], ARRAY['Πρώιμη Εποχή Χαλκού']::text[], 'Η ανάπτυξη του οικισμού τοποθετείται στην Πρώιμη Εποχή του Χαλκού.', '3η χιλιετία π.Χ.', 'Ο οικισμός εγκαταλείφθηκε μετά από διαδοχικές προϊστορικές φάσεις.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· πρόκειται για προϊστορική κοινότητα της Λήμνου.', 'Πρωτοαστικός οικισμός με οργανωμένη κοινωνική και οικιστική δομή στο βόρειο Αιγαίο.', 'Η Πολιόχνη στην ανατολική Λήμνο θεωρείται ένα από τα μεγάλα πρωτοαστικά κέντρα της Πρώιμης Εποχής του Χαλκού. Η ανάπτυξή της συνδέεται με τη στρατηγική θέση της στο βόρειο Αιγαίο και την οργάνωση της προϊστορικής κοινωνίας.', 'Από προϊστορικός οικισμός μετατράπηκε σε οργανωμένο αρχαιολογικό χώρο.', 'medium', 'Προσβάσιμη με όχημα στην περιοχή Καμίνια της Λήμνου, αφού πρώτα φτάσεις στο νησί.', 'Προϊστορική Λήμνος / Βόρειο Αιγαίο', ARRAY['Ηφαιστία', 'Κουκονήσι', 'Αρχαιολογικό Μουσείο Λήμνου']::text[], 'Γενική άποψη των ερειπίων της Πολιόχνης με το αιγαιοπελαγίτικο τοπίο.', 'high', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['odysseus_poliochni']::text[], 'https://upload.wikimedia.org/wikipedia/commons/2/2b/Poliochne.jpg'),
  (115, 'akrotiri-thera', 'Ακρωτήρι Θήρας', ARRAY['Προϊστορική πόλη', 'Οικισμός', 'Μινωικός κόσμος Αιγαίου']::text[], ARRAY['Νεολιθική', 'Πρώιμη Εποχή Χαλκού', 'Μέση Εποχή Χαλκού', 'Ύστερη Εποχή Χαλκού']::text[], 'Οι πρώτες εγκαταστάσεις χρονολογούνται στην Ύστερη Νεολιθική Εποχή.', 'Προϊστορική περίοδος, με μεγάλη ακμή στην Ύστερη Εποχή του Χαλκού', 'Ο οικισμός καλύφθηκε από τα ηφαιστειακά υλικά της μεγάλης έκρηξης της Θήρας.', 'Δεν υπάρχει γνωστός κτήτορας· πρόκειται για οργανωμένη προϊστορική κοινότητα του Αιγαίου.', 'Οικιστικό, εμπορικό και ναυτικό κέντρο του προϊστορικού Αιγαίου.', 'Το Ακρωτήρι της Θήρας είναι ένα από τα σημαντικότερα προϊστορικά κέντρα του Αιγαίου. Ο οικισμός διατηρήθηκε εξαιρετικά λόγω της ηφαιστειακής τέφρας, αποκαλύπτοντας πολυώροφα κτήρια, δρόμους, τοιχογραφίες και στοιχεία προηγμένης οργάνωσης.', 'Από ζωντανός προϊστορικός οικισμός μετατράπηκε, μετά την καταστροφή από το ηφαίστειο, σε αρχαιολογικό χώρο μοναδικής διατήρησης.', 'easy', 'Εύκολη πρόσβαση με όχημα ή λεωφορείο στη Σαντορίνη· ο χώρος είναι στεγασμένος και οργανωμένος.', 'Προϊστορική Θήρα / Κυκλάδες', ARRAY['Μουσείο Προϊστορικής Θήρας', 'Αρχαία Θήρα', 'Ηφαίστειο Σαντορίνης']::text[], 'Οι δρόμοι και τα πολυώροφα κτήρια του στεγασμένου προϊστορικού οικισμού.', 'high', true, 'Manual-review import: mapped cleaned monument "Ακρωτήρι Θήρας" to catalog_id 115 "Προϊστορική πόλη Ακρωτήρι Θήρας". Alternatives: 114: Αρχαία Θήρα (0.147); 201: Μυκηναϊκή Ακρόπολη Σίφνου, (0.055); 83: Αρχαία Καρθαία (0.044).', ARRAY['odysseus_akrotiri_thera']::text[], 'https://upload.wikimedia.org/wikipedia/commons/5/5a/Ancient_Akrotiri.jpeg'),
  (177, 'acropolis-of-lindos', 'Ακρόπολη Λίνδου', ARRAY['Ακρόπολη', 'Ιερό', 'Πόλη', 'Οχύρωση']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή', 'Μεσαιωνική']::text[], 'Η μεγάλη ακμή της Λίνδου τοποθετείται κυρίως στον 7ο-6ο αιώνα π.Χ., ενώ τα μνημεία της ακρόπολης έχουν πολλές φάσεις.', 'Αρχαϊκή - Ρωμαϊκή περίοδος, με μεταγενέστερη μεσαιωνική χρήση', 'Η ακρόπολη άλλαξε χρήσεις και μορφή σε μεταγενέστερες περιόδους, ιδιαίτερα στη μεσαιωνική εποχή.', 'Αναπτύχθηκε από την αρχαία πόλη της Λίνδου και μεταγενέστερους κυρίαρχους της Ρόδου.', 'Θρησκευτικό, πολιτικό και αμυντικό κέντρο της Λίνδου.', 'Η Ακρόπολη της Λίνδου δεσπόζει πάνω από τον οικισμό και τη θάλασσα. Ήταν το κέντρο της ζωής της αρχαίας πόλης και περιλαμβάνει το ιερό της Αθηνάς Λινδίας, ελληνιστικές στοές και μεταγενέστερες οχυρώσεις. Είναι ένα από τα πιο αναγνωρίσιμα μνημεία της Ρόδου.', 'Από αρχαίο θρησκευτικό και πολιτικό κέντρο μετατράπηκε σε οχυρωμένο μεσαιωνικό χώρο και σήμερα σε αρχαιολογικό μνημείο.', 'medium', 'Η πρόσβαση γίνεται με ανάβαση προς την ακρόπολη και μπορεί να είναι κουραστική, ειδικά με ζέστη.', 'Λίνδος / Ρόδος', ARRAY['Ιερό Αθηνάς Λινδίας', 'Ελληνιστική στοά', 'Μεσαιωνικό κάστρο', 'Αρχαία Κάμειρος']::text[], 'Η ακρόπολη της Λίνδου από ψηλά με φόντο τον κόλπο.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_lindos']::text[], 'https://upload.wikimedia.org/wikipedia/commons/e/e9/20210826-Lindos-DJI_0205.jpg'),
  (21, 'kerameikos', 'Κεραμεικός', ARRAY['Νεκροταφείο', 'Δήμος', 'Οχύρωση', 'Μουσείο']::text[], ARRAY['Γεωμετρική', 'Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η περιοχή χρησιμοποιείται από τους προϊστορικούς χρόνους και οργανώνεται έντονα στους ιστορικούς χρόνους.', 'Αρχαϊκή περίοδος - Ρωμαϊκή περίοδος', 'Η αρχαία χρήση σταμάτησε σταδιακά στους μεταγενέστερους χρόνους.', 'Δεν χτίστηκε από ένα πρόσωπο· ήταν περιοχή του αθηναϊκού δήμου των Κεραμέων.', 'Νεκροταφείο, περιοχή εργαστηρίων κεραμέων και βασική ζώνη εισόδου/εξόδου της αρχαίας Αθήνας.', 'Ο Κεραμεικός ήταν μία από τις σημαντικότερες περιοχές της αρχαίας Αθήνας. Υπήρξε ο κύριος χώρος παραγωγής αττικών αγγείων και ένα από τα σημαντικότερα νεκροταφεία της πόλης, ενώ από εκεί περνούσαν μεγάλοι δρόμοι όπως η Ιερά Οδός και η οδός προς την Ακαδημία.', 'Από ζωντανή συνοικία κεραμέων και νεκροταφείο μετατράπηκε σε οργανωμένο αρχαιολογικό χώρο και μουσείο.', 'easy', 'Εύκολη πρόσβαση στο κέντρο της Αθήνας, κοντά σε μετρό και στην Αρχαία Αγορά.', 'Αθήνα / Αθηναϊκή πόλη-κράτος', ARRAY['Αρχαία Αγορά', 'Ιερά Οδός', 'Δίπυλο', 'Πομπείον', 'Ακαδημία Πλάτωνος']::text[], 'Γενική άποψη του αρχαιολογικού χώρου με ταφικά μνημεία ή το Δίπυλο.', 'high', true, 'Manual-review import: mapped cleaned monument "Κεραμεικός" to catalog_id 21 "Κεραμεικός, νεκροταφείο". Alternatives: 5: Πιθανή θέση της Ποικίλης Στοάς (0.110); 76: Ακαδημία Πλάτωνος (0.110); 10: Στοά Ευμένους (0.094).', ARRAY['odysseus_kerameikos']::text[], 'https://upload.wikimedia.org/wikipedia/commons/3/39/Kerameikos_Cemetery_on_July_28%2C_2019.jpg'),
  (76, 'akadimia-platonos', 'Ακαδημία Πλάτωνος', ARRAY['Φιλοσοφική σχολή', 'Ιερό άλσος', 'Δημόσιος χώρος']::text[], ARRAY['Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Ο χώρος ήταν γνωστός ως ιερό άλσος ήδη πριν από την ίδρυση της φιλοσοφικής σχολής του Πλάτωνα.', '4ος αιώνας π.Χ. - Ρωμαϊκή περίοδος', 'Η εκπαιδευτική χρήση σταμάτησε σταδιακά στην ύστερη αρχαιότητα.', 'Η σχολή συνδέεται με τον Πλάτωνα, ενώ ο χώρος προϋπήρχε ως δημόσιο και ιερό τοπίο της Αθήνας.', 'Φιλοσοφική διδασκαλία, άθληση και λατρευτική χρήση.', 'Η Ακαδημία Πλάτωνος ήταν ένας από τους σημαντικότερους πνευματικούς χώρους της αρχαιότητας. Εκεί ο Πλάτων ίδρυσε τη φιλοσοφική του σχολή τον 4ο αιώνα π.Χ., σε περιοχή που συνδεόταν ήδη με άλσος, γυμνάσιο και λατρευτικές παραδόσεις.', 'Από άλσος και γυμνάσιο έγινε φιλοσοφικό κέντρο και σήμερα είναι αστικός αρχαιολογικός χώρος.', 'easy', 'Εύκολη πρόσβαση μέσα στην Αθήνα, αν και ο χώρος είναι περισσότερο ανοιχτό πάρκο παρά εντυπωσιακό μνημείο.', 'Αθήνα / Αττική', ARRAY['Κεραμεικός', 'Ιερά Οδός', 'Αρχαία Αγορά']::text[], 'Χαμηλή λήψη του αρχαιολογικού πάρκου με ενημερωτική πινακίδα ή κατάλοιπα θεμελίων.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_academy_plato']::text[], ''),
  (10, 'stoa-eymenoys', 'Στοά Ευμένους', ARRAY['Στοά', 'Δημόσιο κτήριο', 'Θέατρο']::text[], ARRAY['Ελληνιστική', 'Ρωμαϊκή']::text[], '2ος αιώνας π.Χ.', 'Ελληνιστική - Ρωμαϊκή περίοδος', 'Η χρήση της σταμάτησε με την παρακμή των αρχαίων θεάτρων και οικοδομημάτων της νότιας κλιτύος.', 'Χτίστηκε από τον Ευμένη Β΄ της Περγάμου.', 'Στέγαση και εξυπηρέτηση των θεατών του Θεάτρου Διονύσου και σύνδεση της περιοχής με το Ωδείο Ηρώδου Αττικού.', 'Η Στοά του Ευμένους βρίσκεται στη νότια κλιτύ της Ακρόπολης, ανάμεσα στο Θέατρο Διονύσου και το Ωδείο Ηρώδου Αττικού. Ήταν μακρόστενο διώροφο οικοδόμημα που πρόσφερε προστατευμένο χώρο περιπάτου και συγκέντρωσης στους θεατές.', 'Από δημόσιο εξυπηρετικό κτήριο θεατρικής περιοχής μετατράπηκε σε αρχαιολογικό κατάλοιπο.', 'easy', 'Εύκολη πρόσβαση μέσα στον ενιαίο αρχαιολογικό χώρο της Ακρόπολης.', 'Αθήνα / Αττική', ARRAY['Θέατρο Διονύσου', 'Ωδείο Ηρώδου Αττικού', 'Ακρόπολη']::text[], 'Άποψη της στοάς κατά μήκος της νότιας κλιτύος της Ακρόπολης.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_south_slope_acropolis']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/%CE%97_%CE%A3%CF%84%CE%BF%CE%AC_%CF%84%CE%BF%CF%85_%CE%95%CF%85%CE%BC%CE%AD%CE%BD%CE%BF%CF%85%CF%82_%CF%83%CF%84%CE%B9%CF%82_16_%CE%A3%CE%B5%CF%80%CF%84%CE%B5%CE%BC%CE%B2%CF%81%CE%AF%CE%BF%CF%85_2019.jpg'),
  (13, 'asklipieio-akropolis', 'Ασκληπιείο Ακρόπολης', ARRAY['Ιερό', 'Θεραπευτικό κέντρο']::text[], ARRAY['Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Ιδρύθηκε στα τέλη του 5ου αιώνα π.Χ.', 'Κλασική - Ρωμαϊκή περίοδος', 'Η λατρευτική χρήση σταμάτησε μετά την αρχαιότητα.', 'Συνδέεται με την εισαγωγή της λατρείας του Ασκληπιού στην Αθήνα.', 'Λατρεία του Ασκληπιού και θεραπευτικές τελετουργίες.', 'Το Ασκληπιείο της Ακρόπολης ήταν ιερό αφιερωμένο στον Ασκληπιό, θεό της ιατρικής και της θεραπείας. Βρισκόταν στη νότια κλιτύ της Ακρόπολης και συνδεόταν με τελετουργίες ίασης, αφιερώματα ασθενών και χρήση πηγής/νερού.', 'Από θεραπευτικό ιερό έγινε αρχαιολογικό κατάλοιπο ενταγμένο στον χώρο της Ακρόπολης.', 'easy', 'Εύκολη πρόσβαση μέσω του αρχαιολογικού χώρου της νότιας κλιτύος.', 'Αθήνα / Αττική', ARRAY['Θέατρο Διονύσου', 'Στοά Ευμένους', 'Ακρόπολη']::text[], 'Τα κατάλοιπα του ιερού κάτω από τον βράχο της Ακρόπολης.', 'high', true, 'Manual-review import: mapped cleaned monument "Ασκληπιείο Ακρόπολης" to catalog_id 13 "Ιερό/Ασκληπιείο κάτω από την Ακρόπολη". Alternatives: 12: Ασκληπιείο Αρχαίας Μεσσήνης (0.195); 11: Κλεψύδρα και μυκηναϊκή κρυφή πρόσβαση της βόρειας κλιτύος (0.157); 5: Πιθανή θέση της Ποικίλης Στοάς (0.083).', ARRAY['odysseus_south_slope_acropolis']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Asclepieion_of_Athens_from_the_Acropolis.jpg'),
  (81, 'ramnoys-iero-nemesis', 'Ραμνούς / Ιερό Νέμεσης', ARRAY['Ιερό', 'Οχυρωμένος δήμος', 'Θέατρο']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική']::text[], 'Το ιερό της Νέμεσης ιδρύθηκε πιθανότατα στις αρχές του 6ου αιώνα π.Χ.', '6ος - 4ος αιώνας π.Χ.', 'Η χρήση του χώρου περιορίστηκε σταδιακά μετά την αρχαιότητα.', 'Αναπτύχθηκε από τον αρχαίο δήμο του Ραμνούντα και την αθηναϊκή πολιτεία.', 'Λατρεία της Νέμεσης και έλεγχος στρατηγικής θέσης στην ανατολική Αττική.', 'Ο Ραμνούς ήταν σημαντικός αρχαίος δήμος της Αττικής. Στον χώρο σώζονται το ιερό της Νέμεσης, ερείπια φρουρίου, οικισμού, θεάτρου και ταφικών δρόμων. Η θέση του είχε στρατηγική σημασία απέναντι από τον Ευβοϊκό.', 'Από δήμος και ιερό της Αττικής έγινε αρχαιολογικός χώρος με επιμέρους ζώνες επίσκεψης.', 'medium', 'Η πρόσβαση γίνεται με όχημα· ο χώρος έχει σημεία με περπάτημα και όχι πάντα πλήρη πρόσβαση σε όλα τα τμήματα.', 'Ραμνούς / Αττική / Αθήνα', ARRAY['Ιερό Νέμεσης', 'Φρούριο Ραμνούντα', 'Θέατρο Ραμνούντα']::text[], 'Τα ερείπια του ιερού με θέα προς τη θάλασσα.', 'high', false, 'Imported from cleaned 217 dataset. Match method: fuzzy (0.740).', ARRAY['odysseus_ramnous']::text[], 'https://upload.wikimedia.org/wikipedia/commons/c/cc/Remains_of_the_ancient_city_of_Rhamnous_on_July_22%2C_2020.jpg'),
  (40, 'amfiareio-oropoy', 'Αμφιάρειο Ωρωπού', ARRAY['Ιερό', 'Μαντείο', 'Θεραπευτικό κέντρο', 'Θέατρο']::text[], ARRAY['Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Ιδρύθηκε στα τέλη του 5ου αιώνα π.Χ.', '4ος αιώνας π.Χ. - Ρωμαϊκή περίοδος', 'Η λειτουργία του σταμάτησε μετά την αρχαιότητα.', 'Ιδρύθηκε όταν ο Ωρωπός βρισκόταν υπό αθηναϊκή επιρροή.', 'Λατρεία του ήρωα-θεού Αμφιαράου, μαντική και θεραπευτική χρήση.', 'Το Αμφιάρειο ήταν το σημαντικότερο ιερό του Αμφιαράου στην αρχαία Ελλάδα. Βρίσκεται σε μικρή κοιλάδα κοντά στον Ωρωπό και περιλάμβανε ναό, βωμό, στοές, θέατρο και χώρους για τους επισκέπτες που ζητούσαν χρησμό ή θεραπεία.', 'Από ενεργό μαντικό και θεραπευτικό ιερό μετατράπηκε σε αρχαιολογικό χώρο.', 'easy', 'Σχετικά εύκολη πρόσβαση με όχημα από τον Ωρωπό.', 'Ωρωπός / Αττική και Βοιωτία', ARRAY['Ναός Αμφιαράου', 'Θέατρο Αμφιαρείου', 'Στοές', 'Ιερή πηγή']::text[], 'Το θέατρο ή η κοιλάδα του ιερού με τα βασικά κατάλοιπα.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_amphiareion_oropos']::text[], 'https://upload.wikimedia.org/wikipedia/commons/6/63/Theatre_of_Amphiareion_in_Oropos_%28%CE%98%CE%AD%CE%B1%CF%84%CF%81%CE%BF_%CE%91%CE%BC%CF%86%CE%B9%CE%AC%CF%81%CE%B5%CE%B9%CE%BF%CF%85_%CE%A9%CF%81%CF%89%CF%80%CE%BF%CF%8D%29.jpg'),
  (199, 'kolona-aiginas-naos-apollona', 'Κολώνα Αίγινας / Ναός Απόλλωνα', ARRAY['Ακρόπολη', 'Ναός', 'Πόλη']::text[], ARRAY['Προϊστορική', 'Αρχαϊκή', 'Κλασική']::text[], 'Η περιοχή κατοικήθηκε από την προϊστορική εποχή· ο ναός του Απόλλωνα ανήκει στους αρχαϊκούς χρόνους.', 'Προϊστορική εποχή - Κλασική περίοδος', 'Η αρχαία χρήση μεταβλήθηκε με την εγκατάλειψη της παλιάς πόλης.', 'Αναπτύχθηκε από την κοινότητα της αρχαίας Αίγινας.', 'Ακρόπολη και λατρευτικό κέντρο της αρχαίας πόλης της Αίγινας.', 'Η Κολώνα είναι ο αρχαιολογικός χώρος της αρχαίας πόλης της Αίγινας, κοντά στο σημερινό λιμάνι. Το όνομα προέρχεται από τον όρθιο κίονα του ναού του Απόλλωνα, που αποτελεί χαρακτηριστικό τοπόσημο του χώρου.', 'Από ακρόπολη και λατρευτικό κέντρο έγινε αρχαιολογικός χώρος κοντά στο σύγχρονο λιμάνι.', 'easy', 'Πολύ εύκολη πρόσβαση από το λιμάνι της Αίγινας.', 'Αρχαία Αίγινα', ARRAY['Ναός Αφαίας', 'Αρχαιολογικό Μουσείο Αίγινας', 'Λιμάνι Αίγινας']::text[], 'Ο μοναχικός κίονας του ναού με φόντο τη θάλασσα.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_aegina_kolona']::text[], ''),
  (102, 'ochyro-eleytheron-gyftokastro', 'Οχυρό Ελευθερών / Γυφτόκαστρο', ARRAY['Φρούριο', 'Οχύρωση']::text[], ARRAY['Κλασική', 'Ελληνιστική']::text[], 'Κλασική περίοδος.', '4ος αιώνας π.Χ. - Ελληνιστική περίοδος', 'Το οχυρό εγκαταλείφθηκε μετά τη στρατιωτική του χρήση.', 'Συνδέεται με την αμυντική οργάνωση της Αττικής και της περιοχής των Ελευθερών.', 'Έλεγχος περάσματος μεταξύ Αττικής και Βοιωτίας.', 'Το οχυρό των Ελευθερών, γνωστό και ως Γυφτόκαστρο, είναι ένα από τα καλύτερα σωζόμενα αρχαία φρούρια της Αττικής. Βρίσκεται σε θέση που ελέγχει σημαντικό πέρασμα προς τη Βοιωτία.', 'Από στρατιωτικό οχυρό έγινε αρχαιολογικό μνημείο σε ορεινό πέρασμα.', 'medium', 'Πρόσβαση με όχημα μέχρι κοντινό σημείο και μετά σύντομο περπάτημα/προσοχή στο έδαφος.', 'Αττική / σύνορα με Βοιωτία', ARRAY['Αρχαίο Φρούριο Αιγοσθένων', 'Κιθαιρώνας', 'Ελευσίνα']::text[], 'Τα σωζόμενα τείχη και οι πύργοι του φρουρίου.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_eleutheres_fortress']::text[], ''),
  (35, 'iero-afroditis-stin-iera-odo', 'Ιερό Αφροδίτης στην Ιερά Οδό', ARRAY['Ιερό', 'Λατρευτικός χώρος', 'Ιερά Οδός']::text[], ARRAY['Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Κλασική περίοδος.', 'Κλασική - Ρωμαϊκή περίοδος', 'Η λατρεία σταμάτησε μετά την αρχαιότητα.', 'Συνδέεται με την αθηναϊκή λατρευτική τοπογραφία της Ιεράς Οδού.', 'Λατρεία της Αφροδίτης σε σημείο της διαδρομής Αθήνας-Ελευσίνας.', 'Το Ιερό της Αφροδίτης βρίσκεται κοντά στη Μονή Δαφνίου, πάνω στην αρχαία Ιερά Οδό που ένωνε την Αθήνα με την Ελευσίνα. Η θέση του το συνδέει άμεσα με τη μεγάλη πομπική διαδρομή των Ελευσίνιων Μυστηρίων.', 'Από μικρό ιερό της Ιεράς Οδού έγινε αρχαιολογικό κατάλοιπο μέσα στον σύγχρονο αστικό ιστό.', 'easy', 'Σχετικά εύκολη πρόσβαση από την περιοχή Δαφνίου/Χαϊδαρίου.', 'Αθήνα / Αττική', ARRAY['Ιερά Οδός', 'Ελευσίνα', 'Μονή Δαφνίου']::text[], 'Τα λαξευμένα κατάλοιπα και το φυσικό βραχώδες περιβάλλον του ιερού.', 'medium', true, 'Manual-review import: mapped cleaned monument "Ιερό Αφροδίτης στην Ιερά Οδό" to catalog_id 35 "Ιερό της Αφροδίτης". Alternatives: 15: Αρχαία γέφυρα/διάβαση του Κηφισού στην Ιερά Οδό (0.272); 33: Ιερό των Μουσών (0.156); 223: Αρχαϊκό ιερό (0.156).', ARRAY['odysseus_aphrodite_daphni']::text[], ''),
  (106, 'archaia-asini', 'Αρχαία Ασίνη', ARRAY['Ακρόπολη', 'Οικισμός', 'Οχύρωση']::text[], ARRAY['Προϊστορική', 'Μυκηναϊκή', 'Γεωμετρική', 'Κλασική', 'Ελληνιστική']::text[], 'Ο χώρος κατοικήθηκε από την προϊστορική εποχή.', 'Μυκηναϊκή περίοδος - Ελληνιστική περίοδος', 'Η κατοίκηση και χρήση άλλαξαν πολλές φορές στους ιστορικούς χρόνους.', 'Αναπτύχθηκε από τις κοινότητες της περιοχής της Ασίνης.', 'Οικισμός και οχυρωμένη ακρόπολη σε στρατηγικό παραθαλάσσιο σημείο.', 'Η Αρχαία Ασίνη βρίσκεται σε βραχώδη λόφο δίπλα στη θάλασσα, κοντά στο Τολό. Αναφέρεται ήδη στον Όμηρο και ο χώρος διατηρεί κατάλοιπα από πολλές περιόδους, δείχνοντας τη διαχρονική σημασία της θέσης.', 'Από προϊστορικός και αρχαίος οικισμός έγινε οχυρωμένος χώρος και σήμερα αρχαιολογικό μνημείο.', 'easy', 'Εύκολη πρόσβαση με όχημα, κοντά στο Τολό και το Ναύπλιο.', 'Αργολίδα / Ασίνη', ARRAY['Τολό', 'Ναύπλιο', 'Μιδέα', 'Λέρνα']::text[], 'Η ακρόπολη της Ασίνης πάνω στον βραχώδη λόφο δίπλα στη θάλασσα.', 'high', true, 'Manual-review import: mapped cleaned monument "Αρχαία Ασίνη" to catalog_id 106 "Αρχαία Ασίνη / Καστράκι Τολού". Alternatives: 105: Μυκηναϊκή Ακρόπολη Μιδέας (0.055); 144: [χωρίς όνομα] (0.044); 43: Αρχαίοτερο γεφύρι στο Αρκαδικό (0.037).', ARRAY['odysseus_asini']::text[], ''),
  (105, 'mykinaiki-akropoli-mideas', 'Μυκηναϊκή Ακρόπολη Μιδέας', ARRAY['Ακρόπολη', 'Μυκηναϊκή οχύρωση']::text[], ARRAY['Μυκηναϊκή']::text[], '13ος αιώνας π.Χ. για την κύρια οχυρωματική φάση.', 'Ύστερη Εποχή του Χαλκού', 'Η μυκηναϊκή ακρόπολη καταστράφηκε ή εγκαταλείφθηκε στο τέλος της μυκηναϊκής περιόδου.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· συνδέεται με το μυκηναϊκό σύστημα της Αργολίδας.', 'Οχυρωμένο διοικητικό και στρατηγικό κέντρο.', 'Η Μιδέα είναι μία από τις σημαντικές μυκηναϊκές ακροπόλεις της Αργολίδας. Η ισχυρή οχύρωση και η θέση της ανάμεσα σε άλλα μεγάλα μυκηναϊκά κέντρα δείχνουν ότι αποτελούσε σημαντικό κρίκο στο δίκτυο της μυκηναϊκής Αργολίδας.', 'Από μυκηναϊκή ακρόπολη έγινε αρχαιολογικός χώρος.', 'medium', 'Πρόσβαση με όχημα μέχρι κοντά στον χώρο και περπάτημα σε αρχαιολογικό/φυσικό έδαφος.', 'Μυκηναϊκή Αργολίδα', ARRAY['Λέρνα', 'Ασίνη', 'Μυκήνες', 'Τίρυνθα']::text[], 'Τα κυκλώπεια τείχη της ακρόπολης με θέα στην Αργολίδα.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_midea']::text[], ''),
  (43, 'mykinaiki-gefyra-kazarmas-arkadikoy', 'Μυκηναϊκή Γέφυρα Καζάρμας / Αρκαδικού', ARRAY['Γέφυρα', 'Μυκηναϊκό έργο', 'Οδικό δίκτυο']::text[], ARRAY['Μυκηναϊκή']::text[], '13ος αιώνας π.Χ. περίπου.', 'Μυκηναϊκή περίοδος', 'Η αρχική χρήση της ως τμήμα μυκηναϊκού δρόμου έπαψε μετά την αρχαιότητα, αλλά το μνημείο διατηρείται.', 'Συνδέεται με το μυκηναϊκό οδικό δίκτυο της Αργολίδας.', 'Διευκόλυνση μετακίνησης σε δρόμο που συνέδεε μυκηναϊκά κέντρα.', 'Η Μυκηναϊκή Γέφυρα της Καζάρμας, κοντά στο Αρκαδικό, θεωρείται από τα παλαιότερα σωζόμενα γεφύρια της Ευρώπης. Είναι κατασκευασμένη με κυκλώπεια τεχνική και συνδεόταν με τον μυκηναϊκό δρόμο της Αργολίδας.', 'Από λειτουργική γέφυρα μυκηναϊκού δρόμου έγινε αρχαιολογικό μνημείο.', 'easy', 'Εύκολη πρόσβαση από τον δρόμο, με σύντομη στάση.', 'Μυκηναϊκή Αργολίδα', ARRAY['Μιδέα', 'Τίρυνθα', 'Επίδαυρος', 'Μυκηναϊκοί δρόμοι']::text[], 'Η καμάρα της γέφυρας και η κυκλώπεια λιθοδομή.', 'high', true, 'Manual-review import: mapped cleaned monument "Μυκηναϊκή Γέφυρα Καζάρμας / Αρκαδικού" to catalog_id 43 "Αρχαίοτερο γεφύρι στο Αρκαδικό". Alternatives: 201: Μυκηναϊκή Ακρόπολη Σίφνου, (0.130); 15: Αρχαία γέφυρα/διάβαση του Κηφισού στην Ιερά Οδό (0.098); 51: Ρωμαϊκή Γέφυρα στον Ελευσινιακό Κηφισό (0.098).', ARRAY['odysseus_kazarma_bridge']::text[], ''),
  (3, 'iraio-perachoras', 'Ηραίο Περαχώρας', ARRAY['Ιερό', 'Λιμάνι', 'Υδραυλικά έργα']::text[], ARRAY['Γεωμετρική', 'Αρχαϊκή', 'Κλασική']::text[], 'Η χρήση του ιερού ξεκινά από τους γεωμετρικούς και αρχαϊκούς χρόνους.', 'Γεωμετρική - Κλασική περίοδος', 'Η λατρευτική χρήση σταμάτησε μετά την αρχαιότητα.', 'Αναπτύχθηκε από την Κόρινθο και τις κοινότητες της περιοχής.', 'Λατρεία της Ήρας σε στρατηγικό παραθαλάσσιο ιερό.', 'Το Ηραίο Περαχώρας βρίσκεται κοντά στη λίμνη Βουλιαγμένης και τον Κορινθιακό κόλπο. Ήταν σημαντικό ιερό της Ήρας, με ναούς, βωμούς, δεξαμενές και λιμενικές εγκαταστάσεις, δείχνοντας τη σύνδεση λατρείας και θαλάσσιας δραστηριότητας.', 'Από ενεργό ιερό της Κορινθίας έγινε ελεύθερα προσβάσιμος αρχαιολογικός χώρος.', 'easy', 'Εύκολη πρόσβαση με όχημα, με περπάτημα μέσα στον χώρο.', 'Κόρινθος / Περαχώρα', ARRAY['Αρχαία Κόρινθος', 'Λίμνη Βουλιαγμένης Περαχώρας', 'Κρήνη και δεξαμενές Ηραίου']::text[], 'Το ιερό με τη θάλασσα και το φυσικό τοπίο του Κορινθιακού.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_heraion_perachora']::text[], 'https://upload.wikimedia.org/wikipedia/commons/a/ab/%CE%A0%CE%B5%CF%81%CE%B1%CF%87%CF%8E%CF%81%CE%B1_%CE%9A%CE%BF%CF%81%CE%B9%CE%BD%CE%B8%CE%AF%CE%B1%CF%82.jpg'),
  (59, 'archaios-limenas-kegchreon', 'Αρχαίος λιμένας Κεγχρεών', ARRAY['Λιμάνι', 'Εμπορικό κέντρο', 'Ρωμαϊκό μνημείο']::text[], ARRAY['Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η θέση χρησιμοποιήθηκε ως λιμάνι της Κορίνθου ήδη στην αρχαιότητα.', 'Κλασική - Ρωμαϊκή περίοδος', 'Η χρήση του λιμανιού μεταβλήθηκε στους μεταγενέστερους χρόνους.', 'Αναπτύχθηκε από την πόλη της Κορίνθου.', 'Ανατολικό λιμάνι της Κορίνθου προς τον Σαρωνικό και το Αιγαίο.', 'Οι Κεγχρεές ήταν το ανατολικό λιμάνι της αρχαίας Κορίνθου. Η θέση τους επέτρεπε εμπορική και ναυτική επικοινωνία με το Αιγαίο, ενώ στην περιοχή σώζονται κατάλοιπα λιμενικών εγκαταστάσεων και κτηρίων, ιδιαίτερα από τους ρωμαϊκούς χρόνους.', 'Από κύριο αρχαίο λιμάνι της Κορίνθου έγινε παραθαλάσσιος αρχαιολογικός χώρος.', 'easy', 'Εύκολη πρόσβαση με όχημα, κοντά στον σύγχρονο οικισμό Κεχριές.', 'Κόρινθος / Κορινθιακή πόλη-κράτος', ARRAY['Αρχαία Κόρινθος', 'Ακροκόρινθος', 'Ισθμός', 'Λέχαιο']::text[], 'Τα λιμενικά κατάλοιπα στην ακτή των Κεγχρεών.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_kenchreai']::text[], ''),
  (104, 'archaia-stymfalos', 'Αρχαία Στύμφαλος', ARRAY['Πόλη', 'Ιερό', 'Λίμνη']::text[], ARRAY['Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η πόλη οργανώθηκε κυρίως στους κλασικούς και ελληνιστικούς χρόνους.', 'Κλασική - Ρωμαϊκή περίοδος', 'Η πόλη εγκαταλείφθηκε σταδιακά.', 'Αναπτύχθηκε από την αρχαία κοινότητα της Στυμφάλου.', 'Οχυρωμένη πόλη κοντά στη λίμνη Στυμφαλία, με πολιτική και λατρευτική λειτουργία.', 'Η Αρχαία Στύμφαλος βρίσκεται κοντά στη λίμνη που συνδέεται μυθολογικά με τις Στυμφαλίδες Όρνιθες του Ηρακλή. Ο αρχαιολογικός χώρος περιλαμβάνει κατάλοιπα πόλης, οχύρωσης και δημόσιων/λατρευτικών κτηρίων.', 'Από αρχαία πόλη της ορεινής Κορινθίας έγινε αρχαιολογικός χώρος σε φυσικό τοπίο.', 'medium', 'Πρόσβαση με όχημα στην περιοχή και περπάτημα σε ανοιχτό χώρο.', 'Στύμφαλος / Αρκαδία-Κορινθία', ARRAY['Λίμνη Στυμφαλία', 'Φενεός', 'Νεμέα']::text[], 'Ο αρχαιολογικός χώρος με φόντο τη λίμνη Στυμφαλία.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_stymphalos']::text[], ''),
  (6, 'archaios-feneos', 'Αρχαίος Φενεός', ARRAY['Πόλη', 'Οχύρωση', 'Μυθολογικό τοπίο']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η περιοχή είχε μακρά χρήση στην αρχαιότητα.', 'Κλασική - Ρωμαϊκή περίοδος', 'Η χρήση της αρχαίας πόλης σταμάτησε σταδιακά.', 'Αναπτύχθηκε από την κοινότητα του Φενεού.', 'Ορεινό αστικό κέντρο και έλεγχος της λεκάνης του Φενεού.', 'Ο αρχαίος Φενεός βρισκόταν σε ορεινή περιοχή της Κορινθίας, κοντά στη λίμνη Δόξα και στις καταβόθρες που συνδέονται με παραδόσεις για τον Ηρακλή. Η περιοχή είχε ιδιαίτερη σημασία λόγω της γεωγραφίας και της σχέσης της με τα νερά της λεκάνης.', 'Από ορεινή αρχαία πόλη έγινε αρχαιολογικό και τοπικό ιστορικό σημείο.', 'medium', 'Πρόσβαση με όχημα στην περιοχή, με πιθανό περπάτημα ανάλογα με το ακριβές σημείο.', 'Φενεός / Ορεινή Κορινθία', ARRAY['Στύμφαλος', 'Καταβόθρες Φενεού', 'Λίμνη Δόξα']::text[], 'Πανοραμική εικόνα της αρχαίας θέσης με το ορεινό τοπίο του Φενεού.', 'medium', true, 'Manual-review import: mapped cleaned monument "Αρχαίος Φενεός" to catalog_id 6 "Αρχαίος Φενεός και οι «καταβόθρες του Ηρακλή»". Alternatives: 44: Οι καταβόθρες του Ηρακλή στους αρχαίους Φενεούς (0.220); 60: Αρχαίος Ορχομενός Αρκαδίας (0.195); 25: Ρωμαϊκά λουτρά / βαλανεία στον αρχαιολογικό χώρο (0.073).', ARRAY['odysseus_feneos_museum']::text[], ''),
  (30, 'iero-despoinas-sti-lykosoyra', 'Ιερό Δέσποινας στη Λυκόσουρα', ARRAY['Ιερό', 'Λατρευτικό κέντρο']::text[], ARRAY['Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Το ιερό αναπτύχθηκε στους κλασικούς και ελληνιστικούς χρόνους.', 'Κλασική περίοδος - τέλος ρωμαϊκών χρόνων', 'Η λατρευτική χρήση έπαψε μετά την αρχαιότητα.', 'Αναπτύχθηκε από την αρκαδική κοινότητα της Λυκόσουρας.', 'Λατρεία της τοπικής θεότητας Δέσποινας και άλλων αρκαδικών θεοτήτων.', 'Το Ιερό της Δέσποινας στη Λυκόσουρα ήταν από τα σημαντικότερα ιερά της αρχαίας Αρκαδίας. Συνδέεται με ιδιαίτερη τοπική λατρεία και με σημαντικά γλυπτά και αναθήματα που δείχνουν τον έντονο θρησκευτικό χαρακτήρα του χώρου.', 'Από ενεργό αρκαδικό ιερό μετατράπηκε σε αρχαιολογικό χώρο και μικρό μουσείο.', 'medium', 'Πρόσβαση με όχημα στην περιοχή και περπάτημα στον χώρο.', 'Λυκόσουρα / Αρκαδία', ARRAY['Μουσείο Λυκόσουρας', 'Λύκαιο Όρος', 'Μεγαλόπολη']::text[], 'Τα κατάλοιπα του ιερού με το αρκαδικό ορεινό τοπίο.', 'high', true, 'Manual-review import: mapped cleaned monument "Ιερό Δέσποινας στη Λυκόσουρα" to catalog_id 30 "Βωμός της Δέσποινας στο ιερό της Αρκαδικής θεότητας". Alternatives: 33: Ιερό των Μουσών (0.195); 223: Αρχαϊκό ιερό (0.195); 14: Ιερό Αρτέμιδος Αυλιδείας (0.156).', ARRAY['odysseus_lykosoura_despina']::text[], 'https://upload.wikimedia.org/wikipedia/commons/4/4f/Archaeological_site_of_Lykosoura%2C_Temple_of_Despoina%2C_Lyko18.jpg'),
  (204, 'tainaro-iero-poseidona', 'Ταίναρο / Ιερό Ποσειδώνα', ARRAY['Ιερό', 'Σπήλαιο', 'Μυθολογικό τοπίο']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η λατρεία του Ποσειδώνα στο Ταίναρο είναι αρχαία και συνδέεται με το ακρωτήριο.', 'Αρχαϊκή - Ρωμαϊκή περίοδος', 'Η αρχαία λατρεία σταμάτησε μετά την αρχαιότητα.', 'Δεν συνδέεται με έναν συγκεκριμένο κτήτορα· ήταν ιερό τοπίο της Λακωνίας.', 'Λατρεία του Ποσειδώνα και σύνδεση με παραδόσεις για τον Κάτω Κόσμο.', 'Το Ταίναρο είναι το νοτιότερο άκρο της ηπειρωτικής Ελλάδας και στην αρχαιότητα συνδεόταν με ιερό του Ποσειδώνα και με μύθους για είσοδο στον Κάτω Κόσμο. Η δύναμη του μνημείου βρίσκεται στον συνδυασμό αρχαίας λατρείας, σπηλαίου και άγριου θαλάσσιου τοπίου.', 'Από ιερό και μυθολογικό σημείο έγινε ιστορικός και φυσικός προορισμός.', 'medium', 'Πρόσβαση με όχημα ως κοντινό σημείο και περπάτημα στο ακρωτήριο.', 'Λακωνία / Μάνη', ARRAY['Σπήλαιο Ταίναρου', 'Ακρωτήριο Ταίναρο', 'Μάνη']::text[], 'Το ακρωτήριο, το σπήλαιο ή τα κατάλοιπα του ιερού κοντά στη θάλασσα.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['odysseus_tainaron']::text[], ''),
  (222, 'archaia-iklaina', 'Αρχαία Ίκλαινα', ARRAY['Μυκηναϊκό κέντρο', 'Οικισμός', 'Διοίκηση']::text[], ARRAY['Μυκηναϊκή']::text[], 'Η ακμή της τοποθετείται στη μυκηναϊκή περίοδο.', 'Ύστερη Εποχή του Χαλκού', 'Η χρήση της θέσης μεταβλήθηκε μετά την παρακμή του μυκηναϊκού συστήματος.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· συνδέεται με το μυκηναϊκό δίκτυο της Πύλου.', 'Τοπικό διοικητικό και οικιστικό κέντρο της μυκηναϊκής Μεσσηνίας.', 'Η Ίκλαινα είναι σημαντική μυκηναϊκή θέση της Μεσσηνίας, γνωστή για τα κατάλοιπα οικισμού και διοικητικής δραστηριότητας. Συνδέεται με το ευρύτερο δίκτυο του μυκηναϊκού βασιλείου της Πύλου.', 'Από μυκηναϊκό κέντρο έγινε αρχαιολογική θέση υπό μελέτη.', 'medium', 'Πρόσβαση με όχημα στην περιοχή, αλλά η επισκεψιμότητα μπορεί να είναι περιορισμένη σε σχέση με οργανωμένους χώρους.', 'Μυκηναϊκή Μεσσηνία / Πύλος', ARRAY['Ανάκτορο Νέστορα', 'Θολωτοί τάφοι Πύλου', 'Πύλος']::text[], 'Άποψη των ανασκαφικών καταλοίπων με το μεσσηνιακό τοπίο.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['efa_messinia_iklaina']::text[], ''),
  (86, 'lato', 'Λατώ', ARRAY['Πόλη', 'Πόλη-κράτος', 'Οχύρωση']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική']::text[], 'Η πόλη αναπτύχθηκε πριν και κατά τους ιστορικούς χρόνους, με έντονη ακμή στους δωρικούς χρόνους.', 'Αρχαϊκή - Ελληνιστική περίοδος', 'Η πόλη εγκαταλείφθηκε σταδιακά όταν το κέντρο βάρους μετατοπίστηκε προς το επίνειό της.', 'Αναπτύχθηκε από την πόλη-κράτος των Λατίων.', 'Αστικό και πολιτικό κέντρο της ισχυρότερης πόλης στον κόλπο του Μιραμπέλλου.', 'Η Λατώ είναι μία από τις καλύτερα διατηρημένες αρχαίες πόλεις της Κρήτης. Είναι χτισμένη ανάμεσα σε δύο λόφους, με εξαιρετική θέα προς τον κόλπο του Μιραμπέλλου, και διατηρεί δημόσια κτήρια, αγορά, ναό, πρυτανείο και οικιστικά κατάλοιπα.', 'Από αστικό κέντρο της πόλης-κράτους μετατράπηκε σε αρχαιολογικό χώρο.', 'medium', 'Πρόσβαση με όχημα και περπάτημα στον αρχαιολογικό χώρο.', 'Λατώ / Ανατολική Κρήτη', ARRAY['Άγιος Νικόλαος', 'Κριτσά', 'Γουρνιά', 'Δρήρος']::text[], 'Πανοραμική εικόνα της πόλης με θέα στον κόλπο Μιραμπέλλου.', 'high', true, 'Manual-review import: mapped cleaned monument "Λατώ" to catalog_id 86 "Αρχαία δωρική πόλη Λατώ". Alternatives: 87: Αρχαϊκή πόλη Δρήρος (0.073); 90: Μινωική πόλη Γουρνιά (0.073); 118: Μινωική πόλη Παλαίκαστρο (0.073).', ARRAY['odysseus_lato']::text[], 'https://upload.wikimedia.org/wikipedia/commons/e/e6/Lato_-_Agora.jpg'),
  (90, 'goyrnia', 'Γουρνιά', ARRAY['Μινωικός οικισμός', 'Πόλη', 'Ανάκτορο/διοικητικό κέντρο']::text[], ARRAY['Μινωική']::text[], 'Η ακμή του οικισμού τοποθετείται κυρίως στην Υστερομινωική περίοδο.', '1700-1450 π.Χ. περίπου', 'Ο οικισμός καταστράφηκε στη μινωική περίοδο.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· ήταν μινωική κοινότητα.', 'Οικιστικό, διοικητικό και παραγωγικό κέντρο μεσαίου μεγέθους.', 'Τα Γουρνιά θεωρούνται από τα πιο χαρακτηριστικά ανασκαμμένα παραδείγματα μινωικού οικισμού μεσαίου μεγέθους. Ο χώρος διατηρεί δρόμους, σπίτια, μικρό ανάκτορο/κεντρικό κτήριο και εργαστηριακές εγκαταστάσεις.', 'Από ζωντανός μινωικός οικισμός έγινε αρχαιολογικός χώρος που δείχνει την καθημερινή ζωή της μινωικής Κρήτης.', 'easy', 'Εύκολη πρόσβαση με όχημα, κοντά στον δρόμο Αγίου Νικολάου-Ιεράπετρας.', 'Μινωική Κρήτη / Ανατολική Κρήτη', ARRAY['Λατώ', 'Μόχλος', 'Παχειά Άμμος', 'Ιεράπετρα']::text[], 'Η μινωική πολεοδομία με τα σοκάκια και τα σπίτια του οικισμού.', 'high', true, 'Manual-review import: mapped cleaned monument "Γουρνιά" to catalog_id 90 "Μινωική πόλη Γουρνιά". Alternatives: 87: Αρχαϊκή πόλη Δρήρος (0.073); 118: Μινωική πόλη Παλαίκαστρο (0.073); 120: Μινωικός Οικισμός Μόχλου (0.073).', ARRAY['odysseus_gournia']::text[], ''),
  (87, 'driros', 'Δρήρος', ARRAY['Αρχαϊκή πόλη', 'Ιερό', 'Πόλη-κράτος']::text[], ARRAY['Γεωμετρική', 'Αρχαϊκή', 'Κλασική']::text[], 'Η πόλη αναπτύχθηκε κυρίως στους γεωμετρικούς και αρχαϊκούς χρόνους.', '8ος - 6ος αιώνας π.Χ. και μετά', 'Η σημασία της μειώθηκε σταδιακά στους μεταγενέστερους χρόνους.', 'Αναπτύχθηκε από την τοπική δωρική κοινότητα.', 'Αστικό και θρησκευτικό κέντρο της ανατολικής Κρήτης.', 'Η Δρήρος είναι σημαντική αρχαϊκή πόλη της Κρήτης, γνωστή για τα κατάλοιπα της αγοράς, των οχυρώσεων και ιδιαίτερα για το ιερό του Απόλλωνα Δελφινίου. Ο χώρος βοηθά να φανεί η μετάβαση από τη μινωική στην ιστορική Κρήτη.', 'Από αρχαϊκή πόλη-κράτος έγινε αρχαιολογικός χώρος.', 'medium', 'Πρόσβαση με όχημα και περπάτημα σε υπαίθριο χώρο.', 'Δρήρος / Ανατολική Κρήτη', ARRAY['Λατώ', 'Μάλια', 'Γουρνιά']::text[], 'Τα κατάλοιπα της αρχαϊκής πόλης με το ορεινό τοπίο.', 'medium', true, 'Manual-review import: mapped cleaned monument "Δρήρος" to catalog_id 87 "Αρχαϊκή πόλη Δρήρος". Alternatives: 118: Μινωική πόλη Παλαίκαστρο (0.073); 120: Μινωικός Οικισμός Μόχλου (0.073); 127: Πραισός / αρχαία πόλη των Ετεοκρητών (0.073).', ARRAY['odysseus_driros']::text[], 'https://upload.wikimedia.org/wikipedia/commons/b/bc/Dreros_12.jpg'),
  (48, 'diktaio-antro', 'Δικταίο Άντρο', ARRAY['Σπήλαιο', 'Ιερό', 'Μυθολογικός τόπος']::text[], ARRAY['Νεολιθική', 'Μινωική', 'Αρχαϊκή', 'Κλασική']::text[], 'Η χρήση του σπηλαίου είναι πολύ παλιά, με σημαντική λατρευτική χρήση στη μινωική περίοδο.', 'Μινωική - ιστορικοί χρόνοι', 'Η αρχαία λατρευτική χρήση σταμάτησε μετά την αρχαιότητα.', 'Δεν χτίστηκε· πρόκειται για φυσικό σπήλαιο που απέκτησε λατρευτική χρήση.', 'Λατρευτικός και μυθολογικός χώρος, συνδεδεμένος με τον Δία.', 'Το Δικταίο Άντρο είναι ένα από τα πιο γνωστά σπήλαια της Κρήτης. Βρίσκεται στο οροπέδιο Λασιθίου και συνδέεται με τη λατρεία του Δία και με μύθους για τη γέννησή του. Η θέση του συνδυάζει φυσικό μνημείο και αρχαία λατρεία.', 'Από αρχαίο λατρευτικό σπήλαιο έγινε επισκέψιμο φυσικό και αρχαιολογικό μνημείο.', 'medium', 'Απαιτεί ανάβαση/κατηφόρα σε μονοπάτι και προσοχή μέσα στο σπήλαιο.', 'Μινωική Κρήτη / Οροπέδιο Λασιθίου', ARRAY['Καρφί', 'Μάλια', 'Λασίθι']::text[], 'Το εσωτερικό του σπηλαίου με σταλακτίτες ή η είσοδος με θέα στο οροπέδιο.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_diktaion_antron']::text[], 'https://upload.wikimedia.org/wikipedia/commons/0/04/Dikteonandronkreta_-_4.jpeg'),
  (120, 'minoikos-oikismos-mochloy', 'Μινωικός Οικισμός Μόχλου', ARRAY['Μινωικός οικισμός', 'Λιμάνι', 'Νεκροταφείο']::text[], ARRAY['Μινωική']::text[], 'Ο οικισμός αναπτύχθηκε στη μινωική περίοδο.', 'Πρωτομινωική - Υστερομινωική περίοδος', 'Η χρήση της θέσης άλλαξε μετά την παρακμή των μινωικών κέντρων.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· ήταν μινωική παραθαλάσσια κοινότητα.', 'Λιμενικός οικισμός και εμπορικό σημείο στην ανατολική Κρήτη.', 'Ο Μόχλος είναι σημαντικός μινωικός παραθαλάσσιος οικισμός σε μικρό νησί απέναντι από την ακτή. Η θέση του δείχνει τη ναυτική και εμπορική δραστηριότητα της μινωικής Κρήτης και συνδέεται με οικιστικά κατάλοιπα και νεκροταφεία.', 'Από μινωικός λιμενικός οικισμός έγινε αρχαιολογική θέση με ιδιαίτερο θαλάσσιο χαρακτήρα.', 'medium', 'Η πρόσβαση στον πυρήνα του χώρου εξαρτάται από τη θάλασσα/σκάφος και δεν είναι πάντα απλή.', 'Μινωική Ανατολική Κρήτη', ARRAY['Γουρνιά', 'Παχειά Άμμος', 'Σητεία', 'Ζάκρος']::text[], 'Το μικρό νησί του Μόχλου και τα μινωικά κατάλοιπα δίπλα στη θάλασσα.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['efa_lasithi_mochlos']::text[], 'https://upload.wikimedia.org/wikipedia/commons/9/9b/Kreta_r_08_096.jpg'),
  (118, 'palaikastro', 'Παλαίκαστρο', ARRAY['Μινωική πόλη', 'Οικισμός', 'Λιμενικό κέντρο']::text[], ARRAY['Μινωική']::text[], 'Ο οικισμός αναπτύχθηκε στη μινωική περίοδο.', 'Μινωική περίοδος', 'Η χρήση του μεταβλήθηκε μετά τις καταστροφές του μινωικού κόσμου.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· ήταν μινωική κοινότητα.', 'Οικιστικό και πιθανό εμπορικό κέντρο της ανατολικής Κρήτης.', 'Το Παλαίκαστρο είναι σημαντική μινωική πόλη στην ανατολική Κρήτη. Η θέση του κοντά στη θάλασσα και τα ευρήματα δείχνουν οργανωμένη αστική ζωή, επαφές και ιδιαίτερη σημασία για την περιοχή της Σητείας.', 'Από μινωική πόλη έγινε αρχαιολογικός χώρος.', 'medium', 'Πρόσβαση με όχημα στην περιοχή, με περπάτημα στον χώρο.', 'Μινωική Ανατολική Κρήτη', ARRAY['Ζάκρος', 'Ίτανος', 'Σητεία']::text[], 'Άποψη των θεμελίων της μινωικής πόλης με το ανατολικό κρητικό τοπίο.', 'medium', true, 'Manual-review import: mapped cleaned monument "Παλαίκαστρο" to catalog_id 118 "Μινωική πόλη Παλαίκαστρο". Alternatives: 127: Πραισός / αρχαία πόλη των Ετεοκρητών (0.073); 208: Μινωική έπαυλη Αχλαδιών (0.073); 209: Χαμαίζι (0.073).', ARRAY['efa_lasithi_palaikastro']::text[], 'https://upload.wikimedia.org/wikipedia/commons/0/02/%CE%A0%CE%B1%CE%BB%CE%B1%CE%AF%CE%BA%CE%B1%CF%83%CF%84%CF%81%CE%BF_6488.jpg'),
  (122, 'minoikos-choros-tylisoy', 'Μινωικός χώρος Τυλίσου', ARRAY['Μινωικός οικισμός', 'Μέγαρα', 'Διοικητικό κέντρο']::text[], ARRAY['Μινωική']::text[], 'Η κύρια φάση του χώρου ανήκει στη νεοανακτορική μινωική περίοδο.', 'Μινωική περίοδος', 'Η χρήση του χώρου άλλαξε μετά την παρακμή των μινωικών κέντρων.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· συνδέεται με τη μινωική ανακτορική οργάνωση.', 'Τοπικό διοικητικό και οικιστικό κέντρο κοντά στην Κνωσό.', 'Η Τύλισος είναι μινωικός αρχαιολογικός χώρος κοντά στο Ηράκλειο, γνωστός για τα μεγάλα μινωικά μέγαρα και τα ευρήματα που δείχνουν ισχυρές σχέσεις με την Κνωσό και τον μινωικό κόσμο.', 'Από μινωικό κέντρο έγινε οργανωμένος αρχαιολογικός χώρος.', 'easy', 'Εύκολη πρόσβαση με όχημα από το Ηράκλειο.', 'Μινωική Κρήτη / Κνωσιακή περιοχή', ARRAY['Κνωσός', 'Αμνισός', 'Βαθύπετρο', 'Ηράκλειο']::text[], 'Τα θεμέλια των μινωικών μεγάρων της Τυλίσου.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_tylissos']::text[], 'https://upload.wikimedia.org/wikipedia/commons/c/c3/Ancient_Tylissos.jpg'),
  (111, 'minoiki-epayli-agias-triadas', 'Μινωική Έπαυλη Αγίας Τριάδας', ARRAY['Μινωική έπαυλη', 'Διοικητικό κέντρο']::text[], ARRAY['Μινωική']::text[], 'Η έπαυλη χτίστηκε στη νεοανακτορική περίοδο.', 'Μινωική περίοδος', 'Η χρήση της μεταβλήθηκε μετά τις καταστροφές και τις μεταγενέστερες φάσεις.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· συνδέεται με το μινωικό σύστημα της Φαιστού.', 'Διοικητικό, αποθηκευτικό και πιθανό τελετουργικό κέντρο δίπλα στη Φαιστό.', 'Η Μινωική Έπαυλη της Αγίας Τριάδας βρίσκεται κοντά στη Φαιστό και αποτελεί σημαντικό μινωικό συγκρότημα. Τα ευρήματα δείχνουν διοικητικές, αποθηκευτικές και τελετουργικές λειτουργίες και τη στενή σύνδεση με την πεδιάδα της Μεσαράς.', 'Από μινωικό συγκρότημα έγινε αρχαιολογικός χώρος συνδεδεμένος με τη Φαιστό.', 'easy', 'Εύκολη πρόσβαση με όχημα, πολύ κοντά στη Φαιστό.', 'Μινωική Κρήτη / Μεσαρά', ARRAY['Φαιστός', 'Κομμός', 'Γόρτυνα']::text[], 'Η έπαυλη με φόντο την πεδιάδα της Μεσαράς.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_agia_triada']::text[], ''),
  (126, 'kommos', 'Κομμός', ARRAY['Μινωικό λιμάνι', 'Οικισμός', 'Ιερό']::text[], ARRAY['Μινωική', 'Γεωμετρική', 'Αρχαϊκή', 'Κλασική']::text[], 'Η θέση χρησιμοποιήθηκε ως μινωικό λιμάνι στη 2η χιλιετία π.Χ.', 'Μινωική περίοδος και ιστορικοί χρόνοι', 'Η χρήση της ακτής και των εγκαταστάσεων μεταβλήθηκε στους μεταγενέστερους χρόνους.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· συνδέεται με το μινωικό δίκτυο της Φαιστού.', 'Λιμενική και εμπορική εξυπηρέτηση της νότιας Κρήτης.', 'Ο Κομμός ήταν σημαντικό μινωικό λιμάνι στη νότια Κρήτη, κοντά στη Φαιστό και την Αγία Τριάδα. Η παραθαλάσσια θέση του τον έκανε βασικό σημείο επικοινωνίας της Μεσαράς με το Αιγαίο και την ανατολική Μεσόγειο.', 'Από μινωικό λιμάνι και οικισμό έγινε αρχαιολογική θέση δίπλα στην παραλία.', 'medium', 'Πρόσβαση στην περιοχή είναι εύκολη, αλλά η αρχαιολογική ζώνη μπορεί να έχει περιορισμούς.', 'Μινωική Κρήτη / Μεσαρά', ARRAY['Φαιστός', 'Αγία Τριάδα', 'Μάταλα', 'Γόρτυνα']::text[], 'Η παραλία και τα κατάλοιπα του μινωικού λιμανιού.', 'medium', true, 'Manual-review import: mapped cleaned monument "Κομμός" to catalog_id 126 "Κομμός / Μινωικό λιμάνι Κομμού". Alternatives: 212: Μινωικό νεκροταφείο και οικισμός Κούμασα (0.055); 214: Μινωικός θολωτός τάφος Καμηλαρίου (0.055); 123: Οικία των Κρίνων (0.044).', ARRAY['odysseus_kommos']::text[], ''),
  (77, 'iero-kaveiron-thivas', 'Ιερό Καβείρων Θήβας', ARRAY['Ιερό', 'Μυστήρια', 'Θέατρο']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η λατρεία αναπτύχθηκε από τους αρχαϊκούς χρόνους.', 'Αρχαϊκή - Ρωμαϊκή περίοδος', 'Η λατρευτική χρήση σταμάτησε μετά την αρχαιότητα.', 'Δεν συνδέεται με έναν κτήτορα· ήταν βοιωτικό ιερό με μυστηριακό χαρακτήρα.', 'Λατρεία των Καβείρων και τέλεση μυστηρίων.', 'Το Ιερό των Καβείρων κοντά στη Θήβα ήταν σημαντικό λατρευτικό κέντρο της Βοιωτίας. Συνδεόταν με μυστήρια και περιλάμβανε ιερά κτήρια και θέατρο, δείχνοντας τον ιδιαίτερο θρησκευτικό χαρακτήρα του χώρου.', 'Από μυστηριακό ιερό έγινε αρχαιολογικός χώρος.', 'medium', 'Πρόσβαση με όχημα στην περιοχή και περπάτημα στον χώρο.', 'Θήβα / Βοιωτία', ARRAY['Αρχαία Θήβα', 'Αρχαιολογικό Μουσείο Θηβών', 'Κοιλάδα Μουσών']::text[], 'Το θέατρο ή τα κατάλοιπα του ιερού στο βοιωτικό τοπίο.', 'medium', true, 'Manual-review import: mapped cleaned monument "Ιερό Καβείρων Θήβας" to catalog_id 77 "Ιερό Καβείρων / θέατρο Καβείριων μυστηρίων". Alternatives: 33: Ιερό των Μουσών (0.232); 14: Ιερό Αρτέμιδος Αυλιδείας (0.211); 135: Ιερό Απόλλωνα Δηλίου (0.200).', ARRAY['odysseus_kabeirion_thebes']::text[], ''),
  (33, 'iero-moyson-stin-koilada-ton-moyson', 'Ιερό Μουσών στην Κοιλάδα των Μουσών', ARRAY['Ιερό', 'Πολιτιστικό κέντρο', 'Μυθολογικό τοπίο']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η λατρεία των Μουσών στην περιοχή είναι αρχαία και αναπτύχθηκε στους ιστορικούς χρόνους.', 'Κλασική - Ρωμαϊκή περίοδος', 'Η αρχαία λατρεία έπαψε μετά την αρχαιότητα.', 'Αναπτύχθηκε από τις βοιωτικές κοινότητες της περιοχής.', 'Λατρεία των Μουσών και διοργάνωση μουσικών/ποιητικών εκδηλώσεων.', 'Η Κοιλάδα των Μουσών στους πρόποδες του Ελικώνα ήταν αφιερωμένη στις Μούσες. Ο χώρος συνδέεται με την ποίηση, τη μουσική, τον Ησίοδο και τη βοιωτική θρησκευτική παράδοση.', 'Από λατρευτικό και πολιτιστικό τοπίο έγινε αρχαιολογική και φυσική περιοχή ιστορικού ενδιαφέροντος.', 'medium', 'Πρόσβαση με όχημα και πιθανό περπάτημα σε υπαίθριο τοπίο.', 'Βοιωτία / Ελικώνας', ARRAY['Άσκρη', 'Θήβα', 'Ιερό Καβείρων']::text[], 'Η κοιλάδα με φόντο τον Ελικώνα και τα κατάλοιπα του ιερού.', 'medium', true, 'Manual-review import: mapped cleaned monument "Ιερό Μουσών στην Κοιλάδα των Μουσών" to catalog_id 33 "Ιερό των Μουσών". Alternatives: 42: Κοιλάδα των Μουσών (0.740); 14: Ιερό Αρτέμιδος Αυλιδείας (0.200); 223: Αρχαϊκό ιερό (0.195).', ARRAY['odysseus_valley_muses']::text[], 'https://upload.wikimedia.org/wikipedia/commons/e/e8/ValleyOfMuses2.jpg'),
  (52, 'manteio-trofonioy', 'Μαντείο Τροφωνίου', ARRAY['Μαντείο', 'Ιερό', 'Σπήλαιο']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η λατρεία και το μαντείο είχαν μακρά χρήση στους ιστορικούς χρόνους.', 'Κλασική - Ρωμαϊκή περίοδος', 'Η μαντική λειτουργία σταμάτησε μετά την αρχαιότητα.', 'Δεν συνδέεται με έναν κτήτορα· ήταν τοπικό μαντείο της Λιβαδειάς.', 'Μαντική λατρεία του ήρωα Τροφωνίου.', 'Το Μαντείο του Τροφωνίου στη Λιβαδειά ήταν ένα από τα πιο ιδιαίτερα μαντεία της αρχαιότητας. Συνδεόταν με υπόγεια/σπηλαιώδη εμπειρία και τελετουργική κατάβαση, γεγονός που το έκανε να ξεχωρίζει από άλλα μαντεία.', 'Από μαντείο και ιερό έγινε ιστορικό σημείο μέσα στη Λιβαδειά.', 'easy', 'Εύκολη πρόσβαση στην περιοχή της Λιβαδειάς, αν και τα σωζόμενα κατάλοιπα δεν είναι τόσο εντυπωσιακά.', 'Λιβαδειά / Βοιωτία', ARRAY['Πηγές Κρύας', 'Θήβα', 'Ορχομενός']::text[], 'Το τοπίο στις πηγές της Κρύας ή σημεία που συνδέονται με το Τροφώνιο.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_trophonios']::text[], ''),
  (130, 'akropoli-proernas', 'Ακρόπολη Πρόερνας', ARRAY['Ακρόπολη', 'Οχύρωση', 'Πόλη']::text[], ARRAY['Κλασική', 'Ελληνιστική']::text[], 'Η κύρια οχύρωση ανήκει στους κλασικούς και ελληνιστικούς χρόνους.', 'Κλασική - Ελληνιστική περίοδος', 'Η αρχαία πόλη εγκαταλείφθηκε σταδιακά.', 'Αναπτύχθηκε από την τοπική κοινότητα της Πρόερνας.', 'Οχυρωμένο κέντρο που έλεγχε περάσματα της Φθιώτιδας.', 'Η Ακρόπολη της Πρόερνας βρίσκεται κοντά στον Δομοκό και αποτελεί σημαντική οχυρωμένη θέση της αρχαίας Φθιώτιδας. Τα σωζόμενα τείχη και η στρατηγική τοποθεσία δείχνουν τον αμυντικό χαρακτήρα του χώρου.', 'Από οχυρωμένη αρχαία πόλη έγινε αρχαιολογική θέση.', 'medium', 'Πρόσβαση με όχημα μέχρι την περιοχή και περπάτημα σε λόφο/φυσικό έδαφος.', 'Φθιώτιδα / Αχαΐα Φθιώτιδα', ARRAY['Μελιταία', 'Θερμοπύλες', 'Δομοκός']::text[], 'Τα τείχη της ακρόπολης με θέα προς τη φθιωτική πεδιάδα.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_proerna']::text[], ''),
  (131, 'archaia-melitaia', 'Αρχαία Μελιταία', ARRAY['Πόλη', 'Οχύρωση']::text[], ARRAY['Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η πόλη αναπτύχθηκε στους ιστορικούς χρόνους.', 'Κλασική - Ρωμαϊκή περίοδος', 'Η χρήση της μειώθηκε σταδιακά μετά την αρχαιότητα.', 'Αναπτύχθηκε από την τοπική κοινότητα της Μελιταίας.', 'Αστικό και αμυντικό κέντρο της αρχαίας Φθιώτιδας.', 'Η Αρχαία Μελιταία ήταν σημαντική πόλη της Φθιώτιδας. Η θέση της και τα κατάλοιπα οχύρωσης δείχνουν ότι είχε ρόλο στον έλεγχο της περιοχής και των περασμάτων της κεντρικής Ελλάδας.', 'Από αρχαία πόλη έγινε αρχαιολογική θέση.', 'medium', 'Πρόσβαση με όχημα στην περιοχή και περπάτημα σε υπαίθριο χώρο.', 'Φθιώτιδα', ARRAY['Πρόερνα', 'Θερμοπύλες', 'Δομοκός']::text[], 'Άποψη των οχυρώσεων ή του λόφου της αρχαίας πόλης.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_melitaia']::text[], ''),
  (36, 'makedonikos-tafos-ton-anthemion', 'Μακεδονικός Τάφος των Ανθεμίων', ARRAY['Τάφος', 'Μακεδονικός τάφος']::text[], ARRAY['Ελληνιστική']::text[], 'Πρώτο μισό 3ου αιώνα π.Χ.', 'Ελληνιστική περίοδος', 'Ο τάφος σφραγίστηκε μετά την ταφή και σήμερα είναι μνημείο.', 'Δεν γνωρίζουμε τον νεκρό ή τον κτήτορα.', 'Ταφικό μνημείο επιφανούς προσώπου της Μακεδονίας.', 'Ο Μακεδονικός Τάφος των Ανθεμίων είναι εντυπωσιακός διθάλαμος καμαροσκεπής τάφος στη Νάουσα. Ξεχωρίζει για τη ναόσχημη πρόσοψη και τη ζωγραφική διακόσμηση με φυτικά μοτίβα.', 'Από ταφικό μνημείο έγινε προστατευόμενο αρχαιολογικό μνημείο.', 'easy', 'Εύκολη πρόσβαση στην περιοχή της Μίεζας/Νάουσας, με επίσκεψη σύμφωνα με το ωράριο.', 'Μακεδονία / Μίεζα', ARRAY['Νυμφαίο Μίεζας', 'Αιγές', 'Άλλοι μακεδονικοί τάφοι Λευκαδίων']::text[], 'Η πρόσοψη ή το εσωτερικό με τη ζωγραφική διακόσμηση.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_tomb_anthemia']::text[], 'https://upload.wikimedia.org/wikipedia/commons/9/95/Anthemion_Makedonian_Tomb_1.jpg'),
  (184, 'archaia-leivithra', 'Αρχαία Λείβηθρα', ARRAY['Πόλη', 'Μυθολογικό τοπίο', 'Ορφική παράδοση']::text[], ARRAY['Κλασική', 'Ελληνιστική']::text[], 'Η θέση αναπτύχθηκε στους ιστορικούς χρόνους.', 'Κλασική - Ελληνιστική περίοδος', 'Η χρήση της αρχαίας πόλης σταμάτησε στους μεταγενέστερους χρόνους.', 'Αναπτύχθηκε από την τοπική κοινότητα της Πιερίας.', 'Αρχαία πόλη με έντονη σχέση με τον Ορφέα και το πιερικό τοπίο.', 'Τα Λείβηθρα είναι αρχαία πόλη της Πιερίας, στους πρόποδες του Ολύμπου, και συνδέονται με τις παραδόσεις για τον Ορφέα. Η θέση έχει ιδιαίτερο ενδιαφέρον επειδή συνδυάζει αρχαιολογικά κατάλοιπα και μυθολογικό βάρος.', 'Από αρχαία πόλη έγινε αρχαιολογικός και πολιτιστικός χώρος.', 'medium', 'Πρόσβαση με όχημα στην περιοχή και επίσκεψη ανάλογα με τις συνθήκες λειτουργίας.', 'Πιερία / Μακεδονία', ARRAY['Δίον', 'Όλυμπος', 'Πύδνα']::text[], 'Άποψη του αρχαιολογικού χώρου με το φυσικό τοπίο του Ολύμπου.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_leibethra']::text[], 'https://upload.wikimedia.org/wikipedia/commons/0/0b/Leivithra_Akropolis.JPG'),
  (181, 'archaia-akanthos', 'Αρχαία Άκανθος', ARRAY['Πόλη', 'Νεκρόπολη', 'Παραθαλάσσιο κέντρο']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η πόλη ιδρύθηκε ως αποικία των Ανδρίων τον 7ο αιώνα π.Χ.', 'Αρχαϊκή - Ρωμαϊκή περίοδος', 'Η αρχαία χρήση μεταβλήθηκε στους μεταγενέστερους χρόνους.', 'Άποικοι από την Άνδρο.', 'Παραθαλάσσια πόλη-κράτος με εμπορική και στρατηγική σημασία.', 'Η Αρχαία Άκανθος βρισκόταν στη θέση της σημερινής Ιερισσού. Ήταν σημαντική πόλη της ανατολικής Χαλκιδικής, με λιμάνι, νεκροταφείο και ισχυρές επαφές στο βόρειο Αιγαίο.', 'Από αποικία και πόλη-κράτος έγινε αρχαιολογικό σύνολο ενσωματωμένο στη σύγχρονη Ιερισσό.', 'easy', 'Πρόσβαση με όχημα στην Ιερισσό· ορατά τμήματα μπορεί να είναι διάσπαρτα.', 'Χαλκιδική / Άκανθος', ARRAY['Στάγειρα', 'Όλυνθος', 'Τορώνη']::text[], 'Η περιοχή της αρχαίας πόλης και του νεκροταφείου με φόντο τη θάλασσα.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_akanthos']::text[], ''),
  (183, 'archaia-toroni', 'Αρχαία Τορώνη', ARRAY['Πόλη', 'Λιμάνι', 'Οχύρωση']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η θέση κατοικήθηκε και αναπτύχθηκε από τους αρχαϊκούς χρόνους.', 'Αρχαϊκή - Ρωμαϊκή περίοδος', 'Η αρχαία πόλη άλλαξε χρήση στους μεταγενέστερους χρόνους.', 'Συνδέεται με αποικιακή εγκατάσταση και την ανάπτυξη της Χαλκιδικής.', 'Παραθαλάσσια πόλη και λιμάνι στη Σιθωνία.', 'Η Αρχαία Τορώνη ήταν σημαντική παραθαλάσσια πόλη της Σιθωνίας. Η θέση της πάνω στη θάλασσα και τα κατάλοιπα οχύρωσης δείχνουν τον ρόλο της ως λιμάνι και αστικό κέντρο της Χαλκιδικής.', 'Από αρχαία πόλη και λιμάνι έγινε αρχαιολογικό τοπίο δίπλα στη σύγχρονη παραλία.', 'easy', 'Εύκολη πρόσβαση με όχημα στην περιοχή της Τορώνης.', 'Χαλκιδική / Σιθωνία', ARRAY['Στάγειρα', 'Άκανθος', 'Όλυνθος']::text[], 'Τα κατάλοιπα κοντά στη θάλασσα ή το οχυρωμένο ακρωτήριο.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_toroni']::text[], 'https://upload.wikimedia.org/wikipedia/commons/d/da/Toroni2.jpg'),
  (146, 'archaio-thermo', 'Αρχαίο Θέρμο', ARRAY['Ιερό', 'Πολιτικό κέντρο', 'Αγορά']::text[], ARRAY['Γεωμετρική', 'Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Ο χώρος έχει πολύ παλιά χρήση, με σημαντική μνημειακή ανάπτυξη στους αρχαϊκούς και ελληνιστικούς χρόνους.', 'Αρχαϊκή - Ελληνιστική περίοδος', 'Η αρχαία χρήση σταμάτησε στους μεταγενέστερους χρόνους.', 'Αναπτύχθηκε από τους Αιτωλούς.', 'Ιερό και πολιτικό κέντρο του Κοινού των Αιτωλών.', 'Το Αρχαίο Θέρμο ήταν ένας από τους σημαντικότερους αρχαιολογικούς χώρους της Δυτικής Ελλάδας. Συνδύαζε ιερό, αγορά και πολιτική λειτουργία, καθώς αποτέλεσε κεντρικό σημείο για τους Αιτωλούς.', 'Από ιερό και πολιτικό κέντρο έγινε αρχαιολογικός χώρος και μουσείο.', 'easy', 'Εύκολη πρόσβαση με όχημα· το εισιτήριο συνδέεται και με το μουσείο.', 'Αιτωλία / Κοινό Αιτωλών', ARRAY['Ναός Απόλλωνος Θερμίου', 'Αγορά Θέρμου', 'Αρχαιολογικό Μουσείο Θέρμου']::text[], 'Τα κατάλοιπα του ναού ή γενική άποψη του ιερού και της αγοράς.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_thermos']::text[], ''),
  (93, 'archaia-kassopi', 'Αρχαία Κασσώπη', ARRAY['Πόλη', 'Οχύρωση', 'Θέατρο', 'Αγορά']::text[], ARRAY['Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Κτίστηκε πριν από τα μέσα του 4ου αιώνα π.Χ., περίπου γύρω στο 340 π.Χ.', '4ος αιώνας π.Χ. - 31 π.Χ. περίπου', 'Η πόλη εγκαταλείφθηκε μετά την ίδρυση της Νικόπολης.', 'Αναπτύχθηκε από τους Κασσωπαίους.', 'Πρωτεύουσα της Κασσωπαίας και οχυρωμένο αστικό κέντρο.', 'Η Κασσώπη είναι μία από τις καλύτερα σωζόμενες αρχαίες πόλεις της Ηπείρου. Βρίσκεται σε φυσικά οχυρή θέση σε οροπέδιο κοντά στο Ζάλογγο και διατηρεί τείχη, αγορά, θέατρο, οικίες και δημόσια κτήρια.', 'Από πρωτεύουσα της Κασσωπαίας εγκαταλείφθηκε μετά την ίδρυση της Νικόπολης και σήμερα είναι αρχαιολογικός χώρος.', 'medium', 'Πρόσβαση με όχημα μέχρι τον χώρο, με περπάτημα σε μεγάλη αρχαία πόλη.', 'Κασσωπαία / Ήπειρος', ARRAY['Νικόπολη', 'Νεκρομαντείο Αχέροντα', 'Ζάλογγο']::text[], 'Πανοραμική εικόνα της αρχαίας πόλης με θέα προς τον Αμβρακικό.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_kassope']::text[], ''),
  (80, 'orraon', 'Όρραον', ARRAY['Οχυρωμένος οικισμός', 'Ακρόπολη', 'Κατοικίες']::text[], ARRAY['Κλασική', 'Ελληνιστική']::text[], 'Ιδρύθηκε και περιτειχίστηκε πιθανότατα στο πρώτο μισό του 4ου αιώνα π.Χ.', '4ος-2ος αιώνας π.Χ.', 'Η κατοίκηση μειώθηκε σταδιακά μετά τις πολιτικές και στρατιωτικές αλλαγές της ύστερης ελληνιστικής περιόδου.', 'Συνδέεται με το βασίλειο των Μολοσσών και την οργάνωση της Ηπείρου.', 'Έλεγχος αγροτικής περιοχής και στρατηγικού περάσματος, με οργανωμένη κατοίκηση μέσα σε ισχυρό τείχος.', 'Το Όρραον είναι από τους πιο χαρακτηριστικούς οχυρωμένους οικισμούς της αρχαίας Ηπείρου. Διατηρεί σπίτια, δρόμους και οχυρώσεις σε πολύ καλή κατάσταση, προσφέροντας καθαρή εικόνα μιας μικρής οργανωμένης πόλης των Μολοσσών.', 'Από ζωντανός οχυρωμένος οικισμός μετατράπηκε σε αρχαιολογικό χώρο.', 'medium', 'Η πρόσβαση γίνεται οδικώς, αλλά ο χώρος θέλει περπάτημα και προσοχή στο ανάγλυφο.', 'Μολοσσοί / Ήπειρος', ARRAY['Δωδώνη', 'Νικόπολη', 'Κασσώπη']::text[], 'Άποψη των σωζόμενων σπιτιών και του τείχους του Ορράου.', 'high', true, 'Manual-review import: mapped cleaned monument "Όρραον" to catalog_id 80 "Αρχαιολογικός Χώρος Όρραον/ Αρχαία Ακρόπολη Μολοσσών". Alternatives: 1: Κορυφη Αυγο Παγγαιο (0.000); 5: Πιθανή θέση της Ποικίλης Στοάς (0.000); 7: Μεγάλα Προπύλαια Ελευσίνας (0.000).', ARRAY['odysseus_orraon']::text[], ''),
  (96, 'archaia-elea', 'Αρχαία Ελέα', ARRAY['Οχυρωμένη πόλη', 'Πρωτεύουσα Κοινού', 'Ακρόπολη']::text[], ARRAY['Κλασική', 'Ελληνιστική']::text[], 'Η ίδρυση της πόλης τοποθετείται στον 4ο αιώνα π.Χ.', '4ος-2ος αιώνας π.Χ.', 'Η πόλη έχασε σταδιακά τον ρόλο της μετά την άνοδο άλλων κέντρων της Θεσπρωτίας.', 'Ιδρύθηκε από τους Θεσπρωτούς ως οργανωμένο πολιτικό και διοικητικό κέντρο.', 'Πολιτικό κέντρο και έδρα του Κοινού των Θεσπρωτών για σημαντικό διάστημα.', 'Η Αρχαία Ελέα ήταν μία από τις σημαντικότερες πόλεις της Θεσπρωτίας. Τα ισχυρά τείχη και η θέση της πάνω από την πεδιάδα δείχνουν τη στρατηγική και διοικητική σημασία της στον αρχαίο θεσπρωτικό χώρο.', 'Από πολιτικό κέντρο της Θεσπρωτίας μετατράπηκε σταδιακά σε εγκαταλειμμένο οχυρωμένο χώρο και σήμερα σε αρχαιολογικό τόπο.', 'easy', 'Η πρόσβαση γίνεται οδικώς από την περιοχή της Παραμυθιάς.', 'Θεσπρωτοί / Ήπειρος', ARRAY['Γίτανα', 'Ντόλιανη', 'Κασσώπη']::text[], 'Το πολυγωνικό τείχος και η θέα προς την πεδιάδα.', 'high', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['odysseus_elea_paramythia']::text[], ''),
  (129, 'kichyros-efyra', 'Κίχυρος / Εφύρα', ARRAY['Οχυρωμένη πόλη', 'Ακρόπολη', 'Μυθολογικός τόπος']::text[], ARRAY['Κλασική', 'Ελληνιστική']::text[], 'Η πόλη αναπτύχθηκε σε θέση με παλαιότερη κατοίκηση και σημαντική στρατηγική αξία.', 'Κλασική-Ελληνιστική περίοδος', 'Η χρήση της μειώθηκε μετά τις μεταβολές της ρωμαϊκής περιόδου και την οργάνωση της Νικόπολης.', 'Δεν αποδίδεται σε συγκεκριμένο κτήτορα· συνδέεται με τους αρχαίους Θεσπρωτούς και την περιοχή του Αχέροντα.', 'Έλεγχος της περιοχής του Αχέροντα και σύνδεση με την παράδοση της Εφύρας.', 'Ο Κίχυρος, που ταυτίζεται με την αρχαία Εφύρα, βρίσκεται κοντά στον Αχέροντα και συνδέεται με σημαντικές μυθολογικές και ιστορικές παραδόσεις. Η θέση του ελέγχει την περιοχή και σχετίζεται με το ευρύτερο δίκτυο αρχαίων θεσπρωτικών πόλεων.', 'Από οχυρωμένη πόλη και τοπικό κέντρο μετατράπηκε σε αρχαιολογικό χώρο.', 'medium', 'Η πρόσβαση είναι σχετικά εύκολη με όχημα, αλλά ο χώρος χρειάζεται επιτόπιο έλεγχο.', 'Θεσπρωτία / Ήπειρος', ARRAY['Νεκρομαντείο Αχέροντα', 'Πανδοσία', 'Νικόπολη']::text[], 'Άποψη της οχύρωσης ή του λόφου με το τοπίο του Αχέροντα.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: fuzzy (0.740).', ARRAY['odysseus_efyra_kichyros']::text[], ''),
  (128, 'pandosia-ipeiroy', 'Πανδοσία Ηπείρου', ARRAY['Οχυρωμένη πόλη', 'Ακρόπολη']::text[], ARRAY['Κλασική', 'Ελληνιστική']::text[], 'Η πόλη αναπτύχθηκε στην κλασική και ελληνιστική περίοδο.', 'Κλασική-Ελληνιστική περίοδος', 'Η κατοίκηση μειώθηκε μετά τις μεγάλες αλλαγές της ρωμαϊκής εποχής.', 'Δεν είναι γνωστός συγκεκριμένος κτήτορας· συνδέεται με την αρχαία Ήπειρο και την περιοχή των Μολοσσών/Θεσπρωτών.', 'Έλεγχος περασμάτων και αγροτικής περιοχής κοντά στον Αχέροντα.', 'Η Πανδοσία ήταν οχυρωμένη αρχαία θέση της Ηπείρου, κοντά στον Αχέροντα. Η σημασία της σχετίζεται με τον έλεγχο της ενδοχώρας και με το δίκτυο οχυρών και πόλεων που αναπτύχθηκαν στην περιοχή κατά τους κλασικούς και ελληνιστικούς χρόνους.', 'Από οχυρωμένη πόλη μετατράπηκε σε αρχαιολογικό τοπίο.', 'medium', 'Η πρόσβαση πιθανότατα απαιτεί προσοχή και επιβεβαίωση διαδρομής πριν την επίσκεψη.', 'Ήπειρος', ARRAY['Κίχυρος / Εφύρα', 'Νεκρομαντείο Αχέροντα', 'Νικόπολη']::text[], 'Το αρχαίο ύψωμα και τμήματα οχύρωσης μέσα στο φυσικό τοπίο.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], ''),
  (147, 'archaia-kalydona', 'Αρχαία Καλυδώνα', ARRAY['Πόλη', 'Ιερό', 'Θέατρο']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η πόλη έχει παλαιότερες ρίζες, με σημαντική ανάπτυξη στους ιστορικούς χρόνους.', 'Αρχαϊκή-Ελληνιστική περίοδος', 'Μετά την ίδρυση της Νικόπολης και τις ρωμαϊκές ανακατατάξεις η σημασία της μειώθηκε.', 'Δεν συνδέεται με έναν ιστορικά βεβαιωμένο κτήτορα· στην παράδοση αποδίδεται σε μυθικό ιδρυτή.', 'Αστικό και θρησκευτικό κέντρο της Αιτωλίας, με σημαντική θέση κοντά στον Εύηνο.', 'Η Αρχαία Καλυδώνα ήταν από τις σπουδαιότερες πόλεις της παράλιας Αιτωλίας. Συνδέεται με ισχυρή μυθολογική παράδοση, με το Λαφριαίο ιερό της Αρτέμιδος και με αρχαίο θέατρο που αναδεικνύει τη δημόσια ζωή της πόλης.', 'Από ζωντανή αιτωλική πόλη μετατράπηκε σε αρχαιολογικό χώρο.', 'easy', 'Η πρόσβαση είναι εύκολη μέσω οδικού δικτύου κοντά στο Ευηνοχώρι και το Μεσολόγγι.', 'Αιτωλία', ARRAY['Πλευρώνα', 'Θέρμο', 'Οινιάδες']::text[], 'Το αρχαίο θέατρο ή άποψη του χώρου στους λόφους Κούρταγα.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_kalydon', 'efaaitl_kalydona']::text[], 'https://upload.wikimedia.org/wikipedia/commons/0/0d/Calydon_Aetolia_2010.JPG'),
  (145, 'archaia-stratos', 'Αρχαία Στράτος', ARRAY['Πόλη', 'Τείχη', 'Θέατρο', 'Ναός']::text[], ARRAY['Κλασική', 'Ελληνιστική']::text[], 'Η πόλη οργανώθηκε ιδιαίτερα στους κλασικούς και ελληνιστικούς χρόνους.', '5ος-2ος αιώνας π.Χ.', 'Η σημασία της μειώθηκε σταδιακά μετά τις ρωμαϊκές αλλαγές στην περιοχή.', 'Αναπτύχθηκε από τους Ακαρνάνες ως ένα από τα βασικά πολιτικά κέντρα τους.', 'Πολιτικό και στρατηγικό κέντρο της αρχαίας Ακαρνανίας.', 'Η Αρχαία Στράτος ήταν ένα από τα σημαντικότερα κέντρα της Ακαρνανίας. Ο χώρος διατηρεί ισχυρές οχυρώσεις, θέατρο και τον ναό του Στρατίου Διός, στοιχεία που δείχνουν τη στρατιωτική, πολιτική και θρησκευτική σημασία της πόλης.', 'Από πρωτεύον αστικό κέντρο της Ακαρνανίας μετατράπηκε σε αρχαιολογικό χώρο.', 'easy', 'Η πρόσβαση είναι σχετικά εύκολη με όχημα από την περιοχή του Αγρινίου.', 'Ακαρνανία', ARRAY['Οινιάδες', 'Αλυζεία', 'Πλευρώνα']::text[], 'Το αρχαίο θέατρο ή τα τείχη της Στράτου.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], ''),
  (148, 'archaia-limnaia', 'Αρχαία Λιμναία', ARRAY['Οχυρωμένη πόλη', 'Ακρόπολη']::text[], ARRAY['Κλασική', 'Ελληνιστική']::text[], 'Η οχύρωση και η πόλη αναπτύχθηκαν κυρίως στους κλασικούς και ελληνιστικούς χρόνους.', 'Κλασική-Ελληνιστική περίοδος', 'Η πόλη εγκαταλείφθηκε σταδιακά στους μεταγενέστερους χρόνους.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· συνδέεται με την αρχαία Ακαρνανία.', 'Έλεγχος στρατηγικής θέσης κοντά στον Αμβρακικό και στους δρόμους της περιοχής.', 'Η Αρχαία Λιμναία ήταν οχυρωμένη πόλη της Ακαρνανίας. Η θέση της είχε στρατηγική σημασία, καθώς έλεγχε πέρασμα και περιοχή κοντά στον Αμβρακικό κόλπο. Σήμερα σώζονται κυρίως κατάλοιπα οχύρωσης και της αρχαίας εγκατάστασης.', 'Από οχυρωμένη πόλη έγινε αρχαιολογική θέση.', 'medium', 'Η πρόσβαση είναι μέτρια και χρειάζεται έλεγχο της τοπικής διαδρομής.', 'Ακαρνανία', ARRAY['Στράτος', 'Αλυζεία', 'Οινιάδες']::text[], 'Τα τμήματα της οχύρωσης με θέα προς το τοπίο της περιοχής.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], ''),
  (153, 'archaia-alyzeia', 'Αρχαία Αλυζεία', ARRAY['Πόλη', 'Ιερό', 'Λιμενική περιοχή']::text[], ARRAY['Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η πόλη αναπτύχθηκε στους κλασικούς και ελληνιστικούς χρόνους.', 'Κλασική-Ρωμαϊκή περίοδος', 'Η χρήση της μειώθηκε σταδιακά στους ύστερους χρόνους.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· συνδέεται με την αρχαία Ακαρνανία.', 'Αστικό και παραθαλάσσιο κέντρο με ιερά και υποδομές.', 'Η Αρχαία Αλυζεία ήταν σημαντική ακαρνανική πόλη κοντά στη θάλασσα. Η περιοχή συνδέεται με ιερά, οχυρώσεις και υδραυλικά έργα, δείχνοντας οργανωμένη πόλη με σχέση προς τη θάλασσα και την ενδοχώρα.', 'Από αρχαία πόλη και τοπικό κέντρο έγινε αρχαιολογικός χώρος.', 'medium', 'Η πρόσβαση εξαρτάται από το επιμέρους σημείο, επειδή τα κατάλοιπα είναι διάσπαρτα.', 'Ακαρνανία', ARRAY['Ιερό Ηρακλή Αλυζείας', 'Αρχαίο φράγμα Αλυζείας', 'Οινιάδες']::text[], 'Πανοραμική άποψη της αρχαίας θέσης ή του ιερού.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], 'https://upload.wikimedia.org/wikipedia/commons/f/f5/Map_of_ancient_Epirus_and_environs_%28English%29.svg'),
  (143, 'archaia-figaleia', 'Αρχαία Φιγαλεία', ARRAY['Πόλη', 'Οχύρωση']::text[], ARRAY['Κλασική', 'Ελληνιστική']::text[], 'Η πόλη ήταν σημαντική ήδη στους κλασικούς χρόνους.', 'Κλασική-Ελληνιστική περίοδος', 'Η αρχαία χρήση εγκαταλείφθηκε σταδιακά στους μεταγενέστερους χρόνους.', 'Δεν συνδέεται με έναν συγκεκριμένο κτήτορα· ήταν αρχαία αρκαδική/πελοποννησιακή πόλη.', 'Αστικό και αμυντικό κέντρο στην ορεινή ενδοχώρα.', 'Η Αρχαία Φιγαλεία ήταν σημαντική πόλη της ορεινής Πελοποννήσου. Συνδέεται άμεσα με τον Ναό του Επικούριου Απόλλωνα στις Βάσσες και διατηρεί κατάλοιπα οχύρωσης και αρχαίας κατοίκησης.', 'Από αρχαία πόλη μετατράπηκε σε αρχαιολογικό τοπίο.', 'medium', 'Η πρόσβαση είναι μέτρια λόγω της ορεινής περιοχής.', 'Φιγαλεία / Ορεινή Πελοπόννησος', ARRAY['Ναός Επικούριου Απόλλωνα', 'Βάσσες', 'Λύκαιο Όρος']::text[], 'Τα αρχαία τείχη ή το ορεινό τοπίο της Φιγαλείας.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], ''),
  (140, 'archaia-alifeira', 'Αρχαία Αλίφειρα', ARRAY['Πόλη', 'Ιερό', 'Ακρόπολη']::text[], ARRAY['Κλασική', 'Ελληνιστική']::text[], 'Η πόλη αναπτύχθηκε κυρίως στους κλασικούς και ελληνιστικούς χρόνους.', 'Κλασική-Ελληνιστική περίοδος', 'Η κατοίκηση και η λατρευτική χρήση μειώθηκαν σταδιακά.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· συνδέεται με την αρχαία Τριφυλία/Αρκαδία.', 'Αστικό και λατρευτικό κέντρο με ακρόπολη και ιερά.', 'Η Αρχαία Αλίφειρα βρίσκεται σε ορεινή θέση και συνδέεται με ισχυρή οχύρωση και λατρευτικά μνημεία. Ο χώρος είναι γνωστός για την ακρόπολη και τα κατάλοιπα ιερών, που δείχνουν τη σημασία της πόλης στην ευρύτερη περιοχή.', 'Από αρχαία πόλη και ιερό μετατράπηκε σε αρχαιολογικό χώρο.', 'medium', 'Η πρόσβαση είναι μέτρια και απαιτεί διαδρομή σε ορεινή περιοχή.', 'Τριφυλία / Ηλεία', ARRAY['Φιγαλεία', 'Ολυμπία', 'Βάσσες']::text[], 'Η ακρόπολη ή τα κατάλοιπα του ιερού μέσα στο ορεινό τοπίο.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], ''),
  (137, 'archaia-pellini', 'Αρχαία Πελλήνη', ARRAY['Πόλη', 'Ακρόπολη']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική']::text[], 'Η πόλη ήταν γνωστή ήδη από τους αρχαίους χρόνους και αναπτύχθηκε σε στρατηγική θέση.', 'Αρχαϊκή-Ελληνιστική περίοδος', 'Η αρχαία πόλη εγκαταλείφθηκε ή μετασχηματίστηκε σταδιακά στους μεταγενέστερους χρόνους.', 'Δεν συνδέεται με έναν συγκεκριμένο ιστορικό κτήτορα.', 'Αστικό και στρατηγικό κέντρο της Αχαΐας.', 'Η Αρχαία Πελλήνη ήταν μία από τις σημαντικές πόλεις της αρχαίας Αχαΐας. Η θέση της σε ύψωμα προσέφερε έλεγχο της περιοχής και προστασία, ενώ τα κατάλοιπα της πόλης δείχνουν μακρά χρήση στους ιστορικούς χρόνους.', 'Από αρχαία πόλη μετατράπηκε σε αρχαιολογική θέση.', 'medium', 'Η πρόσβαση είναι μέτρια και χρειάζεται έλεγχο της τοπικής διαδρομής.', 'Αχαΐα', ARRAY['Αιγείρα', 'Ψωφίδα', 'Κορινθία']::text[], 'Η αρχαία ακρόπολη ή γενική άποψη του υψώματος.', 'medium', true, 'Manual-review import: mapped cleaned monument "Αρχαία Πελλήνη" to catalog_id 137 "Αρχαία Πελλήνη Αχαΐας". Alternatives: 142: Αρχαία Ψωφίδα (0.073); 1: Κορυφη Αυγο Παγγαιο (0.000); 5: Πιθανή θέση της Ποικίλης Στοάς (0.000).', ARRAY['odysseus_arch_sites_general']::text[], 'https://upload.wikimedia.org/wikipedia/commons/d/d5/Towns_of_ancient_Achaia.svg'),
  (142, 'archaia-psofida', 'Αρχαία Ψωφίδα', ARRAY['Πόλη', 'Οχύρωση']::text[], ARRAY['Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η πόλη αναπτύχθηκε σε στρατηγική θέση στην ενδοχώρα της βόρειας Πελοποννήσου.', 'Κλασική-Ρωμαϊκή περίοδος', 'Η χρήση της μειώθηκε στους μεταγενέστερους χρόνους.', 'Δεν είναι γνωστός συγκεκριμένος κτήτορας· συνδέεται με την Αρκαδία και την Αχαΐα.', 'Έλεγχος περάσματος και οργάνωση της τοπικής ενδοχώρας.', 'Η Αρχαία Ψωφίδα ήταν πόλη σε σημαντική θέση, κοντά σε φυσικά περάσματα και ποτάμια της περιοχής. Η οχύρωση και τα κατάλοιπα της πόλης δείχνουν τη σημασία της ως τοπικού κέντρου.', 'Από αρχαία πόλη μετατράπηκε σε αρχαιολογική θέση.', 'medium', 'Η πρόσβαση είναι μέτρια λόγω της εσωτερικής ορεινής θέσης.', 'Αχαΐα / Αρκαδική ενδοχώρα', ARRAY['Αρχαία Πελλήνη', 'Αιγείρα', 'Φενεός']::text[], 'Τα ερείπια της οχύρωσης ή η θέση κοντά στο φυσικό τοπίο.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], 'https://upload.wikimedia.org/wikipedia/commons/8/8a/Psophis_city_plan.png'),
  (14, 'iero-artemidos-aylideias', 'Ιερό Αρτέμιδος Αυλιδείας', ARRAY['Ιερό', 'Λατρευτικός χώρος']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η λατρεία στον χώρο αναπτύχθηκε στους ιστορικούς χρόνους.', 'Αρχαϊκή-Ρωμαϊκή περίοδος', 'Η αρχαία λατρεία σταμάτησε σταδιακά μετά την αρχαιότητα.', 'Δεν χτίστηκε από ένα μόνο πρόσωπο· συνδέεται με τη λατρεία της Αρτέμιδος στην Αυλίδα.', 'Λατρεία της Αρτέμιδος Αυλιδείας και σύνδεση με τη μυθολογία της εκστρατείας στην Τροία.', 'Το Ιερό της Αρτέμιδος στην Αυλίδα είναι από τα πιο χαρακτηριστικά λατρευτικά σημεία της Βοιωτίας. Η περιοχή συνδέεται με τον μύθο της Ιφιγένειας και της αναχώρησης των Αχαιών για την Τροία, ενώ ο χώρος είχε διαχρονική λατρευτική χρήση.', 'Από αρχαίο ιερό μετατράπηκε σε αρχαιολογικό χώρο.', 'easy', 'Η πρόσβαση είναι σχετικά εύκολη από την περιοχή της Αυλίδας.', 'Αυλίδα / Βοιωτία', ARRAY['Μυκηναϊκοί τάφοι Αυλίδας', 'Αρχαία Θήβα', 'Δήλιο']::text[], 'Τα κατάλοιπα του ιερού με φόντο την περιοχή της Αυλίδας.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], ''),
  (162, 'archaia-anthidona', 'Αρχαία Ανθηδώνα', ARRAY['Πόλη', 'Λιμάνι', 'Οχύρωση']::text[], ARRAY['Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η πόλη αναπτύχθηκε στους ιστορικούς χρόνους ως παραθαλάσσιο κέντρο.', 'Κλασική-Ρωμαϊκή περίοδος', 'Η χρήση της μειώθηκε σταδιακά στους μεταγενέστερους χρόνους.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· ήταν βοιωτική πόλη.', 'Παραθαλάσσιο αστικό και εμπορικό κέντρο στη Βοιωτία.', 'Η Αρχαία Ανθηδώνα ήταν παραθαλάσσια πόλη της Βοιωτίας, με σχέση προς τη θάλασσα και τους θαλάσσιους δρόμους του Ευβοϊκού. Η θέση της την έκανε σημαντικό τοπικό κέντρο, ενώ τα σωζόμενα κατάλοιπα συνδέονται με οχύρωση και λιμενική δραστηριότητα.', 'Από παραθαλάσσια αρχαία πόλη μετατράπηκε σε αρχαιολογικό χώρο.', 'medium', 'Η πρόσβαση είναι σχετικά εύκολη, αλλά τα κατάλοιπα είναι διάσπαρτα.', 'Βοιωτία', ARRAY['Αυλίδα', 'Δήλιο', 'Εύβοια']::text[], 'Πανοραμική άποψη του χώρου με τη θάλασσα.', 'medium', true, 'Manual-review import: mapped cleaned monument "Αρχαία Ανθηδώνα" to catalog_id 162 "Αρχαία Ανθηδώνα Βοιωτίας". Alternatives: 53: Μυκηναϊκοί θαλαμωτοί τάφοι (0.073); 62: Τρόπαιο Επαμεινώνδα (0.073); 69: Αρχαιολογικό Μουσείο Θηβών (0.073).', ARRAY['odysseus_arch_sites_general']::text[], ''),
  (134, 'archaia-aliartos', 'Αρχαία Αλίαρτος', ARRAY['Πόλη', 'Οχύρωση']::text[], ARRAY['Κλασική', 'Ελληνιστική']::text[], 'Η πόλη αναπτύχθηκε στους ιστορικούς χρόνους στη βοιωτική ενδοχώρα.', 'Κλασική-Ελληνιστική περίοδος', 'Η αρχαία χρήση μειώθηκε σταδιακά στους μεταγενέστερους χρόνους.', 'Δεν συνδέεται με συγκεκριμένο κτήτορα· ήταν βοιωτική πόλη.', 'Τοπικό κέντρο της Βοιωτίας κοντά στην Κωπαΐδα.', 'Η Αρχαία Αλίαρτος ήταν πόλη της Βοιωτίας σε σημαντική θέση κοντά στην περιοχή της Κωπαΐδας. Τα κατάλοιπα της οχύρωσης και της αρχαίας εγκατάστασης δείχνουν την αξία της ως τοπικού κέντρου στους ιστορικούς χρόνους.', 'Από αρχαία πόλη μετατράπηκε σε αρχαιολογική θέση.', 'easy', 'Η πρόσβαση είναι σχετικά εύκολη από τη σύγχρονη Αλίαρτο.', 'Βοιωτία', ARRAY['Γλα', 'Θήβα', 'Κοιλάδα Μουσών']::text[], 'Η οχύρωση ή ο λόφος της αρχαίας πόλης.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], ''),
  (135, 'iero-apollona-dilioy', 'Ιερό Απόλλωνα Δηλίου', ARRAY['Ιερό', 'Λατρευτικός χώρος']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική']::text[], 'Το ιερό αναπτύχθηκε στους ιστορικούς χρόνους.', 'Αρχαϊκή-Ελληνιστική περίοδος', 'Η λατρευτική χρήση σταμάτησε σταδιακά.', 'Δεν είναι γνωστός συγκεκριμένος κτήτορας· συνδέεται με βοιωτικές κοινότητες.', 'Λατρεία του Απόλλωνα Δηλίου.', 'Το Ιερό του Απόλλωνα Δηλίου αποτελούσε σημαντικό λατρευτικό σημείο της βοιωτικής παραλιακής ζώνης. Η θέση του συνδέει τη Βοιωτία με τον Ευβοϊκό και με τα θρησκευτικά δίκτυα της περιοχής.', 'Από ιερό μετατράπηκε σε αρχαιολογική θέση.', 'medium', 'Η πρόσβαση χρειάζεται επιβεβαίωση ανάλογα με το ακριβές σημείο.', 'Βοιωτία', ARRAY['Αυλίδα', 'Ανθηδώνα', 'Ερέτρια']::text[], 'Άποψη των καταλοίπων του ιερού ή του παραλιακού τοπίου.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], ''),
  (62, 'tropaio-epameinonda-sta-leyktra', 'Τρόπαιο Επαμεινώνδα στα Λεύκτρα', ARRAY['Μνημείο μάχης', 'Τρόπαιο']::text[], ARRAY['Κλασική']::text[], 'Συνδέεται με τη μάχη των Λεύκτρων το 371 π.Χ.', '4ος αιώνας π.Χ.', 'Το μνημείο έπαψε να έχει αρχική πολεμική λειτουργία και σήμερα σώζεται ως ιστορικό μνημείο.', 'Συνδέεται με τους Θηβαίους και τη νίκη του Επαμεινώνδα επί των Σπαρτιατών.', 'Μνημείο ανάμνησης της θηβαϊκής νίκης στη μάχη των Λεύκτρων.', 'Το τρόπαιο στα Λεύκτρα συνδέεται με μία από τις πιο σημαντικές μάχες της αρχαίας Ελλάδας. Η νίκη των Θηβαίων το 371 π.Χ. ανέτρεψε την κυριαρχία της Σπάρτης και ανέδειξε τη Θήβα σε μεγάλη δύναμη του ελληνικού κόσμου.', 'Από πολεμικό μνημείο μνήμης μετατράπηκε σε αρχαιολογικό και ιστορικό σημείο.', 'easy', 'Η πρόσβαση είναι εύκολη κοντά στον σύγχρονο οικισμό Λεύκτρα.', 'Θήβα / Βοιωτία', ARRAY['Αρχαία Θήβα', 'Καδμεία', 'Βοιωτία']::text[], 'Το αναστηλωμένο τρόπαιο ή το πεδίο της μάχης.', 'medium', true, 'Manual-review import: mapped cleaned monument "Τρόπαιο Επαμεινώνδα στα Λεύκτρα" to catalog_id 62 "Τρόπαιο Επαμεινώνδα". Alternatives: 53: Μυκηναϊκοί θαλαμωτοί τάφοι (0.073); 69: Αρχαιολογικό Μουσείο Θηβών (0.073); 75: Πύργος Αλιάρτου/Μουλκίου (0.073).', ARRAY['odysseus_arch_sites_general']::text[], ''),
  (206, 'leykanti-xeropoli', 'Λευκαντί / Ξερόπολη', ARRAY['Οικισμός', 'Νεκροταφείο', 'Πρωτογεωμετρικός χώρος']::text[], ARRAY['Πρωτογεωμετρική', 'Γεωμετρική', 'Αρχαϊκή']::text[], 'Ο χώρος έχει ιδιαίτερη σημασία κυρίως στον 10ο-8ο αιώνα π.Χ.', 'Πρωτογεωμετρική-Γεωμετρική περίοδος', 'Η σημασία του μεταβλήθηκε με την ανάπτυξη άλλων ευβοϊκών πόλεων.', 'Δεν συνδέεται με συγκεκριμένο κτήτορα· αποτελεί πρώιμο ευβοϊκό οικιστικό και ταφικό κέντρο.', 'Οικιστική και ταφική χρήση, με πολύτιμα στοιχεία για την περίοδο μετά την κατάρρευση του μυκηναϊκού κόσμου.', 'Το Λευκαντί είναι ένας από τους σημαντικότερους αρχαιολογικούς χώρους για την κατανόηση των λεγόμενων Σκοτεινών Αιώνων και της πρώιμης Γεωμετρικής περιόδου. Τα ευρήματα δείχνουν επαφές, πλούτο και κοινωνική οργάνωση σε μια εποχή που θεωρούνταν παλαιότερα λιγότερο γνωστή.', 'Από οικισμός και νεκροταφείο μετατράπηκε σε αρχαιολογική θέση μεγάλης ερευνητικής σημασίας.', 'medium', 'Η πρόσβαση είναι σχετικά εύκολη στην περιοχή του Λευκαντίου, αλλά ορισμένα σημεία δεν είναι τόσο οργανωμένα για επίσκεψη.', 'Εύβοια', ARRAY['Ερέτρια', 'Αμάρυνθος', 'Χαλκίδα']::text[], 'Η Ξερόπολη ή γενική άποψη της περιοχής του Λευκαντίου.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: fuzzy (0.740).', ARRAY['odysseus_arch_sites_general']::text[], 'https://upload.wikimedia.org/wikipedia/commons/9/93/Lefkadi_8074754.JPG'),
  (205, 'archaia-dystos', 'Αρχαία Δύστος', ARRAY['Πόλη', 'Οχύρωση', 'Πυραμιδοειδές μνημείο']::text[], ARRAY['Κλασική', 'Ελληνιστική']::text[], 'Η πόλη αναπτύχθηκε στους ιστορικούς χρόνους.', 'Κλασική-Ελληνιστική περίοδος', 'Η αρχαία χρήση μειώθηκε σταδιακά.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· ήταν ευβοϊκή πόλη.', 'Οχυρωμένη θέση και τοπικό κέντρο στην Εύβοια.', 'Η Αρχαία Δύστος είναι γνωστή για τα κατάλοιπα της αρχαίας πόλης και το ιδιόμορφο πυραμιδοειδές μνημείο της περιοχής. Η θέση της σε φυσικά προστατευμένο τοπίο δείχνει την αμυντική και τοπική σημασία της.', 'Από αρχαία πόλη μετατράπηκε σε αρχαιολογικό τοπίο.', 'medium', 'Η πρόσβαση είναι μέτρια και χρειάζεται προσοχή ανάλογα με τη διαδρομή.', 'Εύβοια', ARRAY['Ερέτρια', 'Αμάρυνθος', 'Λευκαντί']::text[], 'Το πυραμιδοειδές μνημείο ή η οχύρωση της αρχαίας Δύστου.', 'medium', true, 'Manual-review import: mapped cleaned monument "Αρχαία Δύστος" to catalog_id 205 "Αρχαία Δύστος Ευβοίας / Πυραμίδα". Alternatives: 1: Κορυφη Αυγο Παγγαιο (0.000); 5: Πιθανή θέση της Ποικίλης Στοάς (0.000); 7: Μεγάλα Προπύλαια Ελευσίνας (0.000).', ARRAY['odysseus_arch_sites_general']::text[], 'https://upload.wikimedia.org/wikipedia/commons/c/cb/DE_Distyon.svg'),
  (114, 'archaia-thira', 'Αρχαία Θήρα', ARRAY['Πόλη', 'Ιερά', 'Αγορά']::text[], ARRAY['Γεωμετρική', 'Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η πόλη ιδρύθηκε σε στρατηγικό ύψωμα και αναπτύχθηκε στους ιστορικούς χρόνους.', 'Γεωμετρική-Ρωμαϊκή περίοδος', 'Η χρήση της μειώθηκε στους μεταγενέστερους χρόνους.', 'Συνδέεται με Δωριείς αποίκους και την αρχαία πόλη της Θήρας.', 'Αστικό, θρησκευτικό και στρατηγικό κέντρο του νησιού.', 'Η Αρχαία Θήρα βρίσκεται στο Μέσα Βουνό και προσφέρει εντυπωσιακή θέα στο Αιγαίο. Η θέση της πάνω σε ύψωμα είχε αμυντικό και στρατηγικό χαρακτήρα, ενώ τα κατάλοιπα της πόλης περιλαμβάνουν δρόμους, ιερά, δημόσια κτήρια και κατοικίες.', 'Από αρχαία πόλη μετατράπηκε σε οργανωμένο αρχαιολογικό χώρο.', 'medium', 'Η πρόσβαση είναι μέτρια λόγω της ανηφορικής διαδρομής και της θέσης στο βουνό.', 'Θήρα / Κυκλάδες', ARRAY['Ακρωτήρι Θήρας', 'Μουσείο Προϊστορικής Θήρας', 'Καμάρι']::text[], 'Η αρχαία πόλη στο Μέσα Βουνό με θέα στο Αιγαίο.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_ancient_thera']::text[], 'https://upload.wikimedia.org/wikipedia/commons/1/1f/Santorini_ancient_thera_1.jpg'),
  (83, 'archaia-karthaia', 'Αρχαία Καρθαία', ARRAY['Πόλη', 'Ναοί', 'Θέατρο']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η πόλη αναπτύχθηκε από τους αρχαϊκούς χρόνους.', 'Αρχαϊκή-Ρωμαϊκή περίοδος', 'Η αρχαία πόλη εγκαταλείφθηκε σταδιακά στους μεταγενέστερους χρόνους.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· ήταν μία από τις αρχαίες πόλεις της Κέας.', 'Αστικό και θρησκευτικό κέντρο της Κέας.', 'Η Καρθαία ήταν μία από τις σημαντικότερες αρχαίες πόλεις της Κέας. Ο χώρος συνδυάζει αρχαίους ναούς, θέατρο και εντυπωσιακό φυσικό τοπίο, καθώς βρίσκεται σε απομονωμένη παραθαλάσσια θέση που διατηρεί έντονα την αίσθηση της αρχαίας πόλης.', 'Από αρχαία πόλη μετατράπηκε σε αρχαιολογικό χώρο μέσα σε προστατευμένο φυσικό τοπίο.', 'hard', 'Η πρόσβαση είναι σχετικά δύσκολη, καθώς απαιτεί πεζοπορία ή προσέγγιση από ειδική διαδρομή.', 'Κέα / Κυκλάδες', ARRAY['Ναοί Καρθαίας', 'Αρχαίο θέατρο Καρθαίας', 'Κυκλάδες']::text[], 'Οι ναοί της Καρθαίας με φόντο τη θάλασσα.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Temple_of_Athena_(Karthaia).JPG'),
  (170, 'skarkos-ioy', 'Σκάρκος Ίου', ARRAY['Προϊστορικός οικισμός', 'Κυκλαδικός πολιτισμός']::text[], ARRAY['Πρωτοκυκλαδική']::text[], 'Ο οικισμός χρονολογείται στην Πρωτοκυκλαδική περίοδο, περίπου στην 3η χιλιετία π.Χ.', 'Πρώιμη Εποχή του Χαλκού', 'Ο οικισμός εγκαταλείφθηκε σε προϊστορική φάση και διατηρήθηκε ως αρχαιολογικό στρώμα.', 'Δεν γνωρίζουμε κτήτορα· αποτελεί οργανωμένο προϊστορικό κυκλαδικό οικισμό.', 'Κατοίκηση, παραγωγή και οργάνωση κοινότητας της Πρώιμης Εποχής του Χαλκού.', 'Ο Σκάρκος είναι ένας από τους σημαντικότερους προϊστορικούς οικισμούς των Κυκλάδων. Τα σπίτια, οι δρόμοι και τα ευρήματα δίνουν καθαρή εικόνα της ζωής στο Αιγαίο κατά την Πρώιμη Εποχή του Χαλκού.', 'Δεν άλλαξε χρήση ως πόλη· μετά την εγκατάλειψη διατηρήθηκε ως αρχαιολογικός χώρος.', 'easy', 'Η πρόσβαση είναι σχετικά εύκολη από τη Χώρα της Ίου.', 'Πρωτοκυκλαδικός πολιτισμός / Ίος', ARRAY['Αρχαιολογικό Μουσείο Ίου', 'Κυκλαδικοί οικισμοί', 'Ακρωτήρι Θήρας']::text[], 'Πανοραμική άποψη του οικισμού με τα κυκλαδικά σπίτια.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_skarkos_ios']::text[], 'https://upload.wikimedia.org/wikipedia/commons/b/b4/Skarkos_Hill_Settlement_on_Ios.jpg'),
  (161, 'naos-apollona-sto-despotiko', 'Ναός Απόλλωνα στο Δεσποτικό', ARRAY['Ιερό', 'Ναός', 'Κυκλάδες']::text[], ARRAY['Αρχαϊκή', 'Κλασική']::text[], 'Το ιερό αναπτύχθηκε κυρίως στους αρχαϊκούς χρόνους.', 'Αρχαϊκή-Κλασική περίοδος', 'Η λατρευτική χρήση σταμάτησε στους μεταγενέστερους χρόνους.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· συνδέεται με τις κυκλαδικές κοινότητες της Πάρου και της Αντιπάρου.', 'Λατρεία του Απόλλωνα και λειτουργία ιερού με διαπεριφερειακή σημασία στις Κυκλάδες.', 'Το ιερό του Απόλλωνα στο Δεσποτικό είναι από τα σημαντικότερα αρχαϊκά ιερά των Κυκλάδων. Η θέση του σε μικρό νησί απέναντι από την Αντίπαρο δείχνει τη σημασία των θαλάσσιων δρόμων και των ιερών του Αιγαίου.', 'Από ενεργό κυκλαδικό ιερό μετατράπηκε σε αρχαιολογικό χώρο υπό αναστήλωση και έρευνα.', 'hard', 'Η πρόσβαση είναι δύσκολη γιατί απαιτεί θαλάσσια μετακίνηση προς το Δεσποτικό.', 'Κυκλάδες / Πάρος-Αντίπαρος', ARRAY['Αντίπαρος', 'Πάρος', 'Κυκλαδικά ιερά']::text[], 'Το αναστηλωμένο ιερό του Απόλλωνα με φόντο τη θάλασσα.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], 'https://upload.wikimedia.org/wikipedia/commons/4/4e/%CE%9F_%CE%9D%CE%B1%CF%8C%CF%82_%CF%84%CE%BF%CF%85_%CE%91%CF%80%CF%8C%CE%BB%CE%BB%CF%89%CE%BD%CE%B1%2C_%CE%94%CE%B5%CF%83%CF%80%CE%BF%CF%84%CE%B9%CE%BA%CF%8C.jpg'),
  (166, 'naos-dimitras-sto-sagkri-naxoy', 'Ναός Δήμητρας στο Σαγκρί Νάξου', ARRAY['Ναός', 'Ιερό']::text[], ARRAY['Αρχαϊκή', 'Κλασική']::text[], 'Ο ναός χτίστηκε γύρω στον 6ο αιώνα π.Χ.', '6ος αιώνας π.Χ. - Κλασική περίοδος', 'Η αρχαία λατρεία σταμάτησε και ο χώρος άλλαξε χρήση στους μεταγενέστερους χρόνους.', 'Δεν γνωρίζουμε συγκεκριμένο αρχιτέκτονα· συνδέεται με την αρχαία Νάξο.', 'Λατρεία της Δήμητρας και πιθανώς συναφών αγροτικών θεοτήτων.', 'Ο Ναός της Δήμητρας στο Σαγκρί είναι ένα από τα σημαντικότερα αρχαϊκά μνημεία της Νάξου. Είναι χτισμένος από ναξιακό μάρμαρο και δείχνει την ισχύ της Νάξου στην αρχαϊκή εποχή, καθώς και τη σημασία της λατρείας στην αγροτική ενδοχώρα του νησιού.', 'Από αρχαίο ιερό μετατράπηκε αργότερα σε χριστιανικό χώρο και σήμερα σε αρχαιολογικό μνημείο.', 'easy', 'Η πρόσβαση είναι εύκολη με όχημα από τη Χώρα της Νάξου.', 'Αρχαία Νάξος / Κυκλάδες', ARRAY['Κούροι Φλεριού', 'Αρχαία Νάξος', 'Γύρουλας']::text[], 'Ο ναός της Δήμητρας μέσα στο ναξιακό τοπίο.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['odysseus_sangri_naxos']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Temple_Demeter_Naxos_1.JPG'),
  (169, 'koyros-flerioy-latomeio-naxoy', 'Κούρος Φλεριού / Λατομείο Νάξου', ARRAY['Άγαλμα', 'Λατομείο', 'Αρχαϊκή γλυπτική']::text[], ARRAY['Αρχαϊκή']::text[], 'Οι κούροι συνδέονται με την αρχαϊκή περίοδο και την ανάπτυξη της ναξιακής γλυπτικής.', '7ος-6ος αιώνας π.Χ.', 'Τα αγάλματα έμειναν ημιτελή στα λατομεία και δεν ολοκλήρωσαν την αρχική τους χρήση.', 'Κατασκευάστηκαν από Ναξίους τεχνίτες/λιθοξόους.', 'Παραγωγή μνημειακής γλυπτικής από ναξιακό μάρμαρο.', 'Οι Κούροι στο Φλεριό δείχνουν τη μεγάλη παράδοση της Νάξου στην αρχαϊκή γλυπτική και τη χρήση των τοπικών μαρμάρων. Τα ημιτελή αγάλματα στα αρχαία λατομεία προσφέρουν σπάνια εικόνα της διαδικασίας κατασκευής μεγάλων μαρμάρινων έργων.', 'Δεν άλλαξαν χρήση· εγκαταλείφθηκαν ημιτελή και σήμερα αποτελούν αρχαιολογικό τεκμήριο παραγωγής.', 'easy', 'Η πρόσβαση είναι σχετικά εύκολη με όχημα και μικρό περπάτημα.', 'Αρχαία Νάξος / Κυκλάδες', ARRAY['Ναός Δήμητρας Σαγκρίου', 'Αρχαία Νάξος', 'Κυκλαδική γλυπτική']::text[], 'Ο ξαπλωμένος κούρος στο αρχαίο λατομείο.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: fuzzy (0.688).', ARRAY['odysseus_arch_sites_general']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Kouros_of_Flerio,_Naxos,_6th_c_BC,_118961.jpg'),
  (200, 'fylakopi-miloy', 'Φυλακωπή Μήλου', ARRAY['Προϊστορικός οικισμός', 'Οχύρωση', 'Λιμενικό κέντρο']::text[], ARRAY['Πρωτοκυκλαδική', 'Μεσοκυκλαδική', 'Υστεροκυκλαδική']::text[], 'Ο οικισμός αναπτύχθηκε από την Πρώιμη Εποχή του Χαλκού και γνώρισε διαδοχικές φάσεις.', '3η-2η χιλιετία π.Χ.', 'Ο χώρος εγκαταλείφθηκε μετά τις προϊστορικές φάσεις κατοίκησης.', 'Δεν γνωρίζουμε κτήτορα· αποτελεί σημαντικό προϊστορικό κέντρο της Μήλου.', 'Οικισμός με θαλάσσιες επαφές, παραγωγή και εμπόριο στο Αιγαίο.', 'Η Φυλακωπή είναι ένας από τους σημαντικότερους προϊστορικούς οικισμούς του Αιγαίου. Η θέση της στη Μήλο, νησί πλούσιο σε οψιανό, την έκανε σημαντικό κέντρο επαφών και ανταλλαγών στην προϊστορική περίοδο.', 'Από προϊστορικός οικισμός μετατράπηκε σε αρχαιολογική θέση.', 'medium', 'Η πρόσβαση είναι σχετικά εύκολη, αλλά ο χώρος χρειάζεται προσοχή λόγω της παράκτιας θέσης.', 'Μήλος / Κυκλαδικός πολιτισμός', ARRAY['Οψιανός Μήλου', 'Ακρωτήρι Θήρας', 'Κυκλαδικοί οικισμοί']::text[], 'Τα ερείπια της Φυλακωπής δίπλα στη θάλασσα.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], 'https://upload.wikimedia.org/wikipedia/commons/a/a0/Phylakopi_flying_fish.jpg'),
  (157, 'zagora-androy', 'Ζαγορά Άνδρου', ARRAY['Οικισμός', 'Οχύρωση']::text[], ARRAY['Γεωμετρική']::text[], 'Ο οικισμός χρονολογείται κυρίως στον 8ο αιώνα π.Χ.', 'Γεωμετρική περίοδος', 'Ο οικισμός εγκαταλείφθηκε σχετικά νωρίς, γεγονός που βοήθησε στη διατήρησή του.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· αποτελεί οικισμό της Γεωμετρικής περιόδου στην Άνδρο.', 'Κατοίκηση και οργάνωση κοινότητας της πρώιμης ιστορικής περιόδου.', 'Η Ζαγορά της Άνδρου είναι πολύ σημαντικός οικισμός της Γεωμετρικής περιόδου. Επειδή εγκαταλείφθηκε νωρίς, διατηρεί καθαρή εικόνα της οικιστικής οργάνωσης και της ζωής στο Αιγαίο πριν από την πλήρη ανάπτυξη των κλασικών πόλεων.', 'Μετά την εγκατάλειψή της δεν μετατράπηκε σε μεγάλη μεταγενέστερη πόλη, άρα σώζεται ως αρχαιολογικό στρώμα.', 'hard', 'Η πρόσβαση είναι δύσκολη και απαιτεί πεζοπορία σε σχετικά απομονωμένη θέση.', 'Άνδρος / Κυκλάδες', ARRAY['Παλαιόπολη Άνδρου', 'Στρόφιλας', 'Υψηλή Άνδρου']::text[], 'Η οχυρωμένη θέση της Ζαγοράς με το άγριο κυκλαδικό τοπίο.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], ''),
  (165, 'palaiopoli-androy', 'Παλαιόπολη Άνδρου', ARRAY['Πόλη', 'Λιμάνι', 'Τείχη']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η πόλη αναπτύχθηκε στους ιστορικούς χρόνους ως βασικό κέντρο της Άνδρου.', 'Αρχαϊκή-Ρωμαϊκή περίοδος', 'Η σημασία της μειώθηκε σταδιακά στους μεταγενέστερους χρόνους.', 'Δεν συνδέεται με έναν συγκεκριμένο κτήτορα· ήταν η αρχαία πόλη της Άνδρου.', 'Αστικό, λιμενικό και διοικητικό κέντρο του νησιού.', 'Η Παλαιόπολη ήταν η αρχαία πόλη της Άνδρου και το βασικό κέντρο του νησιού στους ιστορικούς χρόνους. Η θέση της σε παραθαλάσσια ζώνη δείχνει τη σημασία του λιμανιού και των θαλάσσιων επαφών.', 'Από αρχαία πόλη και λιμάνι μετατράπηκε σε αρχαιολογική ζώνη.', 'medium', 'Η πρόσβαση είναι σχετικά εύκολη, αλλά τα κατάλοιπα είναι διάσπαρτα.', 'Άνδρος / Κυκλάδες', ARRAY['Ζαγορά Άνδρου', 'Στρόφιλας', 'Υψηλή Άνδρου']::text[], 'Η Παλαιόπολη με θέα προς τη θάλασσα.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], ''),
  (158, 'strofilas-androy', 'Στρόφιλας Άνδρου', ARRAY['Νεολιθικός οικισμός', 'Προϊστορική οχύρωση']::text[], ARRAY['Νεολιθική']::text[], 'Ο οικισμός ανήκει στη Νεολιθική περίοδο.', 'Νεότερη Νεολιθική περίοδος', 'Ο οικισμός εγκαταλείφθηκε σε προϊστορική φάση.', 'Δεν γνωρίζουμε κτήτορα· αποτελεί προϊστορικό οικισμό της Άνδρου.', 'Κατοίκηση και οχύρωση πρώιμης οργανωμένης κοινότητας στο Αιγαίο.', 'Ο Στρόφιλας είναι ένας από τους σημαντικότερους νεολιθικούς οικισμούς των Κυκλάδων. Ξεχωρίζει για την προϊστορική οχύρωση και τα βραχογραφήματα, που δείχνουν πολύ πρώιμη κοινωνική οργάνωση στο Αιγαίο.', 'Δεν άλλαξε σε ιστορική πόλη· διατηρήθηκε ως προϊστορική αρχαιολογική θέση.', 'medium', 'Η πρόσβαση χρειάζεται έλεγχο, επειδή δεν πρόκειται για τυπικό τουριστικό αρχαιολογικό χώρο.', 'Νεολιθικό Αιγαίο / Άνδρος', ARRAY['Ζαγορά Άνδρου', 'Παλαιόπολη Άνδρου', 'Κυκλαδικοί οικισμοί']::text[], 'Η προϊστορική οχύρωση ή τα βραχογραφήματα του Στρόφιλα.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], ''),
  (171, 'maroylas-kythnoy', 'Μαρουλάς Κύθνου', ARRAY['Προϊστορικός οικισμός', 'Ταφές']::text[], ARRAY['Μεσολιθική']::text[], 'Ο χώρος χρονολογείται κυρίως στη Μεσολιθική περίοδο.', 'Μεσολιθική περίοδος', 'Η θέση εγκαταλείφθηκε μετά τη χρήση της στην προϊστορία.', 'Δεν υπάρχει κτήτορας· πρόκειται για προϊστορική εγκατάσταση κυνηγών/τροφοσυλλεκτών και πρώιμων νησιωτικών κοινοτήτων.', 'Πρώιμη εγκατάσταση και ταφική χρήση στο Αιγαίο.', 'Ο Μαρουλάς της Κύθνου είναι από τις σημαντικότερες μεσολιθικές θέσεις του Αιγαίου. Η σημασία του είναι μεγάλη επειδή δείχνει πολύ πρώιμη ανθρώπινη παρουσία και δραστηριότητα στις Κυκλάδες, πολύ πριν από την ανάπτυξη των γνωστών κυκλαδικών οικισμών της Εποχής του Χαλκού.', 'Δεν άλλαξε χρήση· αποτελεί προϊστορική αρχαιολογική θέση.', 'medium', 'Η πρόσβαση χρειάζεται έλεγχο, καθώς πρόκειται για ειδικό αρχαιολογικό σημείο και όχι πάντα οργανωμένο χώρο επίσκεψης.', 'Προϊστορικό Αιγαίο / Κύθνος', ARRAY['Κυκλαδικές προϊστορικές θέσεις', 'Σκάρκος Ίου', 'Φυλακωπή Μήλου']::text[], 'Η παράκτια θέση του Μαρουλά ή γενική άποψη του χώρου.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], 'https://upload.wikimedia.org/wikipedia/commons/f/fb/Mesolithic_site_Maroulas%2C_Kythnos%2C_190216.jpg'),
  (178, 'archaia-kameiros-rodoy', 'Αρχαία Κάμειρος Ρόδου', ARRAY['Πόλη', 'Αγορά', 'Ναοί', 'Οικισμός']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η πόλη αναπτύχθηκε ιδιαίτερα στους αρχαϊκούς και κλασικούς χρόνους.', 'Αρχαϊκή-Ρωμαϊκή περίοδος', 'Η χρήση της μειώθηκε σταδιακά στους μεταγενέστερους χρόνους.', 'Δεν χτίστηκε από έναν μόνο κτήτορα· ήταν μία από τις τρεις αρχαίες πόλεις της Ρόδου.', 'Αστικό, θρησκευτικό και αγροτικό κέντρο της Ρόδου.', 'Η Αρχαία Κάμειρος ήταν μία από τις τρεις μεγάλες αρχαίες πόλεις της Ρόδου, μαζί με τη Λίνδο και την Ιαλυσό. Ο αρχαιολογικός χώρος διατηρεί καθαρή εικόνα της πολεοδομικής οργάνωσης, με κατοικίες, αγορά, ιερά και δημόσιους χώρους.', 'Από σημαντική πόλη της Ρόδου μετατράπηκε σε οργανωμένο αρχαιολογικό χώρο.', 'easy', 'Η πρόσβαση είναι εύκολη με όχημα από την πόλη της Ρόδου.', 'Ρόδος / Δωδεκάνησα', ARRAY['Ακρόπολη Λίνδου', 'Ακρόπολη Ρόδου', 'Βρουλιά']::text[], 'Πανοραμική άποψη της αρχαίας πόλης της Καμείρου.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_ancient_kameiros']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Kameiros,_ancient_city_ruins_-_Rhodes,_Greece_-_01.JPG'),
  (176, 'akropoli-rodoy', 'Ακρόπολη Ρόδου', ARRAY['Ακρόπολη', 'Ιερά', 'Στάδιο', 'Θέατρο']::text[], ARRAY['Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η ακρόπολη διαμορφώθηκε κυρίως στους ελληνιστικούς χρόνους.', 'Ελληνιστική-Ρωμαϊκή περίοδος', 'Η αρχαία χρήση σταμάτησε σταδιακά και ο χώρος ενσωματώθηκε στην εξέλιξη της πόλης.', 'Συνδέεται με την πόλη της Ρόδου, που ιδρύθηκε το 408/7 π.Χ.', 'Θρησκευτικό, δημόσιο και αθλητικό κέντρο της αρχαίας πόλης.', 'Η Ακρόπολη της Ρόδου, στην περιοχή Μόντε Σμιθ, ήταν σημαντικός δημόσιος και θρησκευτικός χώρος της αρχαίας πόλης. Περιλαμβάνει κατάλοιπα ναών, σταδίου και θεάτρου, δείχνοντας την οργανωμένη αστική ζωή της ελληνιστικής Ρόδου.', 'Από δημόσιος και θρησκευτικός χώρος της αρχαίας πόλης μετατράπηκε σε αστικό αρχαιολογικό πάρκο.', 'easy', 'Εύκολη πρόσβαση, καθώς βρίσκεται μέσα στη σύγχρονη πόλη της Ρόδου.', 'Ρόδος / Δωδεκάνησα', ARRAY['Αρχαία Κάμειρος', 'Ακρόπολη Λίνδου', 'Πόλη Ρόδου']::text[], 'Το αρχαίο στάδιο ή τα κατάλοιπα του ναού του Απόλλωνα.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Stadium_Rhodes.jpg'),
  (175, 'vroylia-rodoy', 'Βρουλιά Ρόδου', ARRAY['Οικισμός', 'Οχύρωση', 'Λιμάνι']::text[], ARRAY['Αρχαϊκή']::text[], 'Ο οικισμός χρονολογείται κυρίως στον 7ο-6ο αιώνα π.Χ.', 'Αρχαϊκή περίοδος', 'Ο οικισμός εγκαταλείφθηκε σχετικά νωρίς.', 'Δεν γνωρίζουμε κτήτορα· αποτελεί αρχαϊκό οικισμό της Ρόδου.', 'Παραθαλάσσιος οικισμός με στρατηγική και εμπορική σημασία.', 'Τα Βρουλιά στη νότια Ρόδο αποτελούν σημαντικό αρχαϊκό οικισμό. Η θέση τους κοντά στη θάλασσα και η οργανωμένη διάταξη του χώρου προσφέρουν στοιχεία για την πρώιμη πολεοδομία και τις θαλάσσιες επαφές της Ρόδου.', 'Μετά την εγκατάλειψη δεν εξελίχθηκε σε μεγάλη μεταγενέστερη πόλη.', 'medium', 'Η πρόσβαση είναι μέτρια λόγω της απομακρυσμένης θέσης στη νότια Ρόδο.', 'Ρόδος / Δωδεκάνησα', ARRAY['Λίνδος', 'Κάμειρος', 'Κυμισάλα']::text[], 'Ο αρχαϊκός οικισμός με το νότιο ροδιακό τοπίο.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], ''),
  (163, 'archaia-kymisala', 'Αρχαία Κυμισάλα', ARRAY['Νεκρόπολη', 'Οικισμός', 'Αρχαιολογικό τοπίο']::text[], ARRAY['Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η χρήση της περιοχής αναπτύχθηκε στους ιστορικούς χρόνους.', 'Κλασική-Ρωμαϊκή περίοδος', 'Η αρχαία χρήση μειώθηκε σταδιακά.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· συνδέεται με την αρχαία Ρόδο.', 'Οικιστική και ταφική χρήση στην αγροτική περιφέρεια της Ρόδου.', 'Η Κυμισάλα είναι σημαντικό αρχαιολογικό τοπίο της Ρόδου, γνωστό κυρίως για τη νεκρόπολη και τα διάσπαρτα κατάλοιπα της αρχαίας εγκατάστασης. Η περιοχή βοηθά να κατανοηθεί η ζωή έξω από τα μεγάλα αστικά κέντρα του νησιού.', 'Από αρχαία οικιστική και ταφική ζώνη μετατράπηκε σε αρχαιολογικό τοπίο.', 'medium', 'Η πρόσβαση είναι μέτρια και εξαρτάται από την ακριβή διαδρομή μέσα στο τοπίο.', 'Ρόδος / Δωδεκάνησα', ARRAY['Κάμειρος', 'Βρουλιά', 'Λίνδος']::text[], 'Η νεκρόπολη ή το αρχαιολογικό τοπίο της Κυμισάλας.', 'medium', true, 'Manual-review import: mapped cleaned monument "Αρχαία Κυμισάλα" to catalog_id 163 "Αρχαία Κυμισάλα Ρόδου/ Νεκρόπολη". Alternatives: 1: Κορυφη Αυγο Παγγαιο (0.000); 5: Πιθανή θέση της Ποικίλης Στοάς (0.000); 7: Μεγάλα Προπύλαια Ελευσίνας (0.000).', ARRAY['odysseus_arch_sites_general']::text[], ''),
  (117, 'ifaistia-limnoy', 'Ηφαιστία Λήμνου', ARRAY['Πόλη', 'Θέατρο', 'Ιερά']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η πόλη αναπτύχθηκε στους ιστορικούς χρόνους ως ένα από τα βασικά κέντρα της Λήμνου.', 'Αρχαϊκή-Ρωμαϊκή περίοδος', 'Η χρήση της μειώθηκε σταδιακά στους μεταγενέστερους χρόνους.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· ήταν μία από τις αρχαίες πόλεις της Λήμνου.', 'Αστικό και θρησκευτικό κέντρο της βόρειας Λήμνου.', 'Η Ηφαιστία ήταν μία από τις σημαντικότερες αρχαίες πόλεις της Λήμνου. Ο χώρος περιλαμβάνει θέατρο, ιερά και κατάλοιπα της πόλης, ενώ το όνομά της συνδέεται με τη λατρεία του Ηφαίστου και την ιδιαίτερη ταυτότητα του νησιού.', 'Από αρχαία πόλη μετατράπηκε σε αρχαιολογικό χώρο.', 'medium', 'Η πρόσβαση είναι σχετικά εύκολη με όχημα, αλλά ο χώρος βρίσκεται σε απομακρυσμένο τμήμα του νησιού.', 'Λήμνος / Βόρειο Αιγαίο', ARRAY['Πολιόχνη', 'Κουκονήσι', 'Καβείριο Λήμνου']::text[], 'Το αρχαίο θέατρο της Ηφαιστίας ή άποψη του αρχαιολογικού χώρου.', 'medium', true, 'Manual-review import: mapped cleaned monument "Ηφαιστία Λήμνου" to catalog_id 117 "Ηφαιστία". Alternatives: 159: Κουκονήσι Λήμνου (0.333); 1: Κορυφη Αυγο Παγγαιο (0.000); 5: Πιθανή θέση της Ποικίλης Στοάς (0.000).', ARRAY['odysseus_arch_sites_general']::text[], 'https://upload.wikimedia.org/wikipedia/commons/1/1d/Hephaistia_Ancient_Theatre_S3000132.jpeg'),
  (159, 'koykonisi-limnoy', 'Κουκονήσι Λήμνου', ARRAY['Προϊστορικός οικισμός', 'Νησίδα']::text[], ARRAY['Πρώιμη Εποχή Χαλκού', 'Μέση Εποχή Χαλκού', 'Ύστερη Εποχή Χαλκού']::text[], 'Ο οικισμός έχει προϊστορικές φάσεις κατοίκησης στην Εποχή του Χαλκού.', '3η-2η χιλιετία π.Χ.', 'Η προϊστορική χρήση εγκαταλείφθηκε σε μεταγενέστερη φάση.', 'Δεν γνωρίζουμε κτήτορα· αποτελεί προϊστορική εγκατάσταση της Λήμνου.', 'Κατοίκηση και θαλάσσιες επαφές στο βόρειο Αιγαίο.', 'Το Κουκονήσι είναι σημαντική προϊστορική θέση της Λήμνου. Η θέση του σε μικρή νησίδα δείχνει τον ρόλο των θαλάσσιων επαφών και της κατοίκησης στο βόρειο Αιγαίο κατά την Εποχή του Χαλκού.', 'Δεν εξελίχθηκε σε ιστορική πόλη· διατηρεί κυρίως προϊστορικό χαρακτήρα.', 'medium', 'Η πρόσβαση χρειάζεται τοπικό έλεγχο, καθώς πρόκειται για ειδική αρχαιολογική θέση.', 'Λήμνος / Προϊστορικό Βόρειο Αιγαίο', ARRAY['Πολιόχνη', 'Ηφαιστία', 'Μύρινα Λήμνου']::text[], 'Η νησίδα Κουκονήσι με το αρχαιολογικό τοπίο.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], 'https://upload.wikimedia.org/wikipedia/commons/3/31/Lemnos_2005_013.jpg'),
  (197, 'pythagoreio-samoy-archaia-poli-samoy', 'Πυθαγόρειο Σάμου / Αρχαία πόλη Σάμου', ARRAY['Πόλη', 'Λιμάνι', 'Τείχη', 'UNESCO']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η αρχαία πόλη της Σάμου αναπτύχθηκε ιδιαίτερα στην αρχαϊκή περίοδο.', 'Αρχαϊκή-Ρωμαϊκή περίοδος', 'Η χρήση της πόλης μετασχηματίστηκε στους μεταγενέστερους χρόνους.', 'Αναπτύχθηκε από την αρχαία Σάμο, με μεγάλη ακμή στην εποχή του Πολυκράτη.', 'Αστικό, ναυτικό και εμπορικό κέντρο του νησιού.', 'Το Πυθαγόρειο βρίσκεται στη θέση της αρχαίας πόλης της Σάμου. Η περιοχή συνδέεται με μεγάλο λιμάνι, τείχη, δημόσια έργα και το Ευπαλίνειο Όρυγμα, αποτελώντας ένα από τα σημαντικότερα κέντρα του ανατολικού Αιγαίου.', 'Από αρχαία πόλη και λιμάνι συνέχισε να ζει ως νεότερος οικισμός με αρχαιολογικά στρώματα.', 'easy', 'Εύκολη πρόσβαση, καθώς βρίσκεται μέσα στο σύγχρονο Πυθαγόρειο.', 'Σάμος / Ιωνικό Αιγαίο', ARRAY['Ευπαλίνειο Όρυγμα', 'Ηραίο Σάμου', 'Αρχαιολογικό Μουσείο Πυθαγορείου']::text[], 'Το λιμάνι και τα κατάλοιπα της αρχαίας πόλης ή τα τείχη.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_ancient_samos_pythagoreion']::text[], 'https://upload.wikimedia.org/wikipedia/commons/0/0e/SamosAntiqueFortificationWalls.jpg'),
  (160, 'emporeios-chioy', 'Εμπορειός Χίου', ARRAY['Οικισμός', 'Ακρόπολη', 'Προϊστορική-αρχαϊκή θέση']::text[], ARRAY['Πρώιμη Εποχή Χαλκού', 'Γεωμετρική', 'Αρχαϊκή']::text[], 'Η περιοχή έχει μακρά χρήση, με σημαντικές φάσεις από την προϊστορία έως την αρχαϊκή περίοδο.', '3η χιλιετία π.Χ. - Αρχαϊκή περίοδος', 'Η χρήση μεταβλήθηκε και ο χώρος εγκαταλείφθηκε σταδιακά.', 'Δεν γνωρίζουμε κτήτορα· αποτελεί σημαντικό οικιστικό κέντρο της Χίου.', 'Κατοίκηση, οχύρωση και έλεγχος παραθαλάσσιας περιοχής.', 'Ο Εμπορειός της Χίου είναι από τους σημαντικούς αρχαιολογικούς χώρους του ανατολικού Αιγαίου. Η θέση του παρουσιάζει διαδοχικές φάσεις κατοίκησης και δείχνει τη σημασία της Χίου στα θαλάσσια δίκτυα από την προϊστορία έως τους αρχαϊκούς χρόνους.', 'Από οικιστικό και οχυρωμένο κέντρο μετατράπηκε σε αρχαιολογικό χώρο.', 'medium', 'Η πρόσβαση είναι σχετικά εύκολη με όχημα, αλλά η ανάβαση στην ακρόπολη θέλει προσοχή.', 'Χίος / Βόρειο Αιγαίο', ARRAY['Αρχαία Χίος', 'Ανατολικό Αιγαίο', 'Πολιόχνη']::text[], 'Η ακρόπολη του Εμπορειού με θέα προς τη θάλασσα.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], 'https://upload.wikimedia.org/wikipedia/commons/2/26/Chios_-_Archaeological_site_of_Emporeios.jpg'),
  (132, 'palaia-alos', 'Παλαιά Άλος', ARRAY['Πόλη', 'Οχύρωση']::text[], ARRAY['Κλασική', 'Ελληνιστική']::text[], 'Η Παλαιά Άλος αναπτύχθηκε στους κλασικούς και ελληνιστικούς χρόνους.', 'Κλασική-Ελληνιστική περίοδος', 'Η πόλη μετασχηματίστηκε και συνδέεται με τη μετακίνηση/ίδρυση της Νέας Άλου.', 'Δεν είναι γνωστός συγκεκριμένος κτήτορας για την αρχική πόλη.', 'Αστικό και στρατηγικό κέντρο στην περιοχή του Αλμυρού.', 'Η Παλαιά Άλος ήταν σημαντική πόλη της νότιας Θεσσαλίας, κοντά σε περάσματα και σε περιοχή με στρατηγική σημασία. Τα κατάλοιπα της οχύρωσης και της πόλης δείχνουν τη σημασία της στον έλεγχο της περιοχής.', 'Η πόλη συνδέεται με μεταβολές και μεταφορά του αστικού κέντρου στη Νέα Άλο.', 'medium', 'Η πρόσβαση είναι σχετικά εύκολη με όχημα, αλλά χρειάζεται επιβεβαίωση του ακριβούς σημείου.', 'Αχαΐα Φθιώτιδα / Θεσσαλία', ARRAY['Νέα Άλος', 'Διμήνι', 'Σέσκλο']::text[], 'Η οχύρωση ή γενική άποψη της αρχαίας θέσης.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['odysseus_arch_sites_general']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/K01_211_Stadttor_Alos.jpg'),
  (133, 'nea-alos', 'Νέα Άλος', ARRAY['Πόλη', 'Οχύρωση', 'Ελληνιστικό κέντρο']::text[], ARRAY['Ελληνιστική']::text[], 'Η Νέα Άλος ιδρύθηκε ή οργανώθηκε στα ελληνιστικά χρόνια.', '3ος-2ος αιώνας π.Χ.', 'Η χρήση της μειώθηκε στους μεταγενέστερους χρόνους.', 'Συνδέεται με την αναδιοργάνωση της περιοχής στην ελληνιστική περίοδο.', 'Νέο αστικό και στρατηγικό κέντρο στην περιοχή του Αλμυρού.', 'Η Νέα Άλος είναι σημαντική ελληνιστική πόλη της Θεσσαλίας. Η οργανωμένη πολεοδομία και η οχύρωση της περιοχής δείχνουν σχεδιασμένη πόλη με στρατηγική σημασία κοντά στον Παγασητικό και στα περάσματα της νότιας Θεσσαλίας.', 'Από ελληνιστική πόλη μετατράπηκε σε αρχαιολογική θέση.', 'medium', 'Η πρόσβαση είναι σχετικά εύκολη, αλλά ο χώρος χρειάζεται επιτόπιο έλεγχο για την καλύτερη διαδρομή.', 'Θεσσαλία / Περιοχή Αλμυρού', ARRAY['Παλαιά Άλος', 'Σέσκλο', 'Διμήνι']::text[], 'Άποψη των τειχών ή της πολεοδομίας της Νέας Άλου.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['odysseus_arch_sites_general']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/K01_212_Alos,_Stadttor_(au%C3%9Fen).jpg'),
  (85, 'stroggylovoyni-karditsas', 'Στρογγυλοβούνι Καρδίτσας', ARRAY['Οχύρωση', 'Αρχαία πόλη', 'Ακρόπολη']::text[], ARRAY['Κλασική', 'Ελληνιστική']::text[], 'Η οχύρωση και η χρήση της θέσης αναπτύχθηκαν κυρίως στους κλασικούς και ελληνιστικούς χρόνους.', 'Κλασική-Ελληνιστική περίοδος', 'Η χρήση μειώθηκε στους μεταγενέστερους χρόνους.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· συνδέεται με την αρχαία Θεσσαλία.', 'Έλεγχος στρατηγικού υψώματος και της τοπικής ενδοχώρας.', 'Το Στρογγυλοβούνι είναι αρχαία οχυρωμένη θέση της Καρδίτσας. Η θέση σε ύψωμα και τα κατάλοιπα οχύρωσης δείχνουν τη στρατηγική σημασία της για τον έλεγχο της περιοχής.', 'Από οχυρωμένη αρχαία θέση μετατράπηκε σε αρχαιολογικό τοπίο.', 'medium', 'Η πρόσβαση πιθανότατα είναι μέτρια και θέλει έλεγχο της τοπικής διαδρομής.', 'Θεσσαλία', ARRAY['Θεόπετρα', 'Σέσκλο', 'Διμήνι']::text[], 'Η κορυφή/οχύρωση του Στρογγυλοβουνίου.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['odysseus_arch_sites_general']::text[], ''),
  (230, 'spilaio-kyklopa-gioyras', 'Σπήλαιο Κύκλωπα Γιούρας', ARRAY['Σπήλαιο', 'Προϊστορική θέση']::text[], ARRAY['Μεσολιθική', 'Νεολιθική', 'Εποχή Χαλκού']::text[], 'Το σπήλαιο παρουσιάζει πολύ παλαιές φάσεις ανθρώπινης παρουσίας από τη Μεσολιθική και τη Νεολιθική περίοδο.', 'Προϊστορική περίοδος', 'Η χρήση του σπηλαίου μεταβλήθηκε μέσα στους αιώνες.', 'Δεν έχει κτήτορα· είναι φυσικό σπήλαιο που χρησιμοποιήθηκε από προϊστορικές κοινότητες.', 'Καταφύγιο, κατοίκηση ή εποχική χρήση και τεκμήριο πρώιμης παρουσίας στο Αιγαίο.', 'Το Σπήλαιο του Κύκλωπα στα Γιούρα είναι σημαντική προϊστορική θέση των Βόρειων Σποράδων. Συνδέεται με πολύ πρώιμες φάσεις ανθρώπινης παρουσίας στο Αιγαίο και έχει ιδιαίτερη αξία για την κατανόηση της νησιωτικής προϊστορίας.', 'Η χρήση του άλλαξε από φυσικό καταφύγιο/προϊστορική θέση σε αρχαιολογικό και φυσικό σημείο ενδιαφέροντος.', 'hard', 'Η πρόσβαση είναι δύσκολη, καθώς απαιτεί θαλάσσια προσέγγιση και ειδικές συνθήκες.', 'Βόρειες Σποράδες / Προϊστορικό Αιγαίο', ARRAY['Θεόπετρα', 'Σέσκλο', 'Νησιωτικές προϊστορικές θέσεις']::text[], 'Η είσοδος του σπηλαίου ή το άγριο τοπίο των Γιούρων.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], ''),
  (66, 'hadrianic-aqueduct-athens', 'Αδριάνειο Υδραγωγείο', ARRAY['Υδραγωγείο', 'Ρωμαϊκό τεχνικό έργο']::text[], ARRAY['Ρωμαϊκή']::text[], '2ος αιώνας μ.Χ.· η κατασκευή άρχισε επί Αδριανού και ολοκληρώθηκε επί Αντωνίνου Ευσεβούς.', '2ος αιώνας μ.Χ. - νεότεροι χρόνοι', 'Δεν πρόκειται για μνημείο που καταστράφηκε σε μία φάση· τμήματα του έργου διατηρήθηκαν και η χρήση/λειτουργία του μεταβλήθηκε μέσα στους αιώνες.', 'Ξεκίνησε από τον αυτοκράτορα Αδριανό και ολοκληρώθηκε από τον Αντωνίνο Ευσεβή.', 'Ύδρευση της Αθήνας μέσω υπόγειας υδραυλικής σήραγγας και δικτύου φρεατίων.', 'Το Αδριάνειο Υδραγωγείο είναι ένα από τα σημαντικότερα ρωμαϊκά τεχνικά έργα της Αθήνας. Αποτελούνταν κυρίως από υπόγεια σήραγγα και σειρά φρεατίων, με σκοπό τη μεταφορά νερού προς την πόλη. Η σημασία του βρίσκεται όχι μόνο στην αρχαιότητα, αλλά και στη μακρά διάρκεια ζωής του ως υδραυλικό έργο.', 'Από ρωμαϊκό έργο ύδρευσης μετατράπηκε σε ιστορικό τεχνικό μνημείο και αντικείμενο σύγχρονων έργων ανάδειξης/διαχείρισης νερού.', 'medium', 'Δεν είναι ένας ενιαίος εύκολα επισκέψιμος αρχαιολογικός χώρος· ορατά τμήματα και φρεάτια βρίσκονται σε διάφορα σημεία της Αθήνας.', 'Ρωμαϊκή Αθήνα', ARRAY['Ρωμαϊκή Αθήνα', 'Δεξαμενή Κολωνακίου', 'Αχαρνές / Ολυμπιακό Χωριό']::text[], 'Ορατό φρέαρ ή τμήμα του Αδριάνειου Υδραγωγείου με αστικό φόντο.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['efada_hadrianic_aqueduct']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Hadrianic_aqueduct,_Remains_of_water_bridge_in_Nea_Ionia,_Athens_(14046482411).jpg'),
  (191, 'thorikos-theatre', 'Θέατρο Θορικού', ARRAY['Θέατρο', 'Αρχαία πόλη', 'Μεταλλευτική περιοχή']::text[], ARRAY['Γεωμετρική', 'Αρχαϊκή', 'Κλασική', 'Ελληνιστική']::text[], 'Ο χώρος έχει πολύ παλιά χρήση· το θέατρο συνδέεται κυρίως με τους αρχαϊκούς και κλασικούς χρόνους.', 'Αρχαϊκή - Κλασική περίοδος', 'Η χρήση του χώρου μειώθηκε σταδιακά στους μεταγενέστερους χρόνους.', 'Δεν είναι γνωστός συγκεκριμένος κτήτορας· συνδέεται με την τοπική κοινότητα του Θορικού και την Αττική.', 'Χώρος συγκέντρωσης, θεάτρου και δημόσιας ζωής της αρχαίας κοινότητας του Θορικού.', 'Ο Θορικός είναι σημαντικός αρχαιολογικός χώρος της Λαυρεωτικής, σε περιοχή στενά συνδεδεμένη με τα μεταλλεία αργύρου. Το αρχαίο θέατρο ξεχωρίζει για το ιδιαίτερο, μη τυπικά ημικυκλικό σχήμα του και αποτελεί ένα από τα πιο χαρακτηριστικά μνημεία της περιοχής.', 'Από χώρο δημόσιας ζωής της αρχαίας κοινότητας μετατράπηκε σε αρχαιολογικό τοπόσημο της Λαυρεωτικής.', 'medium', 'Η πρόσβαση γίνεται με όχημα προς τη Λαυρεωτική και μετά με σύντομη πεζή κίνηση στον χώρο.', 'Θορικός / Αττική', ARRAY['Μεταλλεία Λαυρίου', 'Λόφος Βελατούρι', 'Σούνιο']::text[], 'Το κοίλο του θεάτρου με το τοπίο της Λαυρεωτικής.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_thorikos']::text[], 'https://upload.wikimedia.org/wikipedia/commons/5/57/%CE%98%CE%BF%CF%81%CE%B9%CE%BA%CF%8C%CF%82_7168.jpg'),
  (73, 'euripides-cave-salamis', 'Σπήλαιο Ευριπίδη', ARRAY['Σπήλαιο', 'Ιστορική τοποθεσία']::text[], ARRAY['Κλασική', 'Ρωμαϊκή', 'Νεότερη έρευνα']::text[], 'Δεν έχει κτήτορα· πρόκειται για φυσικό σπήλαιο με αρχαιολογική και φιλολογική σύνδεση.', 'Αρχαιότητα - νεότερη αρχαιολογική έρευνα', 'Δεν υπάρχει ενιαία φάση καταστροφής· το σπήλαιο παραμένει φυσικός και αρχαιολογικός χώρος.', 'Δεν χτίστηκε· είναι φυσικό σπήλαιο.', 'Συνδέεται παραδοσιακά με τον τραγικό ποιητή Ευριπίδη και με χρήση/παρουσία στην αρχαιότητα.', 'Το Σπήλαιο Ευριπίδη βρίσκεται στη νότια Σαλαμίνα, πάνω από τον όρμο Περιστέρια. Η παράδοση το συνδέει με τον Ευριπίδη και η ιδιαίτερη μορφολογία του το κάνει ένα από τα πιο ξεχωριστά σημεία του νησιού. Δεν είναι τυπικό οικοδόμημα, αλλά φυσικός χώρος με ιστορική και αρχαιολογική αξία.', 'Από φυσικό καταφύγιο/χώρο χρήσης έγινε σημείο ιστορικού ενδιαφέροντος και αρχαιολογικής έρευνας.', 'medium', 'Η πρόσβαση απαιτεί μετάβαση στη νότια Σαλαμίνα και περπάτημα σε μονοπάτι.', 'Σαλαμίνα / Αττική', ARRAY['Αρχαία Σαλαμίνα', 'Κολώνες Σαλαμίνας', 'Ναυμαχία Σαλαμίνας']::text[], 'Η είσοδος του σπηλαίου ή η θέα προς τον όρμο Περιστέρια.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_euripides_cave', 'municipality_salamis_euripides_cave']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/The_famous_Cave_of_Euripides_on_Salamis_island,_Greece.jpg'),
  (65, 'didyma-apollo-temple', 'Ναός Απόλλωνα στα Δίδυμα', ARRAY['Ναός', 'Ιερό', 'Μαντείο']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Το ιερό έχει παλαιότερες φάσεις, ενώ ο μεγάλος ελληνιστικός ναός άρχισε να οικοδομείται μετά τον 4ο αιώνα π.Χ.', 'Αρχαϊκή περίοδος - Ρωμαϊκή περίοδος', 'Το ιερό έχασε τη λειτουργία του σταδιακά μετά την ύστερη αρχαιότητα.', 'Συνδέεται με τη Μίλητο και το ιωνικό περιβάλλον· δεν αποδίδεται σε έναν μόνο κτήτορα.', 'Λατρεία του Απόλλωνα και λειτουργία σημαντικού μαντείου της Ιωνίας.', 'Τα Δίδυμα ήταν ένα από τα σημαντικότερα ιερά και μαντεία του Απόλλωνα στον ιωνικό κόσμο. Το ιερό δεν ήταν αυτόνομη πόλη, αλλά ιερός χώρος συνδεδεμένος με τη Μίλητο μέσω Ιεράς Οδού. Ο τεράστιος ναός του Απόλλωνα είναι ένα από τα πιο εντυπωσιακά ελληνιστικά μνημεία της Μικράς Ασίας.', 'Από ενεργό μαντείο και ιερό μετατράπηκε σε αρχαιολογικό χώρο της σημερινής Τουρκίας.', 'easy', 'Εύκολη πρόσβαση από τη σύγχρονη πόλη Didim, αλλά βρίσκεται εκτός Ελλάδας.', 'Ιωνία / Μίλητος', ARRAY['Μίλητος', 'Ιερά Οδός Μιλήτου-Διδύμων', 'Ιωνικά ιερά']::text[], 'Οι τεράστιοι κίονες και το εσωτερικό του ναού του Απόλλωνα.', 'high', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['turkish_museums_didyma_apollo', 'worldhistory_didyma']::text[], 'https://upload.wikimedia.org/wikipedia/commons/5/54/Didymaion_front_AvL.JPG'),
  (196, 'heraion-samos', 'Ηραίο Σάμου', ARRAY['Ιερό', 'Ναός', 'UNESCO']::text[], ARRAY['Γεωμετρική', 'Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Το ιερό έχει πολύ παλαιά λατρευτική χρήση, ενώ ο μεγάλος ναός της Ήρας αναπτύχθηκε ιδιαίτερα στην αρχαϊκή περίοδο.', 'Αρχαϊκή - Ρωμαϊκή περίοδος', 'Η αρχαία λατρεία σταμάτησε σταδιακά στην ύστερη αρχαιότητα.', 'Αναπτύχθηκε από τη σαμιακή πόλη και τους τοπικούς φορείς λατρείας.', 'Λατρεία της Ήρας και λειτουργία ενός από τα σημαντικότερα ιερά του Αιγαίου.', 'Το Ηραίο της Σάμου είναι ένα από τα σημαντικότερα ιερά της αρχαιότητας και μαζί με το Πυθαγόρειο ανήκει στα μνημεία παγκόσμιας κληρονομιάς της UNESCO. Βρισκόταν σε άμεση σχέση με την αρχαία πόλη της Σάμου και συνδεόταν μαζί της μέσω Ιεράς Οδού.', 'Από μεγάλο ιερό της Ήρας έγινε αρχαιολογικός χώρος διεθνούς σημασίας.', 'easy', 'Εύκολη πρόσβαση με όχημα από το Πυθαγόρειο και τα νότια της Σάμου.', 'Αρχαία Σάμος', ARRAY['Πυθαγόρειο Σάμου', 'Ιερά Οδός', 'Ευπαλίνειο Όρυγμα']::text[], 'Ο μοναχικός κίονας και τα κατάλοιπα του μεγάλου ναού της Ήρας.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['unesco_pythagoreion_heraion_samos', 'greek_unesco_samos']::text[], 'https://upload.wikimedia.org/wikipedia/commons/1/10/Heraion_of_Samos_2.jpg'),
  (187, 'dispilio-lake-settlement', 'Νεολιθικός Λιμναίος Οικισμός Δισπηλιού', ARRAY['Νεολιθικός οικισμός', 'Λιμναίος οικισμός', 'Ανοιχτό μουσείο']::text[], ARRAY['Νεολιθική']::text[], 'Προϊστορικός οικισμός, περίπου 7.500 χρόνια πριν από σήμερα σύμφωνα με την παρουσίαση του ανοιχτού μουσείου.', 'Νεολιθική περίοδος', 'Ο οικισμός εγκαταλείφθηκε στην προϊστορία· σήμερα έχει αναπαρασταθεί τμήμα του ως ανοιχτό μουσείο.', 'Προϊστορικές νεολιθικές κοινότητες της περιοχής της Καστοριάς.', 'Κατοίκηση δίπλα στη λίμνη, με οικονομικές δραστηριότητες σχετικές με το νερό, την καλλιέργεια, την κτηνοτροφία και την καθημερινή ζωή.', 'Το Δισπηλιό είναι σημαντικός νεολιθικός λιμναίος οικισμός στη νότια όχθη της λίμνης της Καστοριάς. Η αναπαράσταση του οικισμού βοηθά τον επισκέπτη να καταλάβει πώς μπορούσε να είναι ένα προϊστορικό χωριό δίπλα στη λίμνη.', 'Από προϊστορικός οικισμός έγινε αρχαιολογική θέση και ανοιχτό μουσείο.', 'easy', 'Εύκολη πρόσβαση με όχημα, λίγα χιλιόμετρα έξω από την Καστοριά.', 'Προϊστορική Δυτική Μακεδονία', ARRAY['Λίμνη Ορεστιάδα', 'Αρχαιολογικό Μουσείο Καστοριάς', 'Νεολιθικές θέσεις Βόρειας Ελλάδας']::text[], 'Οι αναπαραστημένες καλύβες του λιμναίου οικισμού δίπλα στη λίμνη.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['dispilio_open_museum']::text[], 'https://upload.wikimedia.org/wikipedia/commons/b/bd/78_GR1320001_SCI_LAKE_ORESTIAS_04_KASTORIA_%28By_TRYFON_MANOLIS_THESSALONIKI_HELLAS%29.jpg'),
  (207, 'dikili-tash', 'Dikili Tash / Ορθόπετρα Κρηνίδων', ARRAY['Προϊστορικός οικισμός', 'Τούμπα', 'Νεολιθική θέση']::text[], ARRAY['Νεολιθική', 'Εποχή Χαλκού']::text[], 'Η θέση κατοικήθηκε ήδη από τη Νεολιθική περίοδο.', 'Νεολιθική περίοδος - Εποχή Χαλκού', 'Η θέση έχει διαδοχικές φάσεις κατοίκησης και εγκατάλειψης.', 'Προϊστορικές κοινότητες της ανατολικής Μακεδονίας.', 'Κατοίκηση, παραγωγή και καθημερινή ζωή σε νεολιθικό και προϊστορικό περιβάλλον.', 'Το Dikili Tash, κοντά στις Κρηνίδες και τους Φιλίππους, είναι μία από τις σημαντικές προϊστορικές θέσεις της ανατολικής Μακεδονίας. Η θέση βοηθά στην κατανόηση των νεολιθικών κοινοτήτων της περιοχής, πριν από την ανάπτυξη των ιστορικών πόλεων.', 'Από προϊστορικός οικισμός μετατράπηκε σε αρχαιολογική θέση έρευνας.', 'medium', 'Η θέση βρίσκεται κοντά σε γνωστούς αρχαιολογικούς χώρους, αλλά η επίσκεψη μπορεί να απαιτεί ειδική πληροφόρηση για την κατάσταση πρόσβασης.', 'Προϊστορική Ανατολική Μακεδονία', ARRAY['Φίλιπποι', 'Κρηνίδες', 'Παγγαίο']::text[], 'Η τούμπα/αρχαιολογικό τοπίο του Dikili Tash κοντά στις Κρηνίδες.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['archaeological_cadastre_dikili_tash', 'odysseus_arch_sites_general']::text[], 'https://upload.wikimedia.org/wikipedia/commons/c/c0/Dikili_Tash_1.JPG'),
  (20, 'ancient-argilos', 'Αρχαία Άργιλος', ARRAY['Πόλη', 'Αποικία', 'Παράκτια θέση']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική']::text[], 'Ιδρύθηκε τον 7ο αιώνα π.Χ., σύμφωνα με τις διαθέσιμες παρουσιάσεις της περιοχής.', '7ος αιώνας π.Χ. - Ελληνιστική περίοδος', 'Η σημασία της μειώθηκε μετά την άνοδο της Αμφίπολης και τις μεταβολές της περιοχής.', 'Ιδρύθηκε από αποίκους από την Άνδρο.', 'Εμπορική και αποικιακή εγκατάσταση κοντά στις εκβολές του Στρυμόνα.', 'Η Αρχαία Άργιλος ήταν αποικία στο χώρο των εκβολών του Στρυμόνα, κοντά στην Αμφίπολη. Η θέση της την έκανε σημαντική για το εμπόριο και τις επαφές ανάμεσα στο Αιγαίο, τη Μακεδονία και την ενδοχώρα.', 'Από ενεργή αποικιακή πόλη έγινε αρχαιολογικός χώρος.', 'medium', 'Η πρόσβαση γίνεται με όχημα στην περιοχή της Αμφίπολης/Στρυμόνα· η κατάσταση επίσκεψης χρειάζεται έλεγχο πριν την αναχώρηση.', 'Αποικία Ανδρίων / Περιοχή Στρυμόνα', ARRAY['Αμφίπολη', 'Στρυμόνας', 'Παγγαίο']::text[], 'Ο λόφος και τα κατάλοιπα της αρχαίας Άργιλου με το τοπίο του Στρυμόνα.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['visit_central_macedonia_argilos', 'tovima_argilos']::text[], 'https://upload.wikimedia.org/wikipedia/commons/d/d7/Munkozani.jpg'),
  (70, 'crypt-agios-demetrios-thessaloniki', 'Κρύπτη Αγίου Δημητρίου', ARRAY['Κρύπτη', 'Παλαιοχριστιανικό μνημείο', 'Βυζαντινό μνημείο']::text[], ARRAY['Ρωμαϊκή', 'Παλαιοχριστιανική', 'Βυζαντινή']::text[], 'Η κρύπτη συνδέεται με τις παλαιοχριστιανικές και μεταγενέστερες φάσεις της βασιλικής του Αγίου Δημητρίου.', 'Παλαιοχριστιανική - Βυζαντινή περίοδος', 'Η χρήση της άλλαξε με τις φάσεις του ναού και σήμερα λειτουργεί ως επισκέψιμος αρχαιολογικός/μουσειακός χώρος.', 'Συνδέεται με την οικοδόμηση και τις φάσεις της βασιλικής του Αγίου Δημητρίου, όχι με έναν μόνο κτήτορα.', 'Λατρευτικός και μνημειακός χώρος συνδεδεμένος με τον Άγιο Δημήτριο και την ιστορία της Θεσσαλονίκης.', 'Η Κρύπτη του Αγίου Δημητρίου βρίσκεται κάτω από τη βασιλική του πολιούχου της Θεσσαλονίκης. Είναι άρρηκτα συνδεδεμένη με τη λατρεία του Αγίου Δημητρίου και την ιστορία του ναού, ενώ σήμερα φιλοξενεί έκθεση με βυζαντινά γλυπτά, επιγραφές και άλλα ευρήματα.', 'Από υπόγειος λατρευτικός/μνημειακός χώρος μετατράπηκε σε επισκέψιμη έκθεση και αρχαιολογικό χώρο.', 'easy', 'Εύκολη πρόσβαση στο κέντρο της Θεσσαλονίκης, μέσα στον ναό του Αγίου Δημητρίου.', 'Θεσσαλονίκη / Ρωμαϊκή και βυζαντινή πόλη', ARRAY['Βασιλική Αγίου Δημητρίου', 'Ρωμαϊκή Αγορά Θεσσαλονίκης', 'Γαλεριανό Συγκρότημα']::text[], 'Ο εσωτερικός χώρος της κρύπτης με τους θόλους και τα εκθέματα.', 'high', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['archaeological_museums_crypt_agios_demetrios', 'odysseus_crypt_agios_demetrios']::text[], ''),
  (71, 'macedonian-tomb-lagadas', 'Μακεδονικός Τάφος Λαγκαδά', ARRAY['Τάφος', 'Μακεδονικός τάφος']::text[], ARRAY['Ελληνιστική']::text[], 'Ελληνιστική περίοδος.', 'Ελληνιστική περίοδος', 'Η ταφική χρήση έπαψε μετά την αρχαιότητα· σήμερα αποτελεί αρχαιολογικό μνημείο.', 'Δεν είναι γνωστός ο κτήτορας· συνδέεται με την τοπική μακεδονική ελίτ.', 'Ταφικό μνημείο για μέλος ισχυρής οικογένειας ή τοπικής αριστοκρατίας.', 'Ο Μακεδονικός Τάφος Λαγκαδά είναι χαρακτηριστικό ταφικό μνημείο της μακεδονικής παράδοσης. Παρότι δεν είναι τόσο γνωστός όσο οι βασιλικοί τάφοι της Βεργίνας, είναι χρήσιμος για να παρουσιαστεί η διάδοση του τύπου των μακεδονικών τάφων στην ευρύτερη περιοχή της Θεσσαλονίκης.', 'Από ταφικό μνημείο μετατράπηκε σε προστατευόμενο αρχαιολογικό σημείο.', 'medium', 'Η πρόσβαση χρειάζεται επιβεβαίωση ανάλογα με το καθεστώς επίσκεψης του μνημείου.', 'Μακεδονία / Περιοχή Λαγκαδά', ARRAY['Θεσσαλονίκη', 'Μακεδονικοί τάφοι Ημαθίας', 'Μακεδονικοί τάφοι Μίεζας']::text[], 'Η πρόσοψη ή το εσωτερικό του μακεδονικού τάφου, αν υπάρχει διαθέσιμη νόμιμη εικόνα.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], ''),
  (182, 'ancient-mende', 'Αρχαία Μένδη', ARRAY['Πόλη', 'Αποικία', 'Εμπορικό κέντρο']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική']::text[], 'Ιδρύθηκε από Ερετριείς, πιθανότατα στον 8ο αιώνα π.Χ.', 'Αρχαϊκή - Κλασική περίοδος', 'Η πόλη έχασε σταδιακά τη σημασία της στους μεταγενέστερους χρόνους.', 'Ερετριείς άποικοι.', 'Αποικιακή και εμπορική εγκατάσταση στη χερσόνησο της Παλλήνης/Κασσάνδρας.', 'Η Αρχαία Μένδη ήταν μία από τις σημαντικές πόλεις της Χαλκιδικής. Γνώρισε οικονομική άνθηση χάρη στη θέση της, στο εμπόριο, στην ξυλεία και ιδιαίτερα στην παραγωγή του φημισμένου Μενδαίου οίνου. Συνδέεται επίσης με τον γλύπτη Παιώνιο.', 'Από ακμαία αποικιακή πόλη έγινε αρχαιολογικός χώρος.', 'medium', 'Η πρόσβαση γίνεται από την περιοχή Καλάνδρας/Κασσάνδρας, αλλά η επισκεψιμότητα πρέπει να ελέγχεται πριν την επίσκεψη.', 'Ερετριακή αποικία / Χαλκιδική', ARRAY['Ποτίδαια', 'Όλυνθος', 'Σκιώνη', 'Κασσάνδρα']::text[], 'Ο αρχαιολογικός λόφος της Μένδης με θέα προς τη θάλασσα.', 'high', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['efa_chalkidiki_mende', 'odysseus_mende']::text[], 'https://upload.wikimedia.org/wikipedia/commons/9/90/MACEDON%2C_Mende._Circa_510-480_BC.jpg'),
  (179, 'ancient-potidaea', 'Αρχαία Ποτίδαια', ARRAY['Πόλη', 'Αποικία', 'Οχύρωση', 'Λιμάνι']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Περίπου 600 π.Χ.', 'Αρχαϊκή - Ελληνιστική περίοδος', 'Η πόλη γνώρισε πολιορκίες και μεταβολές, ενώ η χρήση της περιοχής συνεχίστηκε σε διάφορες φάσεις.', 'Κορίνθιοι άποικοι.', 'Στρατηγική αποικιακή πόλη στον ισθμό της Παλλήνης/Κασσάνδρας, με έλεγχο θαλάσσιων και χερσαίων περασμάτων.', 'Η Αρχαία Ποτίδαια βρισκόταν στον ισθμό της Κασσάνδρας και ιδρύθηκε από Κορίνθιους αποίκους. Η θέση της την έκανε σημαντική πόλη-λιμάνι και στρατηγικό σημείο της Χαλκιδικής. Έπαιξε ρόλο στους Περσικούς πολέμους και στα γεγονότα πριν από τον Πελοποννησιακό Πόλεμο.', 'Από αρχαία αποικία και πόλη-λιμάνι μετατράπηκε σε περιοχή με κατάλοιπα διαφορετικών εποχών.', 'easy', 'Εύκολη πρόσβαση από τη Νέα Ποτίδαια, αλλά τα σωζόμενα αρχαία κατάλοιπα είναι διάσπαρτα.', 'Κορινθιακή αποικία / Χαλκιδική', ARRAY['Μένδη', 'Όλυνθος', 'Κασσάνδρα', 'Διώρυγα Ποτίδαιας']::text[], 'Τμήμα τείχους ή γενική άποψη της Νέας Ποτίδαιας με την αρχαία θέση.', 'high', true, 'Manual-review import: mapped cleaned monument "Αρχαία Ποτίδαια" to catalog_id 179 "Κασσάνδρεια / Αρχαία Ποτίδαια". Alternatives: 72: [χωρίς όνομα] (0.037); 1: Κορυφη Αυγο Παγγαιο (0.000); 5: Πιθανή θέση της Ποικίλης Στοάς (0.000).', ARRAY['odysseus_potidaea', 'visit_central_macedonia_potidaea']::text[], 'https://upload.wikimedia.org/wikipedia/commons/2/25/Chalcidice.jpg'),
  (127, 'ancient-praisos', 'Αρχαία Πραισός', ARRAY['Πόλη', 'Ακρόπολη', 'Ετεοκρητική θέση']::text[], ARRAY['Γεωμετρική', 'Αρχαϊκή', 'Κλασική', 'Ελληνιστική']::text[], 'Η πόλη έχει παλαιότερες φάσεις και αναπτύχθηκε ιδιαίτερα στους ιστορικούς χρόνους.', 'Αρχαϊκή - Ελληνιστική περίοδος', 'Η πόλη εγκαταλείφθηκε/καταστράφηκε στους ελληνιστικούς χρόνους μετά από συγκρούσεις στην ανατολική Κρήτη.', 'Συνδέεται με τους Ετεοκρήτες και τις κοινότητες της ανατολικής Κρήτης.', 'Αστικό και πολιτικό κέντρο της ανατολικής Κρήτης.', 'Η Αρχαία Πραισός ήταν σημαντική πόλη της ανατολικής Κρήτης και συνδέεται με τους Ετεοκρήτες, τον παλαιό αυτόχθονα πληθυσμό του νησιού. Η πόλη εκτεινόταν σε τρεις ακροπόλεις και είχε πρόσβαση σε λιμάνια της περιοχής.', 'Από αρχαία πόλη μετατράπηκε σε αρχαιολογικό τοπίο με διάσπαρτα κατάλοιπα.', 'medium', 'Η πρόσβαση γίνεται από την περιοχή Σητείας, αλλά ο χώρος χρειάζεται προσοχή και βασικό περπάτημα.', 'Πραισός / Ανατολική Κρήτη', ARRAY['Ίτανος', 'Δρήρος', 'Λατώ', 'Ζάκρος']::text[], 'Το τοπίο των ακροπόλεων της Πραισού με τα σωζόμενα κατάλοιπα.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['unesco_sites_crete_praisos', 'archaeological_cadastre_praisos']::text[], ''),
  (119, 'ancient-itanos', 'Ίτανος / Ερημούπολη', ARRAY['Πόλη', 'Λιμάνι', 'Παράκτιος αρχαιολογικός χώρος']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η ίδρυση της πόλης τοποθετείται στους προϊστορικούς/πρώιμους χρόνους, με ισχυρή παρουσία στους ιστορικούς χρόνους.', 'Αρχαϊκή - Ρωμαϊκή περίοδος', 'Η πόλη έχασε σταδιακά τη σημασία της μετά την αρχαιότητα.', 'Δεν γνωρίζουμε συγκεκριμένο κτήτορα· αναπτύχθηκε ως πόλη της ανατολικής Κρήτης.', 'Παράκτιο εμπορικό και πολιτικό κέντρο της ανατολικής Κρήτης.', 'Η Ίτανος βρισκόταν στην Ερημούπολη, κοντά στο φοινικόδασος του Βάι. Ήταν ισχυρή πόλη της ανατολικής Κρήτης, με εμπορικές δραστηριότητες και επαφές προς την Ανατολή. Η παράκτια θέση της την κάνει πολύ χαρακτηριστική για αρχαιολογική καρτέλα με έντονο τοπίο.', 'Από αρχαία παράκτια πόλη έγινε αρχαιολογικός χώρος και σημείο ιστορικού ενδιαφέροντος κοντά στο Βάι.', 'easy', 'Σχετικά εύκολη πρόσβαση με όχημα προς το Βάι/Ερημούπολη, με περπάτημα στον χώρο.', 'Ίτανος / Ανατολική Κρήτη', ARRAY['Βάι', 'Πραισός', 'Ζάκρος', 'Παλαίκαστρο']::text[], 'Τα ερείπια της Ιτάνου δίπλα στη θάλασσα.', 'medium', true, 'Manual-review import: mapped cleaned monument "Ίτανος / Ερημούπολη" to catalog_id 119 "Ερημούπολη". Alternatives: 208: Μινωική έπαυλη Αχλαδιών (0.044); 209: Χαμαίζι (0.044); 232: Βρόκαστρο Λασιθίου (0.044).', ARRAY['unesco_sites_crete_itanos', 'cretanbeaches_itanos']::text[], 'https://upload.wikimedia.org/wikipedia/commons/b/b7/%D0%92%D0%B8%D0%B4_%D0%BD%D0%B0_%D0%BC%D0%BE%D0%BD%D0%B0%D1%81%D1%82%D1%8B%D1%80%D1%8C_%D1%81%D0%BE_%D1%81%D1%82%D0%BE%D1%8F%D0%BD%D0%BA%D0%B8._Toplou._Lasithi._Crete._Greece._%D0%90%D0%B2%D0%B3%D1%83%D1%81%D1%82_2013_-_panoramio.jpg'),
  (89, 'azorias-kavousi', 'Αζοριάς / Καβούσι', ARRAY['Οικισμός', 'Αρχαϊκή πόλη', 'Προϊστορική θέση']::text[], ARRAY['Νεολιθική', 'Εποχή Χαλκού', 'Γεωμετρική', 'Αρχαϊκή']::text[], 'Η θέση παρουσιάζει διαχρονική κατοίκηση, με ιδιαίτερη σημασία στην αρχαϊκή περίοδο.', 'Προϊστορικοί χρόνοι - 5ος αιώνας π.Χ.', 'Η αρχαϊκή πόλη φαίνεται να καταστράφηκε από φωτιά τον 5ο αιώνα π.Χ.', 'Κοινότητες της περιοχής Καβουσίου και της ανατολικής Κρήτης.', 'Οικισμός και οργανωμένη αρχαϊκή κοινότητα με δημόσιους/κοινοτικούς χώρους.', 'Ο Αζοριάς, κοντά στο Καβούσι, είναι σημαντική αρχαιολογική θέση της ανατολικής Κρήτης. Έχει ιδιαίτερη αξία επειδή βοηθά στην κατανόηση της μετάβασης από τις προϊστορικές κοινότητες στις πρώιμες πόλεις της αρχαϊκής Κρήτης.', 'Από κατοικημένη θέση και αρχαϊκή πόλη έγινε πεδίο αρχαιολογικής έρευνας.', 'medium', 'Η πρόσβαση γίνεται από το Καβούσι και απαιτεί προσοχή/περπάτημα σε λόφο.', 'Ανατολική Κρήτη / Περιοχή Καβουσίου', ARRAY['Γουρνιά', 'Καβούσι Κάστρο', 'Βρόκαστρο', 'Λατώ']::text[], 'Ο λόφος του Αζοριά με θέα στον κόλπο του Μιραμπέλλου.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['archaeological_cadastre_azorias', 'cretanbeaches_azorias']::text[], 'https://upload.wikimedia.org/wikipedia/commons/1/14/Aerial_view_of_Azoria_from_the_Kastro.jpg'),
  (91, 'karfi-minoan-settlement', 'Καρφί / Ορεινός μινωικός οικισμός', ARRAY['Ορεινός οικισμός', 'Μινωική θέση', 'Ιερό κορυφής']::text[], ARRAY['Υστερομινωική', 'Πρώιμη Εποχή Σιδήρου']::text[], 'Η χρήση του οικισμού συνδέεται κυρίως με τους μετανακτορικούς/ύστερους μινωικούς χρόνους.', 'Υστερομινωική περίοδος - Πρώιμη Εποχή Σιδήρου', 'Ο ορεινός οικισμός εγκαταλείφθηκε σταδιακά μετά τη φάση χρήσης του.', 'Κοινότητες της ανατολικής Κρήτης, πιθανώς σε περίοδο ανασφάλειας και μετακινήσεων προς ορεινές θέσεις.', 'Κατοίκηση σε φυσικά οχυρή ορεινή θέση και πιθανή λατρευτική χρήση κορυφής.', 'Το Καρφί είναι ορεινή μινωική θέση πάνω από το οροπέδιο Λασιθίου. Ξεχωρίζει για τη θέα και τη φυσική του προστασία, ενώ συνδέεται με τις δύσκολες μεταβατικές φάσεις μετά την κατάρρευση του ανακτορικού συστήματος στην Κρήτη.', 'Από ορεινός οικισμός/λατρευτική θέση έγινε αρχαιολογικό και πεζοπορικό σημείο ενδιαφέροντος.', 'hard', 'Η πρόσβαση είναι δύσκολη και απαιτεί πεζοπορία σε ορεινό περιβάλλον.', 'Ανατολική Κρήτη / Λασίθι', ARRAY['Δικταίο Άντρο', 'Δρήρος', 'Λατώ', 'Οροπέδιο Λασιθίου']::text[], 'Η κορυφή Καρφί και η πανοραμική θέα προς το οροπέδιο Λασιθίου.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['cretanbeaches_karfi', 'ruralgreece_karfi']::text[], 'https://upload.wikimedia.org/wikipedia/commons/9/9f/Karfi-3.JPG'),
  (211, 'prinias-rhizenia', 'Πρινιάς / Ριζηνία', ARRAY['Πόλη', 'Ακρόπολη', 'Ναοί']::text[], ARRAY['Γεωμετρική', 'Αρχαϊκή', 'Κλασική']::text[], 'Η θέση αναπτύχθηκε στους πρώιμους ιστορικούς χρόνους, με ιδιαίτερη σημασία στην αρχαϊκή περίοδο.', 'Γεωμετρική - Αρχαϊκή περίοδος', 'Η χρήση της περιοχής μεταβλήθηκε σταδιακά στους μεταγενέστερους χρόνους.', 'Κοινότητες της κεντρικής Κρήτης.', 'Οικιστικό, πολιτικό και λατρευτικό κέντρο σε στρατηγική θέση της κεντρικής Κρήτης.', 'Ο Πρινιάς, που συχνά ταυτίζεται με τη Ριζηνία, είναι σημαντική αρχαϊκή θέση της Κρήτης. Είναι γνωστή για τα αρχιτεκτονικά και γλυπτά στοιχεία που δείχνουν την ανάπτυξη της κρητικής πόλης στους πρώιμους ιστορικούς χρόνους.', 'Από αρχαία θέση κατοίκησης και λατρείας μετατράπηκε σε αρχαιολογικό χώρο έρευνας.', 'medium', 'Η πρόσβαση γίνεται από την ενδοχώρα του Ηρακλείου και απαιτεί βασική προσοχή στον εντοπισμό της θέσης.', 'Κεντρική Κρήτη', ARRAY['Γόρτυνα', 'Φαιστός', 'Τύλισος', 'Κνωσός']::text[], 'Η ακρόπολη/λόφος του Πρινιά με θέα στην κεντρική Κρήτη.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general', 'archaeological_cadastre_general']::text[], 'https://upload.wikimedia.org/wikipedia/commons/c/ce/Prinias_village.jpg'),
  (214, 'kamilari-tholos-tomb', 'Μινωικός θολωτός τάφος Καμηλαρίου', ARRAY['Τάφος', 'Μινωικό νεκροταφείο']::text[], ARRAY['Μινωική']::text[], 'Μινωική περίοδος.', 'Παλαιοανακτορική - Νεοανακτορική περίοδος', 'Η ταφική χρήση σταμάτησε μετά την αρχαιότητα· το μνημείο σώζεται ως αρχαιολογικός χώρος.', 'Μινωικές κοινότητες της περιοχής της Μεσαράς.', 'Ταφική χρήση για κοινότητα συνδεδεμένη με την περιοχή Φαιστού/Μεσαράς.', 'Ο θολωτός τάφος Καμηλαρίου είναι ένα από τα μινωικά ταφικά μνημεία της Μεσαράς. Η θέση του κοντά στη Φαιστό και την Αγία Τριάδα τον κάνει χρήσιμο για να παρουσιαστεί η ταφική πλευρά του μινωικού πολιτισμού, πέρα από τα ανάκτορα.', 'Από ενεργό μινωικό ταφικό μνημείο έγινε αρχαιολογικός χώρος.', 'medium', 'Η πρόσβαση γίνεται από την περιοχή Καμηλαρίου/Φαιστού και απαιτεί μικρή παράκαμψη από τους βασικούς δρόμους.', 'Μινωική Μεσαρά / Κρήτη', ARRAY['Φαιστός', 'Αγία Τριάδα', 'Κομμός']::text[], 'Ο κυκλικός θολωτός τάφος με το τοπίο της Μεσαράς.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], 'https://upload.wikimedia.org/wikipedia/commons/c/cc/Tholos-Kamilari_1.JPG'),
  (124, 'vathypetro-minoan-villa', 'Μινωική έπαυλη Βαθυπέτρου', ARRAY['Μινωική έπαυλη', 'Αγροτική εγκατάσταση', 'Οικονομικό κέντρο']::text[], ARRAY['Μινωική']::text[], 'Νεοανακτορική μινωική περίοδος.', '2η χιλιετία π.Χ.', 'Η χρήση της έπαυλης σταμάτησε μετά τις καταστροφές/μεταβολές της μινωικής περιόδου.', 'Μινωική τοπική ελίτ ή ανακτορικό δίκτυο της περιοχής Κνωσού/Αρχανών.', 'Αγροτική, παραγωγική και διοικητική λειτουργία, πιθανώς συνδεδεμένη με κρασί, λάδι και αποθήκευση.', 'Η μινωική έπαυλη Βαθυπέτρου, κοντά στις Αρχάνες, είναι χαρακτηριστική θέση για την οικονομική οργάνωση της μινωικής Κρήτης. Δεν είναι μεγάλο ανάκτορο όπως η Κνωσός ή η Φαιστός, αλλά δείχνει πώς λειτουργούσαν μικρότερα κέντρα παραγωγής και διαχείρισης στην ενδοχώρα.', 'Από παραγωγική/διοικητική μινωική εγκατάσταση έγινε αρχαιολογικός χώρος.', 'medium', 'Προσβάσιμη από την περιοχή Αρχανών, αλλά χρειάζεται έλεγχο για ωράριο και κατάσταση επίσκεψης.', 'Μινωική Κρήτη / Περιοχή Αρχανών', ARRAY['Κνωσός', 'Αρχάνες', 'Γιούχτας', 'Τύλισος']::text[], 'Τα κατάλοιπα της έπαυλης με το αγροτικό τοπίο των Αρχανών.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], 'https://upload.wikimedia.org/wikipedia/commons/8/82/Vathypetro-elisa_atene-3911.jpg'),
  (123, 'amnisos-house-of-lilies', 'Αμνισός / Οικία των Κρίνων', ARRAY['Μινωική έπαυλη', 'Παράκτια εγκατάσταση', 'Τοιχογραφίες']::text[], ARRAY['Μινωική']::text[], 'Νεοανακτορική μινωική περίοδος.', '2η χιλιετία π.Χ.', 'Η χρήση του χώρου σταμάτησε μετά τις μινωικές καταστροφές και τις μεταβολές της περιοχής.', 'Συνδέεται με το μινωικό δίκτυο της Κνωσού.', 'Παράκτια εγκατάσταση/έπαυλη συνδεδεμένη με το λιμάνι της Κνωσού και πιθανές τελετουργικές ή διοικητικές χρήσεις.', 'Η Αμνισός ήταν το παραλιακό επίνειο της Κνωσού. Η Οικία των Κρίνων είναι γνωστή από τις μινωικές τοιχογραφίες της και δείχνει τη σύνδεση ανακτορικού κέντρου, θάλασσας και πολυτελούς κατοίκησης.', 'Από μινωική παράκτια εγκατάσταση έγινε αρχαιολογική θέση της περιοχής Ηρακλείου.', 'medium', 'Η πρόσβαση είναι σχετικά εύκολη στην παραλιακή ζώνη ανατολικά του Ηρακλείου, αλλά η επισκεψιμότητα του ακριβούς χώρου χρειάζεται έλεγχο.', 'Μινωική Κνωσός / Αμνισός', ARRAY['Κνωσός', 'Ηράκλειο', 'Μινωικά λιμάνια']::text[], 'Η θέση της Αμνισού ή αναπαράσταση/λεπτομέρεια από την τοιχογραφία των κρίνων.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: fuzzy (0.740).', ARRAY['odysseus_arch_sites_general']::text[], 'https://upload.wikimedia.org/wikipedia/commons/6/6f/Heraklion_-_Amnissos_-_Lily_fresco.jpg'),
  (116, 'ancient-kissamos', 'Αρχαία Κίσσαμος', ARRAY['Πόλη', 'Λιμάνι', 'Ρωμαϊκά κατάλοιπα']::text[], ARRAY['Ελληνιστική', 'Ρωμαϊκή', 'Παλαιοχριστιανική']::text[], 'Η πόλη αναπτύχθηκε ιδιαίτερα στους ελληνιστικούς και ρωμαϊκούς χρόνους.', 'Ελληνιστική - Ρωμαϊκή περίοδος', 'Η πόλη συνέχισε να μεταβάλλεται στους μεταγενέστερους χρόνους και τμήματά της καλύπτονται από τον σύγχρονο οικισμό.', 'Αναπτύχθηκε από τις κοινότητες της δυτικής Κρήτης, με ισχυρή παρουσία στους ρωμαϊκούς χρόνους.', 'Αστικό και λιμενικό κέντρο της δυτικής Κρήτης.', 'Η Αρχαία Κίσσαμος ήταν σημαντική πόλη και λιμάνι της δυτικής Κρήτης. Η θέση της στον κόλπο της Κισσάμου της έδινε ρόλο στις θαλάσσιες επικοινωνίες, ενώ τα σωζόμενα ευρήματα δείχνουν ιδιαίτερη σημασία στους ρωμαϊκούς χρόνους.', 'Η αρχαία πόλη ενσωματώθηκε σε μεταγενέστερες φάσεις κατοίκησης και στη σύγχρονη Κίσσαμο.', 'easy', 'Εύκολη πρόσβαση μέσα/κοντά στη σύγχρονη Κίσσαμο, αλλά τα αρχαία κατάλοιπα είναι διάσπαρτα.', 'Δυτική Κρήτη / Κίσσαμος', ARRAY['Φαλάσαρνα', 'Άπτερα', 'Αρχαιολογικό Μουσείο Κισσάμου']::text[], 'Ρωμαϊκό ψηφιδωτό ή αρχαιολογικό κατάλοιπο της Κισσάμου.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], 'https://upload.wikimedia.org/wikipedia/commons/b/ba/2339_kissamos-kastelli.jpg'),
  (233, 'molyvoti-ancient-stryme', 'Μολυβωτή / Αρχαία Στρύμη', ARRAY['Πόλη', 'Αποικία', 'Παράκτια θέση']::text[], ARRAY['Αρχαϊκή', 'Κλασική']::text[], 'Συνδέεται με αρχαϊκή/κλασική αποικιακή εγκατάσταση στη θρακική ακτή.', 'Αρχαϊκή - Κλασική περίοδος', 'Η θέση εγκαταλείφθηκε ή έχασε τη σημασία της στους μεταγενέστερους χρόνους.', 'Συνδέεται με αποικιακή δραστηριότητα ελληνικών πόλεων στο βόρειο Αιγαίο.', 'Παράκτια εμπορική και αποικιακή εγκατάσταση στη Θράκη.', 'Η Μολυβωτή, που συχνά συνδέεται με την αρχαία Στρύμη, είναι σημαντική παράκτια αρχαιολογική θέση της Ροδόπης. Η θέση της δείχνει την παρουσία ελληνικών αποικιών και εμπορικών εγκαταστάσεων στη θρακική ακτή του βόρειου Αιγαίου.', 'Από αρχαία παράκτια εγκατάσταση έγινε αρχαιολογική θέση έρευνας.', 'medium', 'Η πρόσβαση γίνεται προς την παραλιακή ζώνη της Ροδόπης και μπορεί να απαιτεί έλεγχο για την ακριβή επισκεψιμότητα.', 'Θρακική ακτή / Βόρειο Αιγαίο', ARRAY['Άβδηρα', 'Μεσημβρία-Ζώνη', 'Σαμοθράκη']::text[], 'Το παράκτιο τοπίο της Μολυβωτής με τα αρχαιολογικά ίχνη.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general', 'archaeological_cadastre_general']::text[], ''),
  (139, 'ancient-gortys-arcadia', 'Αρχαία Γόρτυς Αρκαδίας', ARRAY['Πόλη', 'Ιερό', 'Ποτάμιο τοπίο']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η πόλη αναπτύχθηκε σταδιακά στους ιστορικούς χρόνους της Αρκαδίας.', 'Κλασική - Ρωμαϊκή περίοδος', 'Η σημασία της μειώθηκε σταδιακά στους μεταγενέστερους χρόνους.', 'Αρκαδικές κοινότητες της περιοχής.', 'Αστικό και λατρευτικό κέντρο της αρχαίας Αρκαδίας.', 'Η Αρχαία Γόρτυς της Αρκαδίας βρίσκεται σε περιοχή με έντονο φυσικό τοπίο, κοντά στον Λούσιο. Είναι χαρακτηριστικό παράδειγμα αρκαδικής πόλης όπου το αρχαιολογικό ενδιαφέρον συνδυάζεται με ποτάμιο και ορεινό περιβάλλον.', 'Από αρχαία πόλη μετατράπηκε σε αρχαιολογικό τοπίο φυσικού και ιστορικού ενδιαφέροντος.', 'medium', 'Η πρόσβαση γίνεται με όχημα στην ευρύτερη περιοχή και απαιτεί περπάτημα/προσοχή σε φυσικό περιβάλλον.', 'Αρκαδία', ARRAY['Λούσιος', 'Λυκόσουρα', 'Ορχομενός Αρκαδίας', 'Λύκαιο Όρος']::text[], 'Τα ερείπια της Γόρτυος μέσα στο φυσικό τοπίο του Λούσιου.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], ''),
  (60, 'ancient-orchomenos-arcadia', 'Αρχαίος Ορχομενός Αρκαδίας', ARRAY['Πόλη', 'Θέατρο', 'Ακρόπολη']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η πόλη αναπτύχθηκε σταδιακά στους ιστορικούς χρόνους.', 'Κλασική - Ελληνιστική περίοδος', 'Η χρήση της πόλης μειώθηκε στους μεταγενέστερους χρόνους.', 'Αρκαδικές κοινότητες της περιοχής.', 'Πολιτικό και αστικό κέντρο της βόρειας Αρκαδίας.', 'Ο Αρχαίος Ορχομενός της Αρκαδίας ήταν σημαντική πόλη σε στρατηγική θέση. Τα κατάλοιπα της ακρόπολης και του θεάτρου δείχνουν τη δημόσια και πολιτική ζωή της πόλης μέσα στο αρκαδικό τοπίο.', 'Από ενεργή αρχαία πόλη έγινε αρχαιολογικός χώρος.', 'medium', 'Η πρόσβαση γίνεται με όχημα και στη συνέχεια με περπάτημα σε αρχαιολογικό/υπαίθριο χώρο.', 'Αρκαδία', ARRAY['Μαντίνεια', 'Τεγέα', 'Στύμφαλος', 'Λυκόσουρα']::text[], 'Το αρχαίο θέατρο ή η ακρόπολη του Ορχομενού Αρκαδίας.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general', 'allofgreeceone_venues']::text[], ''),
  (156, 'ancient-kleonai', 'Αρχαίες Κλεωνές', ARRAY['Πόλη', 'Οχύρωση', 'Περασματική θέση']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική']::text[], 'Η πόλη αναπτύχθηκε στους ιστορικούς χρόνους κοντά στον άξονα Κορίνθου-Άργους.', 'Αρχαϊκή - Ελληνιστική περίοδος', 'Η σημασία της μειώθηκε στους μεταγενέστερους χρόνους.', 'Τοπική κοινότητα της Κλεωνών.', 'Έλεγχος στρατηγικού περάσματος και συμμετοχή στο δίκτυο πόλεων της βορειοανατολικής Πελοποννήσου.', 'Οι Αρχαίες Κλεωνές βρίσκονται κοντά στη Νεμέα και στον δρόμο που συνέδεε την Κόρινθο με το Άργος. Παρότι είναι λιγότερο γνωστές από τη Νεμέα, είναι σημαντικές για την κατανόηση του τοπικού δικτύου πόλεων της Κορινθίας και της Αργολίδας.', 'Από αρχαία πόλη και οχυρή θέση έγινε αρχαιολογικός χώρος.', 'medium', 'Η πρόσβαση γίνεται από την περιοχή Νεμέας/Κλεωνών, αλλά χρειάζεται έλεγχος για την ακριβή διαδρομή.', 'Κλεωνές / Βορειοανατολική Πελοπόννησος', ARRAY['Αρχαία Νεμέα', 'Αρχαία Κόρινθος', 'Μυκήνες']::text[], 'Τα οχυρωματικά κατάλοιπα ή ο λόφος των αρχαίων Κλεωνών.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], ''),
  (136, 'titane-sikyona', 'Τιτάνη Σικυώνας', ARRAY['Ιερό', 'Αρχαία θέση']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Η θέση συνδέεται με αρχαία λατρευτική δραστηριότητα στην περιοχή της Σικυώνας.', 'Κλασική - Ρωμαϊκή περίοδος', 'Η λατρευτική χρήση σταμάτησε μετά την αρχαιότητα.', 'Τοπικές κοινότητες της περιοχής Σικυώνας.', 'Λατρευτική χρήση και σύνδεση με την αρχαία Σικυώνα.', 'Η Τιτάνη της Σικυώνας είναι λιγότερο γνωστή αλλά σημαντική αρχαία θέση της Κορινθίας. Χρήσιμη στην εφαρμογή ως συμπληρωματικό σημείο γύρω από την Αρχαία Σικυώνα, τη Νεμέα και την Κόρινθο.', 'Από αρχαία λατρευτική θέση έγινε αρχαιολογικό/ιστορικό σημείο ενδιαφέροντος.', 'medium', 'Η πρόσβαση απαιτεί τοπικό εντοπισμό και πιθανώς έλεγχο διαδρομής πριν την επίσκεψη.', 'Σικυώνα / Κορινθία', ARRAY['Αρχαία Σικυώνα', 'Αρχαία Κόρινθος', 'Νεμέα']::text[], 'Το τοπίο της Τιτάνης ή σωζόμενα κατάλοιπα στην περιοχή της Σικυώνας.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], ''),
  (41, 'ancient-trapezous-arcadia', 'Αρχαία Τραπεζούντα Αρκαδίας', ARRAY['Πόλη', 'Αρκαδική θέση']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική']::text[], 'Η πόλη αναπτύχθηκε στους ιστορικούς χρόνους της Αρκαδίας.', 'Κλασική περίοδος', 'Η σημασία της μειώθηκε μετά τη δημιουργία/ενίσχυση μεγαλύτερων αρκαδικών κέντρων.', 'Αρκαδική κοινότητα της περιοχής.', 'Τοπικό αστικό και πολιτικό κέντρο της Αρκαδίας.', 'Η Αρχαία Τραπεζούντα είναι μία από τις μικρότερες αλλά ενδιαφέρουσες αρκαδικές θέσεις. Βοηθά να παρουσιαστεί η Αρκαδία όχι μόνο μέσα από μεγάλα ιερά, αλλά και μέσα από το δίκτυο μικρών πόλεων της ενδοχώρας.', 'Από τοπική αρχαία πόλη έγινε αρχαιολογικό σημείο ενδιαφέροντος.', 'medium', 'Η πρόσβαση χρειάζεται τοπικό εντοπισμό και έλεγχο διαδρομής.', 'Αρκαδία', ARRAY['Λυκόσουρα', 'Λύκαιο Όρος', 'Μεγαλόπολη', 'Γόρτυς Αρκαδίας']::text[], 'Το αρκαδικό τοπίο και τυχόν ορατά κατάλοιπα της αρχαίας θέσης.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: exact-title (1.000).', ARRAY['odysseus_arch_sites_general']::text[], ''),
  (1, 'pangaion-avgo-peak', 'Κορυφή Αυγό Παγγαίου', ARRAY['Ορεινό τοπίο', 'Ιερή/ιστορική περιοχή', 'Μεταλλευτική ζώνη']::text[], ARRAY['Αρχαϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Δεν πρόκειται για χτιστό μνημείο· το Παγγαίο συνδέεται με αρχαία μεταλλευτική, λατρευτική και ιστορική σημασία.', 'Αρχαιότητα - νεότεροι χρόνοι', 'Δεν έχει ενιαία φάση καταστροφής, καθώς πρόκειται κυρίως για ορεινή/ιστορική περιοχή.', 'Δεν έχει κτήτορα· είναι φυσικό βουνό με ιστορική χρήση από αρχαίες κοινότητες.', 'Μεταλλευτική, στρατηγική και πιθανώς λατρευτική σημασία στην αρχαιότητα.', 'Το Παγγαίο όρος είχε μεγάλη σημασία στην αρχαιότητα λόγω των μεταλλείων, της στρατηγικής του θέσης και της σύνδεσής του με θρακικές και μακεδονικές περιοχές. Η κορυφή Αυγό μπορεί να λειτουργήσει στην εφαρμογή ως τοπίο-σύμβολο για την ορεινή διάσταση της περιοχής Καβάλας.', 'Από ιστορικό φυσικό και μεταλλευτικό τοπίο έγινε σημείο πεζοπορικού και πολιτιστικού ενδιαφέροντος.', 'hard', 'Η πρόσβαση είναι δύσκολη και απαιτεί ορεινή διαδρομή/πεζοπορία και κατάλληλες συνθήκες.', 'Παγγαίο / Θράκη και Μακεδονία', ARRAY['Φίλιπποι', 'Dikili Tash', 'Αμφίπολη', 'Παγγαία μεταλλεία']::text[], 'Η κορυφή Αυγό και το ορεινό τοπίο του Παγγαίου.', 'medium', true, 'Manual-review import: mapped cleaned monument "Κορυφή Αυγό Παγγαίου" to catalog_id 1 "Κορυφη Αυγο Παγγαιο". Alternatives: 5: Πιθανή θέση της Ποικίλης Στοάς (0.000); 7: Μεγάλα Προπύλαια Ελευσίνας (0.000); 8: [χωρίς όνομα] (0.000).', ARRAY['odysseus_arch_sites_general']::text[], ''),
  (229, 'spilaio-polyfimos-evros', 'Σπηλιά του Πολύφημου', ARRAY['Σπήλαιο', 'Μυθολογική τοποθεσία', 'Φυσικό μνημείο']::text[], ARRAY['Μυθολογική παράδοση', 'Αρχαιότητα']::text[], 'Δεν έχει κτήτορα· πρόκειται για φυσικό σπήλαιο που συνδέεται με παράδοση/τοπική ταύτιση.', 'Φυσικός χώρος με μεταγενέστερη ιστορική/μυθολογική σημασία', 'Δεν υπάρχει φάση καταστροφής ως χτιστού μνημείου.', 'Δεν χτίστηκε από άνθρωπο.', 'Φυσικός χώρος που στην εφαρμογή μπορεί να παρουσιαστεί ως μυθολογικό/τοπικό σημείο ενδιαφέροντος.', 'Η Σπηλιά του Πολύφημου είναι σημείο που συνδέεται περισσότερο με τοπική παράδοση και μυθολογική αφήγηση παρά με κλασικό αρχαιολογικό οικοδόμημα. Μπορεί να χρησιμοποιηθεί στην εφαρμογή ως ειδική κατηγορία φυσικού/μυθολογικού ενδιαφέροντος, με προσεκτική διατύπωση ώστε να μη δοθεί ως βέβαιη αρχαιολογική ταύτιση.', 'Από φυσικό σπήλαιο προβάλλεται σήμερα ως τοπικό σημείο ενδιαφέροντος.', 'medium', 'Η πρόσβαση πρέπει να ελεγχθεί τοπικά, γιατί εξαρτάται από τη διαδρομή και την κατάσταση του σπηλαίου.', 'Θράκη / τοπική παράδοση', ARRAY['Μεσημβρία-Ζώνη', 'Σαμοθράκη', 'Θρακική ακτή']::text[], 'Η είσοδος του σπηλαίου ή το φυσικό τοπίο γύρω από τη θέση.', 'low', false, 'Imported from cleaned 217 dataset. Match method: fuzzy (1.000).', ARRAY['odysseus_arch_sites_general']::text[], ''),
  (5, 'poikile-stoa-probable-location', 'Πιθανή θέση της Ποικίλης Στοάς', ARRAY['Στοά', 'Δημόσιο κτήριο', 'Υποσημείο αρχαιολογικού χώρου']::text[], ARRAY['Κλασική']::text[], 'Πιθανότατα μεταξύ 475-450 π.Χ.', '5ος αιώνας π.Χ. - Ελληνιστική/Ρωμαϊκή περίοδος', 'Δεν σώζεται ως πλήρες κτήριο· η θέση και τα κατάλοιπα εντάσσονται στον αρχαιολογικό χώρο της Αρχαίας Αγοράς.', 'Συνδέεται παραδοσιακά με τον Πεισιάνακτα, γαμπρό του Κίμωνα.', 'Δημόσια στοά της Αγοράς, γνωστή για τη ζωγραφική διακόσμηση και τη σύνδεσή της με τη δημόσια ζωή της Αθήνας.', 'Η Ποικίλη Στοά ήταν μία από τις πιο γνωστές στοές της Αρχαίας Αγοράς της Αθήνας. Βρισκόταν στη βόρεια πλευρά της Αγοράς και πήρε το όνομά της από τις ζωγραφικές παραστάσεις που κοσμούσαν το εσωτερικό της. Για την εφαρμογή είναι καλύτερα να παρουσιαστεί ως υποσημείο της Αρχαίας Αγοράς, επειδή ανήκει στον ίδιο μεγάλο αρχαιολογικό χώρο.', 'Από δημόσιο κτήριο της αρχαίας πόλης σήμερα σώζεται ως αρχαιολογικό ίχνος μέσα στον ευρύτερο χώρο της Αγοράς.', 'easy', 'Η πρόσβαση γίνεται μέσω του αρχαιολογικού χώρου της Αρχαίας Αγοράς.', 'Αθήνα / Αθηναϊκή πόλη-κράτος', ARRAY['Αρχαία Αγορά της Αθήνας', 'Στοά Αττάλου', 'Ναός Ηφαίστου']::text[], 'Άποψη της βόρειας πλευράς της Αρχαίας Αγοράς ή χάρτης/αναπαράσταση της Ποικίλης Στοάς.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['odysseus_ancient_agora_athens', 'culture_poikile_stoa_pdf']::text[], ''),
  (7, 'great-propylaea-eleusis', 'Μεγάλα Προπύλαια Ελευσίνας', ARRAY['Πρόπυλο', 'Ιερό', 'Υποσημείο αρχαιολογικού χώρου']::text[], ARRAY['Ρωμαϊκή']::text[], 'Ρωμαϊκή περίοδος, στην τελευταία μεγάλη φάση ακμής του ιερού.', 'Ρωμαϊκή περίοδος - τέλος 4ου αιώνα μ.Χ.', 'Ο χώρος παρακμάζει στο τέλος του 4ου αιώνα μ.Χ. και μετατρέπεται σε ερείπια μετά την ύστερη αρχαιότητα.', 'Συνδέεται με τις ρωμαϊκές επεμβάσεις και τον εμπλουτισμό του ιερού από Ρωμαίους αυτοκράτορες.', 'Μνημειακή είσοδος στο ιερό της Δήμητρας και της Περσεφόνης.', 'Τα Μεγάλα Προπύλαια αποτελούσαν τη μνημειακή είσοδο στον ιερό χώρο της Ελευσίνας. Ανήκουν στα εντυπωσιακά ρωμαϊκά οικοδομήματα που στόλισαν το ιερό κατά την τελευταία περίοδο ακμής του. Στην εφαρμογή πρέπει να μπουν ως υποσημείο του αρχαιολογικού χώρου της Ελευσίνας.', 'Από τελετουργική είσοδος του ιερού, σήμερα αποτελεί βασικό αρχαιολογικό σημείο της Ελευσίνας.', 'easy', 'Εύκολη πρόσβαση μέσα από τον οργανωμένο αρχαιολογικό χώρο της Ελευσίνας.', 'Ελευσίνα / Αττική, συνδεδεμένη με την Αθήνα', ARRAY['Αρχαιολογικός χώρος Ελευσίνας', 'Τελεστήριο', 'Μικρά Προπύλαια', 'Ιερά Οδός']::text[], 'Τα σωζόμενα κατάλοιπα των Μεγάλων Προπυλαίων μέσα στον αρχαιολογικό χώρο.', 'high', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['odysseus_eleusis']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/General_view_of_sanctuary_of_Demeter_and_Kore_and_the_Telesterion_(Initiation_Hall),_center_for_the_Eleusinian_Mysteries,_Eleusis_(8191841684).jpg'),
  (11, 'klepsydra-acropolis-north-slope', 'Κλεψύδρα και μυκηναϊκή κρυφή πρόσβαση βόρειας κλιτύος Ακρόπολης', ARRAY['Πηγή', 'Μυκηναϊκή πρόσβαση', 'Υποσημείο αρχαιολογικού χώρου']::text[], ARRAY['Μυκηναϊκή', 'Κλασική', 'Ρωμαϊκή']::text[], 'Η περιοχή συνδέεται με τη μυκηναϊκή οχύρωση και με μεταγενέστερη χρήση της φυσικής πηγής.', 'Μυκηναϊκή εποχή - αρχαιότητα', 'Δεν πρόκειται για ενιαίο κτήριο· τα κατάλοιπα ανήκουν σε διαφορετικές φάσεις χρήσης της βόρειας κλιτύος.', 'Η μυκηναϊκή πρόσβαση συνδέεται με τις ανάγκες της οχυρωμένης ακρόπολης, ενώ η Κλεψύδρα αξιοποιεί τη φυσική πηγή της περιοχής.', 'Εξασφάλιση πρόσβασης και νερού στην Ακρόπολη, ιδιαίτερα σε περιόδους ανάγκης.', 'Η Κλεψύδρα και η κρυφή μυκηναϊκή πρόσβαση της βόρειας κλιτύος είναι από τα πιο ενδιαφέροντα αλλά λιγότερο ορατά σημεία της Ακρόπολης. Δείχνουν ότι ο βράχος δεν ήταν μόνο χώρος λατρείας και μνημείων, αλλά και οργανωμένη οχυρή θέση με ανάγκη για ασφαλή πρόσβαση σε νερό.', 'Η λειτουργική χρήση της πρόσβασης και της πηγής χάθηκε, ενώ σήμερα το σημείο παρουσιάζεται ως αρχαιολογικό κατάλοιπο της βόρειας κλιτύος.', 'medium', 'Δεν είναι τόσο εμφανές όσο τα κύρια μνημεία της Ακρόπολης και θέλει προσεκτικό εντοπισμό στον χώρο.', 'Αθήνα / Ακρόπολη', ARRAY['Ακρόπολη', 'Βόρεια Κλιτύς', 'Προπύλαια']::text[], 'Λήψη της βόρειας κλιτύος ή χάρτης σημείωσης της Κλεψύδρας.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['odysseus_acropolis_general']::text[], ''),
  (15, 'iera-odos-kifisos-ancient-crossing', 'Αρχαία γέφυρα / διάβαση Κηφισού στην Ιερά Οδό', ARRAY['Γέφυρα', 'Οδικό έργο', 'Υποσημείο διαδρομής']::text[], ARRAY['Κλασική', 'Ρωμαϊκή']::text[], 'Αρχαία χρήση της Ιεράς Οδού με μεταγενέστερες επισκευές και φάσεις.', 'Κλασική - Ρωμαϊκή περίοδος', 'Η αρχαία οδική λειτουργία αντικαταστάθηκε από νεότερες διαδρομές.', 'Συνδέεται με την αθηναϊκή οργάνωση της Ιεράς Οδού και τη διαδρομή προς την Ελευσίνα.', 'Διευκόλυνση της πορείας προς την Ελευσίνα και της διάβασης του Κηφισού.', 'Η διάβαση του Κηφισού στην Ιερά Οδό συνδέεται με τη σημαντικότερη τελετουργική διαδρομή της αρχαίας Αττικής, αυτή που ένωνε την Αθήνα με την Ελευσίνα. Είναι καλύτερο να παρουσιαστεί ως υποσημείο της Ιεράς Οδού και της Ελευσίνας, όχι ως ανεξάρτητο μεγάλο μνημείο.', 'Από λειτουργικό σημείο της αρχαίας διαδρομής σήμερα αποτελεί αρχαιολογικό ίχνος/σημείο ενδιαφέροντος.', 'medium', 'Η πρόσβαση εξαρτάται από το ακριβές σημείο και το αστικό περιβάλλον της περιοχής.', 'Αθήνα - Ελευσίνα / Ιερά Οδός', ARRAY['Ιερά Οδός', 'Αρχαιολογικός χώρος Ελευσίνας', 'Ρωμαϊκή γέφυρα Ελευσινιακού Κηφισού']::text[], 'Φωτογραφία του σωζόμενου τμήματος ή χάρτης της Ιεράς Οδού.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['odysseus_eleusis', 'odysseus_iera_odos_general']::text[], ''),
  (51, 'roman-bridge-eleusinian-kifisos', 'Ρωμαϊκή Γέφυρα στον Ελευσινιακό Κηφισό', ARRAY['Γέφυρα', 'Ρωμαϊκό τεχνικό έργο', 'Υποσημείο διαδρομής']::text[], ARRAY['Ρωμαϊκή']::text[], 'Ρωμαϊκή περίοδος.', 'Ρωμαϊκή περίοδος και μεταγενέστεροι χρόνοι ως τεχνικό κατάλοιπο.', 'Η αρχαία λειτουργία της γέφυρας έχει πάψει, αλλά το μνημείο διατηρείται ως κατάλοιπο της οδικής υποδομής.', 'Συνδέεται με τη ρωμαϊκή φάση της Ιεράς Οδού και τις τεχνικές παρεμβάσεις στην περιοχή.', 'Διάβαση του Ελευσινιακού Κηφισού στη διαδρομή της Ιεράς Οδού.', 'Η Ρωμαϊκή Γέφυρα στον Ελευσινιακό Κηφισό αποτελεί τεχνικό μνημείο που συνδέεται με την Ιερά Οδό και την πρόσβαση στο ιερό της Ελευσίνας. Λειτουργεί καλύτερα ως υποσημείο της Ελευσίνας και της Ιεράς Οδού, επειδή εξηγεί τη διαδρομή των προσκυνητών και τη σημασία των οδικών έργων.', 'Από πρακτικό οδικό έργο μετατράπηκε σε αρχαιολογικό κατάλοιπο.', 'medium', 'Η πρόσβαση απαιτεί εντοπισμό στο αστικό/περιαστικό περιβάλλον της περιοχής.', 'Αθήνα - Ελευσίνα / Ιερά Οδός', ARRAY['Ιερά Οδός', 'Αρχαιολογικός χώρος Ελευσίνας', 'Μεγάλα Προπύλαια Ελευσίνας']::text[], 'Πλάγια λήψη της γέφυρας ή κοντινή φωτογραφία της λιθοδομής.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['odysseus_eleusis', 'odysseus_iera_odos_general']::text[], ''),
  (17, 'ancient-theatre-delphi-subpoint', 'Αρχαίο Θέατρο Δελφών', ARRAY['Θέατρο', 'Υποσημείο αρχαιολογικού χώρου']::text[], ARRAY['Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Το σωζόμενο θέατρο ανάγεται κυρίως στους ύστερους κλασικούς/ελληνιστικούς χρόνους, με μεταγενέστερες επεμβάσεις.', 'Ελληνιστική - Ρωμαϊκή περίοδος', 'Έπαψε να λειτουργεί ως θέατρο μετά την εγκατάλειψη των αρχαίων λατρειών και θεσμών.', 'Αναπτύχθηκε στο πλαίσιο του ιερού των Δελφών και της Αμφικτυονίας.', 'Χώρος παραστάσεων και μουσικών/ποιητικών αγώνων στο πλαίσιο του δελφικού ιερού.', 'Το Αρχαίο Θέατρο Δελφών βρίσκεται πάνω από τον ναό του Απόλλωνα και προσφέρει πανοραμική θέα στο ιερό και στο δελφικό τοπίο. Είναι από τα πιο χαρακτηριστικά υποσημεία των Δελφών και βοηθά τον επισκέπτη να καταλάβει ότι ο χώρος δεν ήταν μόνο μαντείο, αλλά και κέντρο αγώνων και δημόσιων εκδηλώσεων.', 'Από χώρο παραστάσεων μετατράπηκε σε αρχαιολογικό μνημείο μέσα στον χώρο των Δελφών.', 'medium', 'Η πρόσβαση γίνεται μέσα από τον αρχαιολογικό χώρο των Δελφών και έχει ανηφορική πορεία.', 'Δελφοί / Πανελλήνιο ιερό', ARRAY['Αρχαιολογικός χώρος Δελφών', 'Ναός Απόλλωνα', 'Στάδιο Δελφών', 'Θόλος Αθηνάς Προναίας']::text[], 'Το κοίλο του θεάτρου με φόντο το δελφικό τοπίο.', 'high', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['odysseus_delphi']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/The_ancient_theatre_of_Delphi,_Greece_-_panoramio.jpg'),
  (12, 'asclepieion-ancient-messene-subpoint', 'Ασκληπιείο Αρχαίας Μεσσήνης', ARRAY['Ιερό', 'Υποσημείο αρχαιολογικού χώρου']::text[], ARRAY['Ελληνιστική', 'Ρωμαϊκή']::text[], 'Κύρια διαμόρφωση στους ελληνιστικούς χρόνους.', 'Ελληνιστική - Ρωμαϊκή περίοδος', 'Έπαψε να λειτουργεί με την παρακμή της αρχαίας πόλης.', 'Συνδέεται με τη δημόσια και θρησκευτική οργάνωση της Αρχαίας Μεσσήνης.', 'Λατρεία του Ασκληπιού και κεντρικό θρησκευτικό/δημόσιο σύνολο της πόλης.', 'Το Ασκληπιείο ήταν ένα από τα σημαντικότερα μνημειακά σύνολα της Αρχαίας Μεσσήνης. Δεν πρέπει να αντιμετωπιστεί ως απομονωμένο μνημείο, αλλά ως βασικό υποσημείο της πόλης, επειδή συνδέεται με την πολιτική, θρησκευτική και κοινωνική ζωή της Μεσσήνης.', 'Από ιερό και δημόσιο κέντρο της πόλης μετατράπηκε σε τμήμα του αρχαιολογικού χώρου.', 'easy', 'Η πρόσβαση γίνεται μέσα από τον οργανωμένο αρχαιολογικό χώρο της Αρχαίας Μεσσήνης.', 'Αρχαία Μεσσήνη / Μεσσηνία', ARRAY['Αρχαία Μεσσήνη', 'Στάδιο', 'Γυμνάσιο', 'Θέατρο', 'Οχυρώσεις']::text[], 'Άποψη του Ασκληπιείου μέσα στον ευρύτερο χώρο της Αρχαίας Μεσσήνης.', 'high', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['efa_messene_guide', 'odysseus_messene_fortifications']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/%CE%A3%CF%84%CE%BF%CE%BD_%CE%B1%CF%81%CF%87%CE%B1%CE%B9%CE%BF%CE%BB%CE%BF%CE%B3%CE%B9%CE%BA%CF%8C_%CF%87%CF%8E%CF%81%CE%BF_%CF%84%CE%B7%CF%82_%CE%B1%CF%81%CF%87%CE%B1%CE%AF%CE%B1%CF%82_%CE%9C%CE%B5%CF%83%CF%83%CE%AE%CE%BD%CE%B7%CF%82_-_panoramio_(1).jpg'),
  (24, 'palaestra-baths-ancient-messene-subpoint', 'Παλαίστρα και λουτρά Αρχαίας Μεσσήνης', ARRAY['Παλαίστρα', 'Λουτρά', 'Υποσημείο αρχαιολογικού χώρου']::text[], ARRAY['Ελληνιστική', 'Ρωμαϊκή']::text[], 'Ελληνιστική/ρωμαϊκή χρήση μέσα στο οργανωμένο πολεοδομικό σύνολο της πόλης.', 'Ελληνιστική - Ρωμαϊκή περίοδος', 'Η λειτουργία τους σταμάτησε με την παρακμή της πόλης.', 'Συνδέονται με τις δημόσιες εγκαταστάσεις της Αρχαίας Μεσσήνης.', 'Άθληση, εκπαίδευση, κοινωνική ζωή και λουτρικές πρακτικές της πόλης.', 'Η παλαίστρα και τα λουτρά αποτελούν σημαντικό υποσύνολο της Αρχαίας Μεσσήνης. Δείχνουν ότι η πόλη είχε πλήρη δημόσια υποδομή, όχι μόνο ιερά και οχυρώσεις, αλλά και χώρους άθλησης, εκπαίδευσης και καθημερινής κοινωνικής ζωής.', 'Από λειτουργικές εγκαταστάσεις της πόλης έγιναν αρχαιολογικά κατάλοιπα μέσα στον ευρύτερο χώρο.', 'easy', 'Εντός του αρχαιολογικού χώρου, με περπάτημα ανάμεσα στα μνημεία της Μεσσήνης.', 'Αρχαία Μεσσήνη / Μεσσηνία', ARRAY['Αρχαία Μεσσήνη', 'Στάδιο', 'Γυμνάσιο', 'Ασκληπιείο']::text[], 'Άποψη των λουτρών ή της παλαίστρας με το στάδιο/γυμνάσιο κοντά.', 'high', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['efa_messene_guide']::text[], ''),
  (25, 'roman-baths-ancient-corinth-subpoint', 'Ρωμαϊκά λουτρά / βαλανεία Αρχαίας Κορίνθου', ARRAY['Λουτρά', 'Ρωμαϊκό κτήριο', 'Υποσημείο αρχαιολογικού χώρου']::text[], ARRAY['Ρωμαϊκή']::text[], 'Ρωμαϊκή περίοδος.', 'Ρωμαϊκή περίοδος', 'Έπαψαν να λειτουργούν μετά την παρακμή/μεταβολή της ρωμαϊκής πόλης.', 'Συνδέονται με τη ρωμαϊκή Κόρινθο και τις δημόσιες υποδομές της.', 'Λουτρική και κοινωνική χρήση μέσα στη ρωμαϊκή πόλη.', 'Τα ρωμαϊκά λουτρά της Αρχαίας Κορίνθου δείχνουν τη μεταμόρφωση της πόλης μετά τη ρωμαϊκή αναδιοργάνωση. Για την εφαρμογή είναι καλύτερο να μπουν ως υποσημείο της Αρχαίας Κορίνθου, ώστε ο χρήστης να βλέπει τη συνέχεια της πόλης από την ελληνική στη ρωμαϊκή περίοδο.', 'Από λουτρικές εγκαταστάσεις έγιναν τμήμα του αρχαιολογικού χώρου.', 'easy', 'Εντός του οργανωμένου αρχαιολογικού χώρου της Αρχαίας Κορίνθου.', 'Ρωμαϊκή Κόρινθος', ARRAY['Αρχαία Κόρινθος', 'Ναός Απόλλωνα', 'Αγορά', 'Ακροκόρινθος']::text[], 'Κοντινή άποψη των λουτρικών καταλοίπων μέσα στον χώρο της Κορίνθου.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['odysseus_ancient_corinth']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Baths_of_Corinth.jpg'),
  (78, 'fountain-system-heraion-perachora-subpoint', 'Υδραυλικό σύστημα Κρήνης στο Ηραίο Περαχώρας', ARRAY['Υδραυλικό έργο', 'Κρήνη', 'Υποσημείο ιερού']::text[], ARRAY['Αρχαϊκή', 'Κλασική']::text[], 'Αρχαϊκή/κλασική χρήση στο πλαίσιο του ιερού.', 'Αρχαϊκή - Κλασική περίοδος', 'Η λειτουργία του σταμάτησε με την εγκατάλειψη του ιερού.', 'Συνδέεται με την οργάνωση του ιερού της Ήρας στην Περαχώρα.', 'Παροχή και διαχείριση νερού για τις ανάγκες του ιερού και των επισκεπτών.', 'Το υδραυλικό σύστημα της κρήνης είναι σημαντικό υποσημείο του Ηραίου Περαχώρας, επειδή δείχνει ότι το ιερό είχε τεχνική υποδομή για τη διαχείριση νερού. Δεν χρειάζεται ξεχωριστή μεγάλη καρτέλα, αλλά αξίζει να εμφανίζεται μέσα στην καρτέλα του Ηραίου.', 'Από λειτουργικό υδραυλικό έργο αποτελεί σήμερα αρχαιολογικό κατάλοιπο.', 'easy', 'Ελεύθερη/εύκολη πρόσβαση στον χώρο του Ηραίου, ανάλογα με τις συνθήκες επίσκεψης.', 'Κορινθία / Περαχώρα', ARRAY['Ηραίο Περαχώρας', 'Βραχοκομμένες δεξαμενές', 'Λίμνη Βουλιαγμένης Περαχώρας']::text[], 'Κοντινή λήψη της κρήνης ή των υδραυλικών καταλοίπων.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['odysseus_heraion_perachora']::text[], ''),
  (79, 'rock-cut-cisterns-heraion-perachora-subpoint', 'Βραχοκομμένες δεξαμενές Ηραίου Περαχώρας', ARRAY['Δεξαμενές', 'Υδραυλικό έργο', 'Υποσημείο ιερού']::text[], ARRAY['Αρχαϊκή', 'Κλασική']::text[], 'Αρχαϊκή/κλασική χρήση στο πλαίσιο του ιερού.', 'Αρχαϊκή - Κλασική περίοδος', 'Η χρήση τους σταμάτησε με την εγκατάλειψη ή μεταβολή του ιερού.', 'Συνδέονται με την οργάνωση του ιερού της Ήρας στην Περαχώρα.', 'Αποθήκευση νερού και υποστήριξη της λειτουργίας του ιερού.', 'Οι βραχοκομμένες δεξαμενές του Ηραίου Περαχώρας είναι τεχνικά κατάλοιπα που βοηθούν τον χρήστη να καταλάβει την καθημερινή λειτουργία ενός αρχαίου ιερού. Είναι καλό να μπουν ως υποσημείο του Ηραίου μαζί με την κρήνη και τα υπόλοιπα μνημεία του χώρου.', 'Από δεξαμενές αποθήκευσης νερού έγιναν αρχαιολογικά κατάλοιπα.', 'easy', 'Βρίσκονται μέσα στην περιοχή του Ηραίου Περαχώρας.', 'Κορινθία / Περαχώρα', ARRAY['Ηραίο Περαχώρας', 'Υδραυλικό σύστημα Κρήνης']::text[], 'Φωτογραφία των βραχοκομμένων δεξαμενών κοντά στο ιερό.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['odysseus_heraion_perachora']::text[], ''),
  (46, 'altar-of-despina-lykosoura-subpoint', 'Βωμός της Δέσποινας στο ιερό της Λυκόσουρας', ARRAY['Βωμός', 'Ιερό', 'Υποσημείο ιερού']::text[], ARRAY['Κλασική', 'Ελληνιστική']::text[], 'Συνδέεται με τη χρήση του ιερού της Δέσποινας στους κλασικούς/ελληνιστικούς χρόνους.', 'Κλασική - Ελληνιστική περίοδος', 'Η λατρευτική χρήση σταμάτησε στους μεταγενέστερους χρόνους.', 'Συνδέεται με την τοπική αρκαδική λατρεία της Δέσποινας.', 'Λατρευτικές τελετές και θυσίες στο ιερό της Δέσποινας.', 'Ο βωμός της Δέσποινας είναι υποσημείο του ιερού της Λυκόσουρας. Η σημασία του είναι ότι δείχνει την τοπική αρκαδική λατρεία και τη θρησκευτική ταυτότητα της περιοχής. Καλύτερα να συνδέεται με την καρτέλα της Λυκόσουρας και όχι να εμφανίζεται ως ανεξάρτητο μεγάλο μνημείο.', 'Από λατρευτικός βωμός αποτελεί σήμερα αρχαιολογικό κατάλοιπο.', 'medium', 'Η πρόσβαση γίνεται μέσω του αρχαιολογικού χώρου της Λυκόσουρας/ορεινής Αρκαδίας.', 'Αρκαδία / Λυκόσουρα', ARRAY['Ιερό Δέσποινας', 'Λυκόσουρα', 'Λύκαιο Όρος']::text[], 'Κοντινή φωτογραφία του βωμού ή γενική άποψη του ιερού.', 'medium', true, 'Manual-review import: mapped cleaned monument "Βωμός της Δέσποινας στο ιερό της Λυκόσουρας" to catalog_id 46 "Βωμός του Δία". Alternatives: 223: Αρχαϊκό ιερό (0.156); 152: Ιερό του Ηρακλή Αρχαία Αλυζεία (0.130); 141: Αρχαία Θεισόα Αρκαδίας (0.073).', ARRAY['odysseus_lykosoura_general']::text[], ''),
  (141, 'altar-of-zeus-lykaion-subpoint', 'Βωμός του Δία στο Λύκαιο Όρος', ARRAY['Βωμός', 'Ιερό', 'Υποσημείο ιερού']::text[], ARRAY['Προϊστορική', 'Αρχαϊκή', 'Κλασική', 'Ελληνιστική']::text[], 'Η λατρεία στο Λύκαιο Όρος έχει πολύ μεγάλη διάρκεια και δεν περιορίζεται σε μία οικοδομική φάση.', 'Προϊστορικοί χρόνοι - αρχαιότητα', 'Η αρχαία λατρεία σταμάτησε σταδιακά στους μεταγενέστερους χρόνους.', 'Συνδέεται με την τοπική αρκαδική λατρεία του Δία.', 'Λατρεία του Δία σε ορεινό ιερό με έντονη τοπική και μυθική σημασία.', 'Ο βωμός του Δία είναι το πιο χαρακτηριστικό υποσημείο του Λύκαιου Όρους. Δείχνει τον λατρευτικό χαρακτήρα του χώρου και συνδέεται με τις αρκαδικές παραδόσεις για τον Δία. Στην εφαρμογή καλό είναι να εμφανίζεται μέσα στην καρτέλα του Λύκαιου Όρους μαζί με το στάδιο και τον ιππόδρομο.', 'Από ενεργό λατρευτικό σημείο αποτελεί σήμερα αρχαιολογικό και τοπικό σημείο ενδιαφέροντος.', 'medium', 'Η πρόσβαση είναι ορεινή και λιγότερο εύκολη από οργανωμένους αρχαιολογικούς χώρους πόλεων.', 'Αρκαδία / Λύκαιο Όρος', ARRAY['Λύκαιο Όρος', 'Ιερό Δία', 'Στάδιο/Ιππόδρομος Λυκαίου']::text[], 'Πανοραμική άποψη του ορεινού βωμού και του τοπίου.', 'medium', true, 'Manual-review import: mapped cleaned monument "Βωμός του Δία στο Λύκαιο Όρος" to catalog_id 141 "Αρχαία Θεισόα Αρκαδίας". Alternatives: 190: [χωρίς όνομα] (0.044); 8: [χωρίς όνομα] (0.000); 26: [χωρίς όνομα] (0.000).', ARRAY['lykaion_excavation_project', 'odysseus_lykaion_general']::text[], ''),
  (34, 'tomb-of-brasidas-amphipolis-subpoint', 'Τάφος Βρασίδα', ARRAY['Ταφικό μνημείο', 'Υποσημείο αρχαιολογικού χώρου']::text[], ARRAY['Κλασική']::text[], '5ος αιώνας π.Χ., σε σύνδεση με τα γεγονότα του Πελοποννησιακού Πολέμου.', 'Κλασική περίοδος', 'Σήμερα αποτελεί αρχαιολογικό σημείο μέσα στην ευρύτερη Αμφίπολη.', 'Συνδέεται με τους κατοίκους της Αμφίπολης και τη μνήμη του Σπαρτιάτη στρατηγού Βρασίδα.', 'Ταφική και μνημονική χρήση για πρόσωπο που συνδέθηκε έντονα με την ιστορία της πόλης.', 'Ο Τάφος Βρασίδα είναι σημαντικό υποσημείο της Αμφίπολης, επειδή συνδέει τον αρχαιολογικό χώρο με ένα συγκεκριμένο ιστορικό πρόσωπο και με τον Πελοποννησιακό Πόλεμο. Δεν χρειάζεται να αντικαταστήσει την κύρια καρτέλα της Αμφίπολης, αλλά πρέπει να εμφανίζεται μέσα σε αυτήν ως συνδεδεμένο σημείο.', 'Από μνημείο ταφικής/ηρωικής μνήμης αποτελεί σήμερα αρχαιολογικό σημείο της Αμφίπολης.', 'easy', 'Πρόσβαση στην περιοχή της Αμφίπολης με όχημα και μικρή περιήγηση στον χώρο.', 'Αμφίπολη / Μακεδονία', ARRAY['Αμφίπολη', 'Τείχη Αμφίπολης', 'Αρχαιολογικό Μουσείο Αμφίπολης', 'Στρυμόνας']::text[], 'Φωτογραφία του σημείου/ταφικού χώρου ή σύνδεση με τον αρχαιολογικό χάρτη της Αμφίπολης.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['odysseus_amphipolis']::text[], ''),
  (39, 'archaeological-museum-nicopolis-subpoint', 'Αρχαιολογικό Μουσείο Νικόπολης', ARRAY['Μουσείο', 'Υποστηρικτικό σημείο επίσκεψης']::text[], ARRAY['Ρωμαϊκή', 'Παλαιοχριστιανική']::text[], 'Σύγχρονο μουσείο για την παρουσίαση ευρημάτων της αρχαίας Νικόπολης.', 'Σύγχρονη μουσειακή χρήση.', 'Δεν αφορά αρχαία κατασκευή αλλά σύγχρονη μουσειακή υποδομή.', 'Ελληνικό κράτος / αρμόδιες αρχαιολογικές υπηρεσίες.', 'Παρουσίαση και ερμηνεία των ευρημάτων της Νικόπολης.', 'Το Αρχαιολογικό Μουσείο Νικόπολης δεν είναι αρχαίο μνημείο, αλλά είναι πολύ χρήσιμο σημείο για την εφαρμογή, επειδή βοηθά τον επισκέπτη να καταλάβει την ιστορία της ρωμαϊκής πόλης και των παλαιοχριστιανικών μνημείων της περιοχής.', 'Σύγχρονη χρήση ως μουσείο.', 'easy', 'Εύκολη πρόσβαση με όχημα κοντά στη Νικόπολη και την Πρέβεζα.', 'Νικόπολη / Ρωμαϊκή Ήπειρος', ARRAY['Αρχαία Νικόπολη', 'Ρωμαϊκά τείχη', 'Ωδείο', 'Στάδιο Νικόπολης']::text[], 'Εξωτερική άποψη του μουσείου ή έκθεμα από τη Νικόπολη.', 'high', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['odysseus_nicopolis', 'nicopolis_museum_official']::text[], ''),
  (64, 'pylos-archaeological-museum-subpoint', 'Αρχαιολογικό Μουσείο Πύλου', ARRAY['Μουσείο', 'Υποστηρικτικό σημείο επίσκεψης']::text[], ARRAY['Μυκηναϊκή', 'Κλασική', 'Ελληνιστική', 'Ρωμαϊκή']::text[], 'Σύγχρονη μουσειακή υποδομή.', 'Σύγχρονη μουσειακή χρήση.', 'Δεν αφορά αρχαίο μνημείο αλλά μουσείο.', 'Ελληνικό κράτος / αρχαιολογικές υπηρεσίες.', 'Παρουσίαση ευρημάτων από την Πύλο και την ευρύτερη περιοχή της Μεσσηνίας.', 'Το Αρχαιολογικό Μουσείο Πύλου είναι χρήσιμο σημείο για τον χρήστη που επισκέπτεται το Ανάκτορο του Νέστορα και τα μυκηναϊκά μνημεία της περιοχής. Στην εφαρμογή καλό είναι να εμφανίζεται ως υποστηρικτικό σημείο και όχι ως αρχαίο μνημείο.', 'Σύγχρονη χρήση ως μουσείο.', 'easy', 'Εύκολη πρόσβαση μέσα ή κοντά στην Πύλο.', 'Πύλος / Μεσσηνία', ARRAY['Ανάκτορο του Νέστορα', 'Θολωτοί τάφοι Πύλου', 'Αρχαία Ίκλαινα']::text[], 'Εξωτερική όψη του μουσείου ή επιλεγμένο μυκηναϊκό έκθεμα.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['efa_messene_guide', 'odysseus_nestor_palace']::text[], ''),
  (68, 'royal-mycenaean-tholos-tomb-engianos', 'Βασιλικός μυκηναϊκός θολωτός τάφος Εγκλιανού', ARRAY['Θολωτός τάφος', 'Μυκηναϊκό ταφικό μνημείο', 'Υποσημείο']::text[], ARRAY['Μυκηναϊκή']::text[], 'Χρειάζεται ειδικότερη χρονολόγηση από αναλυτική πηγή· προσωρινά εντάσσεται στη γνωστή περίοδο του γονικού/ευρύτερου χώρου.', 'Αρχαιότητα, με ειδικότερη φάση ανάλογα με το μνημείο.', 'Η αρχική χρήση έχει πάψει και το σημείο σώζεται ως αρχαιολογικό κατάλοιπο ή υποσημείο.', 'Δεν είναι γνωστός συγκεκριμένος κτήτορας· συνδέεται με την τοπική κοινότητα ή τον ευρύτερο αρχαιολογικό χώρο.', 'Συμπληρωματική λειτουργία μέσα στον ευρύτερο αρχαιολογικό χώρο ή τοπικό μνημειακό σύνολο.', 'Ο βασιλικός μυκηναϊκός θολωτός τάφος κοντά στο Ανάκτορο του Νέστορα συμπληρώνει την εικόνα του μυκηναϊκού κέντρου της Πύλου. Είναι καλύτερο να παρουσιαστεί ως υποσημείο του ανακτόρου, επειδή βοηθά να φανεί η σχέση ανάμεσα στην ανακτορική εξουσία και τα ταφικά μνημεία της περιοχής.', 'Από λειτουργικό σημείο της αρχαιότητας αποτελεί σήμερα αρχαιολογικό κατάλοιπο ή σημείο ερμηνείας.', 'medium', 'Η πρόσβαση εξαρτάται από το αν το σημείο βρίσκεται μέσα σε οργανωμένο αρχαιολογικό χώρο ή σε πιο ανοιχτό/τοπικό τοπίο.', 'Πύλος / Ανάκτορο Νέστορα', ARRAY['Ανάκτορο του Νέστορα']::text[], 'Φωτογραφία του σημείου ή γενική άποψη του ευρύτερου χώρου: Ανάκτορο του Νέστορα.', 'medium', false, 'Imported from cleaned 217 dataset. Match method: kml-id (1.000).', ARRAY['efamess_tholotoi_nestoros_project', 'odysseus_nestor_palace']::text[], ''),
